// C/P Practice Test flashcards: original stand-alone cards that teach what the Chem/Phys questions of AAMC Practice
// Exams 1, 3, 4, 5 and 6 need (the pe1-cp … pe6-cp cards of data/qb-aamc-fl.js). TODAY's C/P flashcard step uses only
// these cards (masteryFlashPool in js/mastery.js).
// Every card names, in `from`, the Practice Exam card(s) whose question needs it; `aamc` and `disc` come from that card.
// Original wording, numbers and compounds only: no AAMC passage, question, number or answer choice is reproduced.
// Format: {id, s: topic tag, disc, aamc, q, choices: [4], ans: 0-3, exp, from: [src, …], how: {ask, know, steps, trap}, teach}
const CP_TEST_CARDS = [
  // ── Practice Exam 1 · Chem/Phys, Q1–10 ──
  // pe1-cp:1 (TLC on silica: the most polar compound moves least)
  {id:"cpt-pe1-01a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"A silica gel TLC plate is developed with hexane containing a little diethyl ether. Which compound will travel the shortest distance up the plate?",
    choices:["Cyclohexanol","Cyclohexanone","Chlorocyclohexane","Cyclohexane"],ans:0,
    exp:"Silica is a **polar stationary phase**; the eluent is mostly nonpolar. A compound that can donate **hydrogen bonds** to silica's surface groups sticks most and moves least. Only cyclohexanol has an **O–H** donor; the ketone is only an acceptor, and the chloride and the alkane interact weakly.",
    how:{ask:"Decide which compound sticks hardest to the polar silica, so it moves least.",
      know:"• Normal-phase TLC: **polar stationary phase** (silica, Si–OH) and a less polar mobile phase.\n• More polar compound → held more by silica → **smaller Rf**.\n• Strength of the hold: **O–H/N–H donors** > C=O or ether O (acceptors) > C–halogen > C–H only.",
      steps:[{text:"The eluent is mostly hexane, so the polar silica holds polar compounds back.",hl:"hexane containing a little diethyl ether"},
        {text:"Rank each compound by its strongest interaction with Si–OH.",calc:["Cyclohexanol: **O–H donor** (hydrogen bonds)","Cyclohexanone: C=O acceptor only","Chlorocyclohexane: weak dipole","Cyclohexane: London forces only"]},
        {text:"The ketone, the chloride and the alkane interact less with silica, so they move farther.",strike:["Cyclohexanone","Chlorocyclohexane","Cyclohexane"]},
        {text:"Answer: cyclohexanol, the only hydrogen-bond donor, moves the shortest distance."}],
      trap:"Choosing the heaviest compound: in TLC, polarity decides how far a spot moves, not molar mass."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"silica gel",note:"polar stationary phase"},{t:"hexane",note:"nonpolar eluent"},{t:"shortest distance",note:"smallest Rf"}]},
      {text:"**Polar sticks to polar.** Silica is covered with Si–OH groups, so polar compounds cling to it and lag behind."},
      {text:"**Find the hydrogen-bond donor.** An O–H group can donate a hydrogen bond to Si–OH; a C=O can only accept one.",calc:["O–H > C=O > C–Cl > C–H"]},
      {text:"**Rule to reuse:** on silica, the compound with the strongest polar groups (O–H or N–H first) has the smallest Rf."}]},
  {id:"cpt-pe1-01b",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"In normal-phase TLC on silica, a spot with a very low Rf is interacting most strongly with which part of the system?",
    choices:["The polar silica","The nonpolar eluent","The solvent vapor","The glass backing"],ans:0,
    exp:"A spot moves only while it is dissolved in the **mobile phase**. A low Rf means it spends most of its time **adsorbed on the polar silica** (the stationary phase).",
    how:{ask:"Link a low Rf to the phase that holds the compound back.",
      know:"• **Rf** = distance moved by the spot ÷ distance moved by the solvent front.\n• The **stationary phase** (silica) holds compounds back; the **mobile phase** carries them up.\n• Low Rf → mostly bound to the stationary phase.",
      steps:[{text:"A low Rf means the spot barely moved compared with the solvent.",hl:"a very low Rf"},
        {text:"The eluent carries compounds up; a compound that liked it would move far, not barely move.",strike:["The nonpolar eluent"]},
        {text:"Vapor and the plate's backing do not take part in the separation.",strike:["The solvent vapor","The glass backing"]},
        {text:"Answer: the polar silica, the stationary phase."}],
      trap:"Thinking the eluent \"pulls\" a low-Rf spot: a strong attraction to the mobile phase gives a high Rf."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"normal-phase TLC",note:"polar stationary phase"},{t:"very low Rf",note:"barely moved"}]},
      {text:"**Two phases compete.** The silica holds the compound in place; the eluent carries it upward."},
      {text:"**Read the Rf.** A spot that barely moved spent almost all its time stuck to the silica.",calc:["low Rf → stationary phase wins","high Rf → mobile phase wins"]},
      {text:"**Rule to reuse:** a low Rf means strong binding to the stationary phase; a high Rf means the compound prefers the mobile phase."}]},
  {id:"cpt-pe1-01c",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"Which bond in a molecule allows it to donate a hydrogen bond to the Si–OH groups on a silica surface?",
    choices:["O–H","C=O","C–O–C","C–Br"],ans:0,
    exp:"A hydrogen-bond **donor** needs an H bonded to N, O or F. Only **O–H** has one. C=O and an ether oxygen (C–O–C) have lone pairs, so they can only **accept** hydrogen bonds; C–Br does neither well.",
    how:{ask:"Find the group with an H attached to N, O or F.",
      know:"• **Donor**: H covalently bonded to N, O or F (N–H, O–H, F–H).\n• **Acceptor**: a lone pair on N, O or F (C=O, ethers, amines).\n• A C–H or C–halogen bond is not a hydrogen-bond donor.",
      steps:[{text:"To donate, the molecule must supply an H on an electronegative atom.",hl:"donate a hydrogen bond"},
        {text:"C=O and an ether oxygen have lone pairs but no H on oxygen: acceptors only.",strike:["C=O","C–O–C"]},
        {text:"Bromine is not N, O or F, and the bond has no H.",strike:["C–Br"]},
        {text:"Answer: O–H."}],
      trap:"Counting C=O as a donor because it is polar: polarity alone does not make a donor; an H on N, O or F does."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"donate a hydrogen bond",note:"needs an H on N, O or F"},{t:"Si–OH",note:"the surface's own O–H groups"}]},
      {text:"**Donor = H on N, O or F.** The H is very δ+ and can reach a lone pair on another atom."},
      {text:"**Check each bond.**",calc:["O–H: donor ✓","C=O: acceptor only","C–O–C: acceptor only","C–Br: neither"]},
      {text:"**Rule to reuse:** only N–H, O–H and F–H donate hydrogen bonds; C=O and ether oxygens can only accept them."}]},
  {id:"cpt-pe1-01d",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"A student spots equal volumes of one compound on chromatography paper, once from a concentrated solution and once from a dilute one. After development, how do the two spots compare?",
    choices:["Same Rf; bigger concentrated spot","Same Rf; bigger dilute spot","Higher Rf; bigger concentrated spot","Lower Rf; same spot size"],ans:0,
    exp:"How far a compound travels depends on how it divides between the stationary and mobile phases, which is a property of the compound, so both spots have the **same Rf**. Concentration only changes **how much** material is there, so the concentrated spot is **larger and darker**.",
    how:{ask:"Separate what sets the distance a compound moves from what sets the size of its spot.",
      know:"• Distance moved (Rf) is set by how strongly the compound binds the stationary phase compared with the mobile phase.\n• **Spot size** is set by the **amount** applied (concentration), not by the distance moved.",
      steps:[{text:"It is the same compound on the same paper and solvent.",hl:"spots equal volumes of one compound"},
        {text:"Same compound, same phases → same Rf, so a change in Rf is ruled out.",strike:["Higher Rf; bigger concentrated spot","Lower Rf; same spot size"]},
        {text:"More material in the concentrated sample makes its spot the larger one.",strike:["Same Rf; bigger dilute spot"]},
        {text:"Answer: same Rf; the concentrated spot is bigger."}],
      trap:"Thinking a stronger solution moves farther: concentration changes how much is there, not how far it travels."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"equal volumes of one compound",note:"same Rf expected"},{t:"concentrated",note:"more material"},{t:"dilute",note:"less material"}]},
      {text:"**Distance is a property of the compound.** It depends on how the compound shares itself between the paper's water and the solvent."},
      {text:"**Size is a property of the amount.** More material spreads into a bigger, darker spot.",calc:["Rf: same","spot size: concentrated > dilute"]},
      {text:"**Rule to reuse:** in chromatography, Rf is characteristic of the compound under fixed conditions; spot size only reflects how much was applied."}]},
  // pe1-cp:2 (the assumption behind a prebiotic-origin claim)
  {id:"cpt-pe1-02a",s:"Research Design & Reasoning",disc:"organic_chem",aamc:"5C",skill:"SIRS 3",from:["pe1-cp:2#1"],
    q:"A team concludes that amino acids arose on the primitive Earth, since passing sparks through methane and ammonia gave them in the lab. The argument requires that:",
    choices:["those gases were present then.","the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."],ans:0,
    exp:"A lab synthesis shows what **can** happen. To conclude it **did** happen on the early Earth, the **starting materials and conditions** (here methane, ammonia and electrical discharge) must have existed then. Yield, purity and a claim about all reactions do not bear on that.",
    how:{ask:"Find the unstated premise that must be true for the lab result to support the historical claim.",
      know:"• **Assumption**: a premise the conclusion needs but does not state; if it were false, the conclusion would fail.\n• A lab model of a past event supports the claim only if its **inputs and conditions** existed at that time.",
      steps:[{text:"The conclusion is about the early Earth; the evidence is from a lab.",hl:"amino acids arose on the primitive Earth"},
        {text:"Test each choice: if it were false, would the argument fail?",calc:["gases absent then → the lab result says nothing about then → fails","low yield → some still formed → stands"]},
        {text:"Yield, optical purity and all reactions are not needed for the conclusion.",strike:["the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."]},
        {text:"Answer: the gases must have been present on the early Earth."}],
      trap:"Choosing a detail about the experiment's quality; the gap is between the lab and the early Earth."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"on the primitive Earth",note:"the conclusion"},{t:"in the lab",note:"the evidence"},{t:"requires",note:"find the assumption"}]},
      {text:"**Split conclusion from evidence.** The evidence is a lab result; the conclusion is about the past."},
      {text:"**Bridge the gap.** For the lab to stand in for the early Earth, the same ingredients had to be there."},
      {text:"**Negate to test.** If the gases were absent, the argument collapses, so that is the assumption.",calc:["negate the choice → does the conclusion fail?"]},
      {text:"**Rule to reuse:** a lab model supports a claim about the past only if its starting materials and conditions existed then."}]},
  {id:"cpt-pe1-02b",s:"Research Design & Reasoning",disc:"organic_chem",aamc:"5C",skill:"SIRS 3",from:["pe1-cp:2#1"],
    q:"An unstated premise that must be true for a study's conclusion to hold is called:",
    choices:["an assumption","a confounding factor","a dependent variable","a null result"],ans:0,
    exp:"An **assumption** is a premise the argument needs but never states. A confounding factor is a third variable that distorts a relationship; a dependent variable is what is measured; a null result is a finding of no effect.",
    how:{ask:"Match the definition to the term for an unstated, required premise.",
      know:"• **Assumption**: unstated premise the conclusion depends on.\n• **Confounder**: a third variable linked to both cause and effect.\n• **Dependent variable**: the measured outcome.\n• **Null result**: no effect detected.",
      steps:[{text:"The definition stresses \"unstated\" and \"must be true\".",hl:"An unstated premise that must be true"},
        {text:"A confounder, a measured outcome and a no-effect finding are parts of a study's design or results, not hidden premises.",strike:["a confounding factor","a dependent variable","a null result"]},
        {text:"Answer: an assumption."}],
      trap:"Picking a confounding factor because it is also \"hidden\"; a confounder is a variable, not a premise of the argument."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"unstated premise",note:"not said aloud"},{t:"must be true",note:"needed by the conclusion"}]},
      {text:"**An argument has parts:** evidence, conclusion and the unstated links between them."},
      {text:"**Name the link.** The unstated link that must hold is the assumption; negate it and the conclusion falls."},
      {text:"**Rule to reuse:** an assumption is the unstated premise whose denial would break the conclusion."}]},
  // pe1-cp:3 (Rf measured from the baseline)
  {id:"cpt-pe1-03a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:3#1"],
    q:"A TLC baseline is 1.5 cm above the plate's lower edge. Measured from that edge, the solvent front is at 9.5 cm and a spot's center is at 5.5 cm. What is the retention factor (Rf)?",
    choices:["0.42","0.50","0.58","2.0"],ans:1,
    exp:"**Rf = spot distance ÷ solvent-front distance, both from the baseline.** Spot: 5.5 − 1.5 = 4.0 cm. Front: 9.5 − 1.5 = 8.0 cm. Rf = 4.0 ÷ 8.0 = **0.50**.",
    how:{ask:"Measure both distances from the baseline, then divide.",
      know:"**Rf = distance moved by the compound ÷ distance moved by the solvent front**, both measured from the **baseline** where the sample was spotted. Rf is between 0 and 1.",
      steps:[{text:"The distances are given from the edge, but the sample started at the baseline.",hl:"baseline is 1.5 cm above the plate's lower edge",fig:"cpt-tlc-plate"},
        {text:"Subtract the baseline from both readings.",calc:["spot: 5.5 − 1.5 = **4.0 cm**","front: 9.5 − 1.5 = **8.0 cm**"]},
        {text:"Divide.",calc:["Rf = 4.0 ÷ 8.0 = **0.50**"]},
        {text:"0.58 skips the baseline (5.5 ÷ 9.5), 0.42 subtracts it from only the spot, and 2.0 is inverted.",strike:["0.58","0.42","2.0"]},
        {text:"Answer: 0.50."}],
      trap:"Dividing the raw readings (5.5 ÷ 9.5 = 0.58): both distances must start at the baseline."},
    teach:[{text:"First, **find every number** and what it means.",marks:[{t:"1.5 cm",note:"where the sample started"},{t:"9.5 cm",note:"solvent front, from the edge"},{t:"5.5 cm",note:"spot, from the edge"}]},
      {text:"**Start at the baseline.** The race starts where the sample was spotted, not at the plate's edge.",calc:["spot: 5.5 − 1.5 = 4.0 cm","front: 9.5 − 1.5 = 8.0 cm"]},
      {text:"**Divide spot by front.**",calc:["Rf = 4.0 ÷ 8.0 = 0.50"]},
      {text:"**Rule to reuse:** Rf = (spot − baseline) ÷ (front − baseline), and it always falls between 0 and 1."}]},
  {id:"cpt-pe1-03b",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:3#1"],
    q:"A student reports an Rf value for a TLC spot. Within what range must any correctly calculated Rf fall?",
    choices:["0 to 1","1 to 10","−1 to 1","0 to 100"],ans:0,
    exp:"A spot can never travel farther than the solvent front that carries it, and it cannot move backward. So **Rf = spot distance ÷ front distance** lies **between 0 and 1**. A value above 1 means the distances were swapped or mismeasured.",
    how:{ask:"Use the definition of Rf to bound its value.",
      know:"**Rf = spot distance ÷ solvent-front distance.** The spot moves no farther than the front (≤ 1) and not below the baseline (≥ 0).",
      steps:[{text:"The spot is carried by the solvent, so it cannot pass the front.",hl:"correctly calculated Rf"},
        {text:"Distances are never negative, and the ratio never exceeds 1.",strike:["−1 to 1","1 to 10","0 to 100"]},
        {text:"Answer: 0 to 1."}],
      trap:"Reading Rf as a percent (0 to 100); it is a plain ratio."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Rf value",note:"a ratio of two distances"}]},
      {text:"**Top of the ratio ≤ bottom.** The spot rides on the solvent, so it never goes past the front."},
      {text:"**Bottom limit.** A spot that never left the baseline has Rf = 0.",calc:["0 ≤ Rf ≤ 1"]},
      {text:"**Rule to reuse:** every Rf lies between 0 and 1; a larger value means the ratio is inverted."}]},
  // pe1-cp:4 (E1 dehydration: which alkenes form directly from the carbocation)
  {id:"cpt-pe1-04a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1"],
    q:"In the E1 dehydration of an alcohol, the proton removed in the final step comes from:",
    choices:["an adjacent carbon.","the cationic carbon.","any carbon in the chain.","the departing water."],ans:0,
    exp:"In E1, water leaves to give a carbocation; a base then removes an **H⁺ from a carbon bonded to C⁺**. The new **C=C** forms between those two neighboring carbons, so the double bond always touches the former cationic carbon.",
    how:{ask:"Locate the H that leaves so the new C=C can form.",
      know:"• **E1**: protonate –OH → water leaves → **carbocation** → base removes an H⁺ from a **neighboring (β) carbon**.\n• The new C=C joins the cationic carbon and that neighbor.",
      steps:[{text:"The last step makes the C=C, which needs electrons from a C–H bond next to C⁺.",hl:"the final step",fig:"cpt-e1-beta"},
        {text:"Losing H⁺ from C⁺ itself would not create a C=C, and an H two or more carbons away cannot form a C=C to C⁺ in one step.",strike:["the cationic carbon.","any carbon in the chain."]},
        {text:"Water has already left; it is not the source of the eliminated H⁺.",strike:["the departing water."]},
        {text:"Answer: an adjacent carbon."}],
      trap:"Thinking any H in the molecule can leave; only an H on a carbon next to C⁺ gives a C=C in one step."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"E1 dehydration",note:"carbocation path"},{t:"final step",note:"loss of H⁺"}]},
      {text:"**Make the cation.** Acid protonates –OH; water leaves; C⁺ forms where the OH was."},
      {text:"**Form the C=C.** The electrons of a C–H bond on the next carbon swing in to make the double bond.",calc:["H–C–C⁺ → C=C + H⁺"]},
      {text:"**Rule to reuse:** in E1, the C=C always forms between the cationic carbon and a carbon directly bonded to it."}]},
  {id:"cpt-pe1-04b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1"],
    q:"3-Methylpentan-3-ol is heated with concentrated H₂SO₄. Which alkene is NOT formed directly from the carbocation?",
    choices:["(E)-3-Methylpent-2-ene","(Z)-3-Methylpent-2-ene","2-Ethylbut-1-ene","3-Methylpent-1-ene"],ans:3,
    exp:"Water leaves C3, giving a **tertiary cation at C3**. Its neighbors are C2, C4 (each in an ethyl group) and the methyl carbon. Loss of H⁺ from C2 or C4 gives 3-methylpent-2-ene, as **both E and Z** because the cation is planar; loss from the methyl gives 2-ethylbut-1-ene. **3-Methylpent-1-ene** has its C=C between C1 and C2, which does not touch C3, so it cannot form directly.",
    how:{ask:"List the carbons next to the cationic carbon; every direct alkene has its C=C touching C⁺.",
      know:"• E1: C⁺ forms where the OH was; the C=C forms between C⁺ and a **neighboring carbon** that loses H⁺.\n• The planar cation gives **both E and Z** isomers when the alkene can have them.\n• An alkene whose C=C does not include the old C–OH carbon needs a rearrangement first.",
      steps:[{text:"The OH is on C3, a tertiary carbon, so C⁺ forms at C3.",hl:"3-Methylpentan-3-ol"},
        {text:"Neighbors of C3 and the alkene each gives.",fig:"cpt-e1-cation",calc:["C2 or C4 → C=C at C2–C3: **3-methylpent-2-ene (E and Z)**","CH₃ on C3 → C=CH₂: **2-ethylbut-1-ene**"]},
        {text:"These three put the C=C on C3, so they form directly.",strike:["(E)-3-Methylpent-2-ene","(Z)-3-Methylpent-2-ene","2-Ethylbut-1-ene"]},
        {text:"Answer: 3-methylpent-1-ene; its C=C (C1–C2) does not include C3."}],
      trap:"Ruling out one of the E/Z pair: a planar cation can lose either neighboring H, so both geometric isomers form."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3-Methylpentan-3-ol",note:"OH on a 3° carbon"},{t:"H₂SO₄",note:"acid, heat: E1"},{t:"NOT formed directly",note:"find the odd alkene"}]},
      {text:"**Place the cation.** C⁺ sits on C3, where the OH was."},
      {text:"**Walk to each neighbor.** Each neighboring C–H can become the second carbon of the C=C.",calc:["C2/C4 → pent-2-ene (E and Z)","CH₃ → but-1-ene with an ethyl branch"]},
      {text:"**Spot the outsider.** A C=C at C1–C2 never touches C3.",calc:["3-methylpent-1-ene ✗"]},
      {text:"**Rule to reuse:** a direct E1 alkene always has the former C–OH carbon in its C=C."}]},
  {id:"cpt-pe1-04c",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#4"],
    q:"Why does the acid-catalyzed dehydration of a tertiary alcohol often give both the E and the Z alkene?",
    choices:["The cation is planar","The alcohol is chiral","Water is a strong base","The acid adds twice"],ans:0,
    exp:"The carbocation is **sp² and planar**, and the C–C bond to it can rotate. Rotation about the bond to C⁺ lets either H on the neighboring carbon line up with the empty p orbital, so the C=C can form with the groups on the **same side (Z)** or **opposite sides (E)**. Both isomers form; the more stable one is major.",
    how:{ask:"Explain why the intermediate does not fix the alkene's geometry.",
      know:"• A carbocation is **sp², trigonal planar**.\n• Rotation about the bond to C⁺ lets either neighboring H line up to leave.\n• So E1 gives **both E and Z** alkenes (E usually major).",
      steps:[{text:"Both isomers come from the same carbocation.",hl:"both the E and the Z alkene"},
        {text:"Chirality of the alcohol is lost once the planar cation forms; water is a weak base; the acid is a catalyst.",strike:["The alcohol is chiral","Water is a strong base","The acid adds twice"]},
        {text:"Answer: the cation is planar."}],
      trap:"Thinking E1 is stereospecific like E2; E1 passes through a flat cation, so geometry is not controlled."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"tertiary alcohol",note:"E1 via a cation"},{t:"E and the Z",note:"two geometries"}]},
      {text:"**Picture the cation.** C⁺ is flat, with its three groups in one plane."},
      {text:"**Either H can leave.** Rotation puts one H or another in line, so the groups end up on the same or opposite sides.",calc:["same side → Z","opposite sides → E"]},
      {text:"**Rule to reuse:** E1 through a planar carbocation gives both E and Z alkenes, with the more stable E usually major."}]},
  {id:"cpt-pe1-04d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#2"],
    q:"Each alcohol is warmed with the same concentrated acid. Which one dehydrates fastest?",
    choices:["2-Methylbutan-2-ol","Pentan-1-ol","Pentan-2-ol","3-Methylbutan-1-ol"],ans:0,
    exp:"Acid-catalyzed dehydration goes by **E1**: the slow step is water leaving to form a **carbocation**. The more stable the cation, the faster it forms: **3° > 2° > 1°**. 2-Methylbutan-2-ol has its OH on a tertiary carbon, so it dehydrates fastest; pentan-2-ol (2°) is slower, and the two primary alcohols are slowest.",
    how:{ask:"Classify each alcohol's OH carbon, then rank by the stability of the carbocation it would form.",
      know:"• E1 dehydration: protonate –OH → water leaves (**slow step**) → carbocation → lose H⁺.\n• A faster slow step means a more stable cation: **3° > 2° > 1°**.\n• Classify by counting carbons bonded to the C–OH carbon: 3 = tertiary, 2 = secondary, 1 = primary.",
      steps:[{text:"Same acid, same temperature: only the alcohol's structure changes the rate.",hl:"the same concentrated acid"},
        {text:"Classify each OH carbon.",calc:["2-methylbutan-2-ol: C2 bonded to 3 carbons → **3°**","pentan-2-ol: **2°**","pentan-1-ol and 3-methylbutan-1-ol: **1°**"]},
        {text:"Primary alcohols would have to form an unstable 1° cation, so they are slowest.",strike:["Pentan-1-ol","3-Methylbutan-1-ol"]},
        {text:"A 2° cation forms more slowly than a 3° cation.",strike:["Pentan-2-ol"]},
        {text:"Answer: 2-methylbutan-2-ol, the tertiary alcohol."}],
      trap:"Ranking by branching anywhere in the chain: 3-methylbutan-1-ol is branched, but its OH is on a primary carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"same concentrated acid",note:"only structure differs"},{t:"dehydrates fastest",note:"easiest carbocation"}]},
      {text:"**Find the slow step.** In E1 dehydration, water leaving to make the carbocation sets the rate."},
      {text:"**Rank the cations.** More alkyl groups on C⁺ stabilize it.",calc:["3° > 2° > 1°"]},
      {text:"**Classify the OH carbon.** Count its carbon neighbors; 2-methylbutan-2-ol has three."},
      {text:"**Rule to reuse:** tertiary alcohols dehydrate most easily because they form the most stable carbocation; primary alcohols dehydrate slowest."}]},
  {id:"cpt-pe1-04e",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1","pe1-cp:4#3","pe1-cp:4#4"],
    q:"Which statement about the acid-catalyzed dehydration of 1-methylcyclopentanol is true?",
    choices:["One water is lost, via a carbocation","Two waters are lost in one step","The alkene geometry is set by the alcohol","The C–H bond breaks before the C–O bond"],ans:0,
    exp:"The OH is protonated and leaves as **one water molecule**, giving a **planar carbocation**; then H⁺ is lost from a neighboring carbon. Because the flat cation forgets the alcohol's 3D arrangement, the reaction is **not stereospecific**, and the C–O bond breaks first (it is E1, not a concerted E2).",
    how:{ask:"Judge each statement against the E1 mechanism: what leaves, in what order, through what intermediate.",
      know:"• **E1 dehydration**: ROH + H⁺ → ROH₂⁺ → **R⁺ + H₂O** (one water) → alkene + H⁺.\n• The C–O bond breaks **first**; the C–H bond breaks last.\n• The carbocation is planar, so the alcohol's geometry is lost: **not stereospecific**.",
      steps:[{text:"Write the E1 steps for this tertiary alcohol.",hl:"acid-catalyzed dehydration",calc:["R–OH + H⁺ → R–OH₂⁺","R–OH₂⁺ → **R⁺ + H₂O**","R⁺ → alkene + H⁺"]},
        {text:"Only one water molecule leaves, and the steps are separate, not one concerted step.",strike:["Two waters are lost in one step"]},
        {text:"The planar cation does not remember the alcohol's arrangement, so the alcohol does not set the geometry.",strike:["The alkene geometry is set by the alcohol"]},
        {text:"Water leaves before H⁺ is removed, so the C–O bond breaks first.",strike:["The C–H bond breaks before the C–O bond"]},
        {text:"Answer: one water is lost, via a carbocation."}],
      trap:"Treating dehydration like E2 (one step, stereospecific): with acid and heat, alcohols go through a carbocation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"acid-catalyzed dehydration",note:"E1"},{t:"1-methylcyclopentanol",note:"tertiary alcohol"}]},
      {text:"**Count the waters.** One OH leaves as one H₂O."},
      {text:"**Order the bonds.** C–O breaks to make C⁺; the C–H breaks after.",calc:["C–O first → C⁺ → C–H last"]},
      {text:"**Flat cation, no memory.** The planar C⁺ can lose an H from either side, so the starting geometry does not carry over."},
      {text:"**Rule to reuse:** acid-catalyzed dehydration loses one water through a carbocation, so it is stepwise and not stereospecific."}]},
  // pe1-cp:5 (activated carboxyl + amine → amide; amide C=O in the IR)
  {id:"cpt-pe1-05a",s:"Amino Acids & Proteins",disc:"organic_chem",aamc:"5C",skill:"SIRS 1",from:["pe1-cp:5#1"],
    q:"The activated carboxyl group of glycine reacts with the amino group of valine, releasing one water molecule. Which linkage forms?",
    choices:["Amide","Ester","Anhydride","Ether"],ans:0,
    exp:"Carboxyl + **amine** → **amide** (a peptide bond), with loss of H₂O. Carboxyl + alcohol gives an ester; carboxyl + carboxyl gives an anhydride; an ether needs two alcohols.",
    how:{ask:"Name the bond made when a carboxyl group condenses with an amine.",
      know:"• **Condensation** joins two groups and releases H₂O.\n• RCOOH + R′NH₂ → **amide** (RCONHR′); RCOOH + R′OH → ester; RCOOH + RCOOH → anhydride.\n• Between amino acids the amide is the **peptide bond**.",
      steps:[{text:"The partner is the amino group, an amine.",hl:"amino group of valine"},
        {text:"Ester and ether need an alcohol O; an anhydride needs a second carboxyl group.",strike:["Ester","Ether","Anhydride"]},
        {text:"Answer: an amide (peptide) bond."}],
      trap:"Choosing ester because water is lost; esters also lose water, but only when the partner is an alcohol."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"carboxyl group",note:"acyl donor"},{t:"amino group",note:"N nucleophile"},{t:"releasing one water",note:"condensation"}]},
      {text:"**Match the partner.** The nucleophile here is nitrogen, from the amine."},
      {text:"**Build the bond.**",calc:["R–COOH + H₂N–R′ → R–CO–NH–R′ + H₂O"]},
      {text:"**Rule to reuse:** carboxyl + amine → amide (peptide bond); carboxyl + alcohol → ester."}]},
  // pe1-cp:6 (SN2 rate: steric crowding at and next to the reacting carbon)
  {id:"cpt-pe1-06a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:6#1"],
    q:"Which statement gives the order of SN2 reaction rates for alkyl halides with the same leaving group?",
    choices:["Methyl fastest, tertiary slowest","Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest","Primary fastest, tertiary slowest"],ans:0,
    exp:"SN2 needs **backside attack** on the carbon bearing the leaving group. Each added alkyl group crowds that side: **methyl > 1° > 2° ≫ 3°** (tertiary essentially does not react by SN2).",
    how:{ask:"Rank substrates by how crowded the backside of the reacting carbon is.",
      know:"• **SN2**: one step, the nucleophile attacks opposite the leaving group.\n• Steric order: **methyl > primary > secondary ≫ tertiary**.\n• The reverse order (3° fastest) belongs to SN1, which goes through a carbocation.",
      steps:[{text:"SN2 rate depends on access to the carbon's backside.",hl:"order of SN2 reaction rates",fig:"cpt-sn2-backside"},
        {text:"Tertiary-first is the SN1 order; secondary-first fits neither.",strike:["Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest"]},
        {text:"Primary is fast but methyl, with no alkyl groups, is faster still.",strike:["Primary fastest, tertiary slowest"]},
        {text:"Answer: methyl fastest, tertiary slowest."}],
      trap:"Using carbocation stability (3° > 2° > 1°); that ranks SN1 rates, not SN2."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"SN2",note:"backside attack, one step"},{t:"same leaving group",note:"only sterics differ"}]},
      {text:"**Picture the attack.** The nucleophile must reach the carbon from behind the leaving group."},
      {text:"**Count the blockers.** Each alkyl group on that carbon gets in the way.",calc:["CH₃–X: 0 → fastest","1°: 1","2°: 2","3°: 3 → no SN2"]},
      {text:"**Rule to reuse:** SN2 rates run methyl > 1° > 2° ≫ 3°, the reverse of SN1."}]},
  {id:"cpt-pe1-06d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:6#1"],
    q:"With HBr, a secondary alcohol substitutes more slowly than a primary alcohol by SN2. Where is the crowding that slows the secondary alcohol?",
    choices:["At the OH-bearing carbon","At the protonated oxygen","At the incoming bromide","At the solvent molecules"],ans:0,
    exp:"In SN2, Br⁻ attacks the **carbon bonded to the leaving group** (–OH₂⁺) from the back side. A secondary carbon carries two alkyl groups that crowd that back side; a primary carbon carries one. The oxygen is the leaving group, on the other side, so crowding there does not matter.",
    how:{ask:"Find the atom the nucleophile attacks, then see what crowds it.",
      know:"• SN2: the nucleophile attacks the **carbon** that holds the leaving group, from the side opposite it.\n• Groups on **that carbon** block the attack, so the SN2 rate is methyl > 1° > 2°, and 3° does not react by SN2.\n• With an alcohol and HX, the leaving group is –OH₂⁺; the oxygen is not attacked.",
      steps:[{text:"The nucleophile is Br⁻; the leaving group is water on the protonated alcohol.",hl:"secondary alcohol substitutes more slowly",fig:"cpt-sn2-crowded"},
        {text:"Br⁻ bonds to carbon, not oxygen, so the oxygen's surroundings do not set the rate.",strike:["At the protonated oxygen"]},
        {text:"The nucleophile and solvent are the same for both alcohols, so they cannot explain the difference.",strike:["At the incoming bromide","At the solvent molecules"]},
        {text:"Answer: at the carbon bearing the OH, which has two alkyl groups in a secondary alcohol."}],
      trap:"Looking at the oxygen because the –OH is the group that changes: SN2 attack, and its crowding, happen at the carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"secondary alcohol",note:"two alkyl groups on C–OH"},{t:"SN2",note:"backside attack on carbon"}]},
      {text:"**Find the target.** In SN2 the nucleophile attacks the carbon that holds the leaving group."},
      {text:"**Count the blockers on that carbon.**",calc:["1° carbon: 1 alkyl group","2° carbon: 2 alkyl groups → slower","3° carbon: 3 → no SN2"]},
      {text:"**Rule to reuse:** SN2 slows with crowding at the carbon being attacked (methyl > 1° > 2°, no 3°), not at the leaving group."}]},
  // pe1-cp:7 (carbocation rearrangement in alcohol + HX)
  {id:"cpt-pe1-07a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#1"],
    q:"During the reaction of an alcohol with HBr, a secondary carbocation shifts a hydride from the next carbon to become tertiary. Why does this shift occur?",
    choices:["The 3° cation is more stable","The 2° cation is more stable","Hydride is a good leaving group","Bromide prefers 2° carbons"],ans:0,
    exp:"Alkyl groups **donate electron density** (hyperconjugation and induction) to C⁺, so **3° > 2° > 1°** in stability. A 1,2-hydride shift moves the + charge to the neighboring carbon when that carbon becomes a **more stable** cation.",
    how:{ask:"Explain what drives a carbocation to rearrange.",
      know:"• Carbocation stability: **3° > 2° > 1° > methyl** (alkyl groups donate electron density).\n• **1,2-hydride or 1,2-methyl shift**: a group on the next carbon moves over with its bonding pair, moving C⁺ to that carbon.\n• Shifts happen when the new cation is more stable.",
      steps:[{text:"The shift turns a 2° cation into a 3° one.",hl:"a secondary carbocation shifts a hydride",fig:["cpt-shift-2","cpt-shift-3"]},
        {text:"A 2° cation is less stable than a 3°, so it would not form at the 3° cation's expense.",strike:["The 2° cation is more stable"]},
        {text:"The hydride moves within the ion; it does not leave. Bromide adds wherever the cation ends up.",strike:["Hydride is a good leaving group","Bromide prefers 2° carbons"]},
        {text:"Answer: the 3° cation is more stable."}],
      trap:"Thinking the nucleophile directs the shift; the cation rearranges first, driven only by its own stability."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"secondary carbocation",note:"less stable"},{t:"hydride",note:"H with its two electrons"},{t:"tertiary",note:"more stable"}]},
      {text:"**Rank cations.** More alkyl groups on C⁺ spread the charge.",calc:["3° > 2° > 1° > CH₃⁺"]},
      {text:"**Move downhill.** The H on the next carbon slides over with its electron pair, leaving C⁺ on the more substituted carbon."},
      {text:"**Rule to reuse:** a carbocation shifts H or CH₃ from a neighboring carbon whenever that makes a more stable cation."}]},
  {id:"cpt-pe1-07b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#2"],
    q:"3,3-Dimethylbutan-2-ol reacts with HBr. Which product can form without a methyl shift in the carbocation?",
    choices:["2-Bromo-3,3-dimethylbutane","2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"],ans:0,
    exp:"Loss of water from C2 leaves a **secondary cation on C2**. Br⁻ adding there gives **2-bromo-3,3-dimethylbutane** directly. C3 is quaternary (no H), so a **1,2-methyl shift** from C3 makes a 3° cation at C3; that cation gives 2-bromo-2,3-dimethylbutane, 2,3-dimethylbut-2-ene and 2,3-dimethylbut-1-ene.",
    how:{ask:"Find the product whose new group sits on the carbon that held the OH, with the carbon skeleton unchanged.",
      know:"• C⁺ forms where the OH was; Br⁻ there = direct product.\n• A methyl shift moves C⁺ to the next carbon and rearranges the skeleton (the methyl changes carbons).\n• Products with Br on a carbon that never held the OH, a C=C that does not include that carbon, or a changed branching pattern come from the shifted cation.",
      steps:[{text:"The OH is on C2; C3 carries two methyls and no H.",hl:"3,3-Dimethylbutan-2-ol"},
        {text:"Direct path: Br⁻ adds to C2, keeping both methyls on C3.",calc:["CH₃–CH(Br)–C(CH₃)₂–CH₃ = **2-bromo-3,3-dimethylbutane**"]},
        {text:"A 2,3-dimethyl skeleton means one methyl moved from C3 to C2.",strike:["2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"]},
        {text:"Answer: 2-bromo-3,3-dimethylbutane."}],
      trap:"Choosing an alkene because elimination seems \"direct\"; here every listed alkene has the 2,3-dimethyl skeleton of the shifted cation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3,3-Dimethylbutan-2-ol",note:"OH on C2, quaternary C3"},{t:"HBr",note:"cation path"},{t:"without a methyl shift",note:"direct product"}]},
      {text:"**Place the cation.** C⁺ forms on C2, where the OH was."},
      {text:"**Compare skeletons.** Before the shift: two methyls on C3. After: one on C2 and one on C3.",calc:["3,3-dimethyl → unshifted","2,3-dimethyl → shifted"]},
      {text:"**Pick the unshifted one.** Br on C2 with the 3,3-dimethyl skeleton."},
      {text:"**Rule to reuse:** a product whose groups or branches moved to a carbon that never held the OH came from a rearranged cation."}]},
  {id:"cpt-pe1-07c",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#3"],
    q:"An alcohol reacts with HBr, and the product's Br sits on the carbon next to the one that held the OH. What does this most likely indicate?",
    choices:["A 1,2-shift occurred","Direct SN2 attack occurred","The alcohol was tertiary","Two bromides were added"],ans:0,
    exp:"Without rearrangement, Br⁻ bonds to the carbon that **held the OH** (where C⁺ formed, or where SN2 attack occurs). Br on the **neighboring** carbon means the positive charge moved there first by a **1,2-hydride or 1,2-methyl shift** (elimination followed by re-addition of HBr can give the same result, but a 1,2-shift is the usual cause).",
    how:{ask:"Decide what moved the reactive site off the original C–OH carbon.",
      know:"• Direct substitution (SN1 or SN2) puts Br on the carbon that held the OH.\n• A **1,2-shift** moves C⁺ to the next carbon, so Br ends up there.",
      steps:[{text:"The Br is one carbon away from where the OH was.",hl:"the carbon next to the one that held the OH"},
        {text:"SN2 puts Br exactly where the OH left.",strike:["Direct SN2 attack occurred"]},
        {text:"A tertiary alcohol or a second Br does not move the site of attack.",strike:["The alcohol was tertiary","Two bromides were added"]},
        {text:"Answer: a 1,2-shift occurred."}],
      trap:"Assuming the nucleophile can wander; Br⁻ bonds where the cation is, so a moved Br means a moved cation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"carbon next to the one that held the OH",note:"group on a new carbon"}]},
      {text:"**Where should Br go?** Directly, it replaces the OH on the same carbon."},
      {text:"**Explain the move.** The cation shifted one carbon over before Br⁻ arrived.",calc:["C2⁺ → (H or CH₃ shift) → C3⁺ → C3–Br"]},
      {text:"**Rule to reuse:** a new group on a carbon that never held the leaving group is the fingerprint of a carbocation rearrangement."}]},
  // pe1-cp:8 (GC elution order follows volatility)
  {id:"cpt-pe1-08a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#1"],
    q:"In gas chromatography with a nonpolar column, which compound in a mixture generally reaches the detector first?",
    choices:["The lowest-boiling","The highest-boiling","The most hydrogen-bonded","The most massive"],ans:0,
    exp:"In GC the sample is vaporized and carried by an inert gas. A compound that **stays in the gas phase** most (the most **volatile**, lowest boiling point) spends the least time dissolved in the column's liquid and **elutes first**.",
    how:{ask:"Link elution order in GC to volatility.",
      know:"• **GC**: mobile phase = carrier gas; stationary phase = a liquid film in the column.\n• Most volatile (lowest boiling point) → mostly in the gas → **elutes first**.\n• Boiling point rises with stronger intermolecular forces and larger size.",
      steps:[{text:"The carrier gas moves only the molecules that are in the vapor.",hl:"reaches the detector first"},
        {text:"High boiling point, strong hydrogen bonding and large mass all keep a compound in the column longer.",strike:["The highest-boiling","The most hydrogen-bonded","The most massive"]},
        {text:"Answer: the lowest-boiling compound."}],
      trap:"Picking by polarity or mass alone: on a nonpolar GC column, volatility (boiling point) sets the elution order."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"gas chromatography",note:"gas mobile phase"},{t:"first",note:"spends most time as gas"}]},
      {text:"**Only gas moves.** A molecule advances only while it is in the vapor."},
      {text:"**Volatile wins.** The lowest boiling point means the most time in the vapor.",calc:["low bp → elutes first","high bp → elutes last"]},
      {text:"**Rule to reuse:** in GC, compounds come off in order of increasing boiling point."}]},
  {id:"cpt-pe1-08b",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#2"],
    q:"Which of these three-carbon compounds has the lowest boiling point?",
    choices:["Propane","Propanal","Propan-1-ol","1-Chloropropane"],ans:0,
    exp:"Propane (44 g/mol) has only **London dispersion forces** and the smallest mass. Propanal and 1-chloropropane add **dipole–dipole** forces, and propan-1-ol adds **hydrogen bonding**, so propane boils lowest (about −42 °C).",
    how:{ask:"Rank the compounds by their strongest intermolecular force, then by size.",
      know:"• Intermolecular forces: **London < dipole–dipole < hydrogen bonding**.\n• London forces grow with molar mass and surface area.\n• Weakest forces → lowest boiling point → most volatile.",
      steps:[{text:"All four have three carbons, so their functional groups decide.",hl:"three-carbon compounds"},
        {text:"Strongest force in each.",calc:["propane: London only","propanal: dipole–dipole","1-chloropropane: dipole–dipole","propan-1-ol: **hydrogen bonding**"]},
        {text:"Each polar compound has stronger forces than the alkane.",strike:["Propanal","Propan-1-ol","1-Chloropropane"]},
        {text:"Answer: propane."}],
      trap:"Thinking 1-chloropropane boils lowest because it cannot hydrogen bond: its dipole and larger mass (78.5 vs 44 g/mol) put it near 47 °C, far above propane."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"three-carbon",note:"similar size"},{t:"lowest boiling point",note:"weakest forces"}]},
      {text:"**Name each force.** Alkane: London. C=O or C–Cl: dipole–dipole. O–H: hydrogen bonding."},
      {text:"**Weakest boils first.**",calc:["propane < propanal ≈ 1-chloropropane < propan-1-ol"]},
      {text:"**Rule to reuse:** with similar sizes, an alkane boils lowest and an alcohol highest, because hydrogen bonding is the strongest force."}]},
  {id:"cpt-pe1-08c",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#3"],
    q:"Pentan-1-ol boils about 100 °C higher than pentane. Which intermolecular force accounts for most of this difference?",
    choices:["Hydrogen bonding","London dispersion","Ion–dipole attraction","Covalent bonding"],ans:0,
    exp:"Both molecules have five carbons, so their **London** forces are similar. The O–H group of pentan-1-ol lets its molecules **hydrogen bond** to each other, the strongest intermolecular force between neutral molecules, which raises the boiling point most.",
    how:{ask:"Find the force the alcohol has that the alkane lacks.",
      know:"• **Hydrogen bonding** (O–H, N–H, F–H with a lone pair on N, O or F) is the strongest force between neutral molecules.\n• Ion–dipole forces need ions; covalent bonds are within molecules, not between them.",
      steps:[{text:"Same carbon count, so the difference comes from the –OH group.",hl:"Pentan-1-ol"},
        {text:"London forces are about equal for the two molecules.",strike:["London dispersion"]},
        {text:"There are no ions, and boiling does not break covalent bonds.",strike:["Ion–dipole attraction","Covalent bonding"]},
        {text:"Answer: hydrogen bonding."}],
      trap:"Choosing covalent bonding: boiling separates molecules; it does not break bonds inside them."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Pentan-1-ol",note:"has O–H"},{t:"pentane",note:"London only"},{t:"100 °C higher",note:"a big force difference"}]},
      {text:"**Cancel what is shared.** Both have five carbons, so their London forces are similar."},
      {text:"**Find what is new.** The O–H group lets alcohol molecules hydrogen bond to each other."},
      {text:"**Rule to reuse:** an O–H or N–H group raises the boiling point far more than added mass does, because of hydrogen bonding."}]},
  {id:"cpt-pe1-08d",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#3"],
    q:"A mixture of pent-1-ene, 1-chloropentane and pentan-1-ol is run on a nonpolar gas chromatography column. In what order do they reach the detector?",
    choices:["Alkene, then chloride, then alcohol","Alcohol, then chloride, then alkene","Chloride, then alkene, then alcohol","Alkene, then alcohol, then chloride"],ans:0,
    exp:"Lowest boiling point first. Pent-1-ene has only London forces (bp ≈ 30 °C). 1-Chloropentane adds a C–Cl dipole and more mass (bp ≈ 108 °C). Pentan-1-ol **hydrogen-bonds** (bp ≈ 138 °C), so it comes out **last**.",
    how:{ask:"Rank the three by intermolecular forces, which sets their boiling points and so their GC order.",
      know:"• GC elutes in order of increasing boiling point.\n• Alkene: London only → most volatile.\n• Alkyl halide: dipole–dipole plus London → middle.\n• Alcohol: hydrogen bonding → least volatile, last.",
      steps:[{text:"All three have five carbons, so the functional group decides.",hl:"pent-1-ene, 1-chloropentane and pentan-1-ol",calc:["pent-1-ene: London → bp ≈ 30 °C","1-chloropentane: dipole → bp ≈ 108 °C","pentan-1-ol: H-bonding → bp ≈ 138 °C"]},
        {text:"The alcohol hydrogen-bonds, so it cannot come out first or second.",strike:["Alcohol, then chloride, then alkene","Alkene, then alcohol, then chloride"]},
        {text:"The alkene is more volatile than the chloride, so it comes out before it.",strike:["Chloride, then alkene, then alcohol"]},
        {text:"Answer: alkene, then chloride, then alcohol."}],
      trap:"Ordering by molar mass alone: the alcohol is lighter than the chloride but comes out after it, because it hydrogen-bonds."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"nonpolar gas chromatography column",note:"order by boiling point"},{t:"reach the detector",note:"elution order"}]},
      {text:"**Name each force.** C=C: London only. C–Cl: a dipole. O–H: hydrogen bonding."},
      {text:"**Weakest forces leave first.**",calc:["alkene < alkyl halide < alcohol"]},
      {text:"**Rule to reuse:** in GC, an alkene beats an alkyl halide of the same chain, and an alcohol, which hydrogen-bonds, comes out last."}]},
  // pe1-cp:9 (rate law → SN2 → inversion, and the R/S label)
  {id:"cpt-pe1-09b",s:"Stereochemistry",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#1","pe1-cp:9#2"],
    q:"(R)-2-Chlorobutane reacts by SN2 with sodium methanethiolate, CH₃SNa. What configuration does the product have?",
    choices:["(S) only","(R) only","Racemic mixture","Meso compound"],ans:0,
    exp:"SN2 gives **inversion**. The –SCH₃ group (first atom S, 16) now ranks **first**, just as Cl did, and the order of the others (ethyl > methyl > H) is unchanged. Inverting the 3D arrangement with the same priority order flips the label: **R → S**.",
    how:{ask:"Apply inversion, then check whether the priorities changed.",
      know:"• **SN2 → inversion** of the 3D arrangement; no carbocation, so no racemization.\n• **CIP priority** by atomic number of the first atom: S (16) and Cl (17) both outrank C (6) and H (1).\n• If the new group has the same rank as the old one, inversion switches R ↔ S.",
      steps:[{text:"The reaction is SN2, so the configuration inverts.",hl:"reacts by SN2",fig:"cpt-sn2-backside"},
        {text:"Priorities before and after.",calc:["before: Cl > ethyl > methyl > H","after: **SCH₃** > ethyl > methyl > H"]},
        {text:"Same order, inverted geometry, so the label changes; SN2 does not racemize, and the product has one stereocenter.",strike:["(R) only","Racemic mixture","Meso compound"]},
        {text:"Answer: (S) only."}],
      trap:"Keeping the label R: inversion with unchanged priorities always switches the descriptor."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"(R)-2-Chlorobutane",note:"starting label"},{t:"SN2",note:"inversion"},{t:"CH₃SNa",note:"S nucleophile"}]},
      {text:"**Flip the umbrella.** The nucleophile enters opposite Cl; the other three groups turn inside out."},
      {text:"**Re-rank.** S still outranks every carbon, just as Cl did.",calc:["rank order unchanged → R becomes S"]},
      {text:"**Rule to reuse:** SN2 inverts the center; if the entering group takes the leaving group's priority rank, R and S swap."}]},
  {id:"cpt-pe1-09c",s:"Stereochemistry",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#2"],
    q:"Which substituent on a stereocenter has the highest Cahn–Ingold–Prelog priority?",
    choices:["–SH","–OH","–NH₂","–CH₂Br"],ans:0,
    exp:"CIP priority is decided by the **atomic number of the first atom**: S (16) > O (8) > N (7) > C (6). The bromine in –CH₂Br is one atom farther out, so it does not count until the first atoms tie.",
    how:{ask:"Compare only the atoms bonded directly to the stereocenter.",
      know:"• **CIP rule 1**: higher atomic number of the first atom = higher priority.\n• Look farther out only when the first atoms are the same.\n• S 16, O 8, N 7, C 6, H 1.",
      steps:[{text:"First atoms: S, O, N and C.",hl:"highest Cahn–Ingold–Prelog priority"},
        {text:"O, N and the carbon of –CH₂Br all have lower atomic numbers than S; Br is not the first atom.",strike:["–OH","–NH₂","–CH₂Br"]},
        {text:"Answer: –SH."}],
      trap:"Ranking –CH₂Br first because Br is heavy; priority is decided at the first atom, which is carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"highest Cahn–Ingold–Prelog priority",note:"compare first atoms"}]},
      {text:"**List the first atoms.**",calc:["–SH: S (16)","–OH: O (8)","–NH₂: N (7)","–CH₂Br: C (6)"]},
      {text:"**Highest atomic number wins.** S beats the rest."},
      {text:"**Rule to reuse:** CIP priority is set by the first atom's atomic number; go farther out only to break a tie."}]},
  {id:"cpt-pe1-09e",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#3"],
    q:"3-Bromohexane reacts with sodium hydrosulfide, NaSH, by SN2. What is the name of the substitution product?",
    choices:["Hexane-3-thiol","Pentane-3-thiol","Hexane-1-thiol","Heptane-3-thiol"],ans:0,
    exp:"SN2 swaps the leaving group for the nucleophile **on the same carbon** and changes no C–C bond. The chain keeps its **6 carbons** and the SH lands on **C3**, where Br was: **hexane-3-thiol**.",
    how:{ask:"Count the product's carbon chain and locate the new group.",
      know:"• Substitution replaces X with Nu on the **same carbon**; no carbons are added or removed (HS⁻ brings no carbon).\n• Name: chain length (hex = 6) + position + suffix (-thiol for SH).\n• Number the chain so the group gets the lowest locant.",
      steps:[{text:"The substrate's chain and the leaving group's position.",hl:"3-Bromohexane",calc:["hexane = **6 carbons**","Br on **C3**"]},
        {text:"HS⁻ replaces Br on C3; the chain is untouched.",calc:["C₆ chain, SH on C3 → **hexane-3-thiol**"]},
        {text:"Five or seven carbons would mean a carbon was lost or gained, which SN2 with HS⁻ cannot do.",strike:["Pentane-3-thiol","Heptane-3-thiol"]},
        {text:"SN2 does not move the group to the chain's end.",strike:["Hexane-1-thiol"]},
        {text:"Answer: hexane-3-thiol."}],
      trap:"Miscounting the chain after drawing the product: the nucleophile replaces one atom, so the carbon count stays the same."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3-Bromohexane",note:"6 C, Br on C3"},{t:"NaSH",note:"HS⁻, no carbon"},{t:"SN2",note:"same carbon"}]},
      {text:"**Count the chain.** Hex- means 6 carbons, and nothing in HS⁻ adds a carbon."},
      {text:"**Keep the position.** SN2 puts the new group where the leaving group was.",calc:["Br on C3 → SH on C3"]},
      {text:"**Name it.**",calc:["hexane + 3 + thiol → hexane-3-thiol"]},
      {text:"**Rule to reuse:** after a substitution, the product keeps the substrate's carbon chain and the new group's position; only the group's name changes."}]},
  // pe1-cp:10 (Fischer esterification: the alcohol oxygen stays in the ester)
  {id:"cpt-pe1-10a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#1"],
    q:"In the acid-catalyzed esterification of acetic acid with ethanol, the oxygen joining the acyl carbon to the ethyl group comes from:",
    choices:["the ethanol","the acetic acid","the acid catalyst","the water"],ans:0,
    exp:"In Fischer esterification the **alcohol's oxygen is the nucleophile**: it attacks the protonated carbonyl carbon. Later an –OH from the **acid** leaves as water. So the bridging –O– of ethyl acetate is the **ethanol** oxygen.",
    how:{ask:"Identify the nucleophile, whose oxygen is kept in the product.",
      know:"• **Fischer esterification**: RCOOH + R′OH ⇌ RCOOR′ + H₂O (acid catalyst).\n• The **alcohol O attacks** the carbonyl carbon; **water leaves from the acid** side.\n• So the ester's C–O–R′ oxygen comes from the alcohol.",
      steps:[{text:"The bridging oxygen links the acyl carbon to the ethyl group.",hl:"the oxygen joining the acyl carbon to the ethyl group"},
        {text:"The acid loses one of its oxygens as water; the catalyst only adds and removes H⁺.",strike:["the acetic acid","the acid catalyst","the water"]},
        {text:"Answer: the ethanol."}],
      trap:"Assuming the acid keeps both oxygens; one of them leaves in the water."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"acid-catalyzed esterification",note:"Fischer"},{t:"ethanol",note:"the nucleophile"}]},
      {text:"**Activate.** H⁺ protonates the acid's C=O, making the carbon more electrophilic."},
      {text:"**Attack and leave.**",calc:["EtO–H attacks C → tetrahedral intermediate","acid's –OH → –OH₂⁺ → leaves as H₂O"]},
      {text:"**Rule to reuse:** in Fischer esterification the alcohol keeps its oxygen as the ester's –O–, and the acid loses an oxygen as water."}]},
  {id:"cpt-pe1-10b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#2"],
    q:"Propanoic acid with ¹⁸O in both of its oxygens is esterified with unlabeled ethanol under acid catalysis. Which ester oxygen carries no label?",
    choices:["The bridging O","The carbonyl O","Both oxygens","Neither oxygen"],ans:0,
    exp:"The **ethanol oxygen** (unlabeled) attacks the protonated carbonyl carbon and stays bonded to the ethyl group as the ester's **bridging –O–**. One labeled acid oxygen leaves in the water; the other labeled oxygen stays as the ester's **C=O**. So only the bridging oxygen is unlabeled.",
    how:{ask:"Follow each oxygen through the mechanism: which one does the ester get from the alcohol?",
      know:"• Fischer esterification: the **alcohol O attacks** the carbonyl carbon and becomes the ester's –O–R′.\n• One of the acid's oxygens leaves as **water**; the other stays as the ester's **C=O**.\n• An isotope label marks an atom; where it ends up shows which bonds broke.",
      steps:[{text:"The label is on the acid's oxygens; the ethanol oxygen is ordinary.",hl:"¹⁸O in both of its oxygens"},
        {text:"Map each oxygen.",calc:["ester C=O: from the acid → **¹⁸O**","ester –O–: from ethanol → **¹⁶O**","water: from the acid → ¹⁸O"]},
        {text:"The carbonyl O is labeled, so neither \"both\" nor the carbonyl is unlabeled; the bridging O is unlabeled, so \"neither\" fails.",strike:["The carbonyl O","Both oxygens","Neither oxygen"]},
        {text:"Answer: the bridging O."}],
      trap:"Assuming the acid supplies the bridging oxygen; that oxygen comes from the alcohol, and an acid oxygen leaves as water."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"¹⁸O in both of its oxygens",note:"label on the acid"},{t:"unlabeled ethanol",note:"ordinary O nucleophile"},{t:"carries no label",note:"find the alcohol's O"}]},
      {text:"**The alcohol keeps its oxygen.** Ethanol's O attacks the carbonyl carbon and ends up between C=O and the ethyl group."},
      {text:"**The acid gives one O to water and keeps one as C=O.**",calc:["C=¹⁸O stays","–¹⁸OH leaves as H₂¹⁸O","–¹⁶O–Et from ethanol"]},
      {text:"**Rule to reuse:** in Fischer esterification the ester's bridging oxygen comes from the alcohol, its C=O oxygen from the acid, and the water from the acid."}]},
  {id:"cpt-pe1-10d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#3"],
    q:"To learn which reactant loses its –OH in an acid-catalyzed esterification, a chemist replaces the alcohol's O–H hydrogen with deuterium. Why does this label fail?",
    choices:["Acidic H exchanges with solvent","Deuterium is too heavy to react","The ester cannot contain hydrogen","Mass spectrometry cannot detect D"],ans:0,
    exp:"A hydrogen on oxygen is **acidic**: in acid it is swapped on and off rapidly with the solvent and the catalyst, so the D is **scrambled** among all O–H groups before and during the reaction. Where it ends up says nothing about which bond broke.",
    how:{ask:"Decide whether the labeled atom stays put long enough to report which bond broke.",
      know:"• H on O or N is acidic and **exchanges** with protic solvent and acid quickly.\n• A useful label must sit on an atom that does not exchange.",
      steps:[{text:"The label is on an O–H hydrogen.",hl:"replaces the alcohol's O–H hydrogen with deuterium"},
        {text:"That H trades places with the solvent's H in acid, so the label spreads everywhere.",calc:["R–O–D + H₂O ⇌ R–O–H + HOD"]},
        {text:"Deuterium reacts normally, the ester does contain H atoms, and mass spectrometry detects D easily.",strike:["Deuterium is too heavy to react","The ester cannot contain hydrogen","Mass spectrometry cannot detect D"]},
        {text:"Answer: the acidic H exchanges with solvent."}],
      trap:"Assuming any isotope tracks its atom: a label on an exchangeable H is lost to the solvent."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"O–H hydrogen",note:"acidic, exchangeable"},{t:"deuterium",note:"the label"}]},
      {text:"**Ask if the label stays put.** O–H hydrogens hop between molecules in acid many times a second."},
      {text:"**Scrambled label, no answer.**",calc:["D spreads over every O–H → no information"]},
      {text:"**Rule to reuse:** an H on O or N is a useless label: it exchanges in acid, so it cannot show which bond broke."}]},
  // ── Practice Exam 1 · Chem/Phys, physics: Q11, 14, 15, 18, 21, 52 (the first full 50-card day) ──
  // ── Practice Exam 1 · Chem/Phys, physics batch ──
  // pe1-cp:11 (eye-lens power from object and image distances)
  {id:"cpt-pe1-11a",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 1",from:["pe1-cp:11#1"],
    q:"A camera lens forms a sharp image of a flower 5.0 cm behind the lens when the flower is 20 cm in front. What is the focal length in metres?",
    choices:["0.040 m","4.0 m","0.067 m","25 m"],ans:0,
    exp:"Convert first: o = 0.20 m and i = 0.050 m. The **thin-lens equation** adds the reciprocals: 1/f = 5 m⁻¹ + 20 m⁻¹ = 25 m⁻¹, so **f = 0.040 m** (4.0 cm).",
    how:{ask:"Use the thin-lens equation with both distances converted to metres, then invert to get f.",
      know:"• **Thin-lens equation: 1/f = 1/o + 1/i** (o = object distance, i = image distance, f = focal length).\n• Work in **metres**: 1 cm = 0.01 m.\n• The equation gives 1/f; flip the result to get f.",
      steps:[{text:"Pick out the two distances and convert them to metres.",hl:"5.0 cm behind the lens",calc:["i = 5.0 cm = **0.050 m**","o = 20 cm = **0.20 m**"]},
        {text:"Add the reciprocals.",hl:"20 cm in front",calc:["1/f = 1/o + 1/i","1/f = 1/0.20 m + 1/0.050 m","1/f = 5 m⁻¹ + 20 m⁻¹ = **25 m⁻¹**"]},
        {text:"Invert to get the focal length.",calc:["f = 1 ÷ 25 m⁻¹ = **0.040 m**"]},
        {text:"25 m forgets to invert 1/f. 0.067 m subtracts the reciprocals (20 − 5 = 15 m⁻¹). 4.0 m does the arithmetic in centimetres (f = 4.0 cm) and then labels it metres.",strike:["25 m","0.067 m","4.0 m"]},
        {text:"Answer: 0.040 m."}],
      trap:"Doing the sum in centimetres gives f = 4.0 cm; that is right in cm, but 4.0 m is a hundred times too large. Convert to metres before you start."},
    teach:[{text:"First, **find every number** and what it measures.",marks:[{t:"5.0 cm behind the lens",note:"image distance i"},{t:"20 cm in front",note:"object distance o"},{t:"in metres",note:"unit of the answer"}]},
      {text:"**The thin-lens equation** links the three distances, each measured from the lens.",calc:["1/f = 1/o + 1/i"]},
      {text:"**Convert to metres first,** so 1/f comes out in m⁻¹.",calc:["o = 0.20 m → 1/o = 5 m⁻¹","i = 0.050 m → 1/i = 20 m⁻¹"]},
      {text:"**Add, then flip.**",calc:["1/f = 25 m⁻¹","f = 0.040 m"]},
      {text:"**Rule to reuse:** convert o and i to metres, add their reciprocals to get 1/f, and remember to invert at the end if the question asks for f."}]},
  {id:"cpt-pe1-11b",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 1",from:["pe1-cp:11#2"],
    q:"A converging magnifying lens has a focal length of 25 cm. What is the lens power, in diopters?",
    choices:["+4.0 D","+0.040 D","+25 D","+0.25 D"],ans:0,
    exp:"**Power P = 1/f**, and a diopter is one inverse metre, so f must be in metres: P = 1 ÷ 0.25 m = **+4.0 D**. A converging lens has a positive power.",
    how:{ask:"Convert the focal length to metres, take its reciprocal, and give the sign for a converging lens.",
      know:"• **P = 1/f**, with **f in metres**; the unit is the **diopter (D = m⁻¹)**.\n• Converging lens: f > 0, so P > 0. Diverging lens: P < 0.",
      steps:[{text:"Convert the focal length.",hl:"a focal length of 25 cm",calc:["f = 25 cm = **0.25 m**"]},
        {text:"Take the reciprocal.",calc:["P = 1/f","P = 1 ÷ 0.25 m","P = **4.0 m⁻¹ = +4.0 D**"]},
        {text:"+0.040 D comes from using centimetres (1/25 cm⁻¹). +25 D is just the focal length number, not its reciprocal.",strike:["+0.040 D","+25 D"]},
        {text:"+0.25 D is the focal length in metres, not its reciprocal. The sign is + because a converging lens has positive power.",hl:"converging",strike:["+0.25 D"]},
        {text:"Answer: +4.0 D."}],
      trap:"+0.040 D: taking 1/25 with f still in centimetres. Diopters are per metre, so convert before dividing."},
    teach:[{text:"First, **find the key words and number**.",marks:[{t:"converging",note:"positive power"},{t:"25 cm",note:"focal length f"},{t:"diopters",note:"unit = m⁻¹"}]},
      {text:"**Power measures how strongly a lens bends light**: a shorter focal length means a stronger lens.",calc:["P = 1/f"]},
      {text:"**A diopter is an inverse metre**, so f goes in metres.",calc:["25 cm = 0.25 m","P = 1 ÷ 0.25 = 4.0 D"]},
      {text:"**Rule to reuse:** power in diopters = 1 ÷ (focal length in metres); converging lenses are +, diverging lenses are −."}]},
  {id:"cpt-pe1-11c",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 1",from:["pe1-cp:11#3"],
    q:"A person's eye lens sits 24 mm in front of the retina. When the eye focuses sharply on a book 30 cm away, what is the image distance?",
    choices:["2.4 cm","30 cm","32.4 cm","27.6 cm"],ans:0,
    exp:"A sharp image must form **on the retina**, so the image distance is the **lens-to-retina distance**: 24 mm = **2.4 cm**. The 30 cm is the object distance; the eye focuses by changing f, not i.",
    how:{ask:"Decide where the image of a sharply focused object must land in the eye.",
      know:"• In the eye, the **image forms on the retina**.\n• So **i = lens-to-retina distance**, fixed for a given eye.\n• **o** = distance from lens to the object. The eye changes its **focal length** (accommodation) to keep i fixed.",
      steps:[{text:"A sharp image means the light converges exactly on the retina.",hl:"focuses sharply",calc:["image location = retina"]},
        {text:"So the image distance is the lens-to-retina distance.",hl:"24 mm in front of the retina",calc:["i = 24 mm = **2.4 cm**"]},
        {text:"30 cm is where the book is: the object distance.",hl:"a book 30 cm away",strike:["30 cm"]},
        {text:"Adding or subtracting the two distances has no meaning in the lens equation.",strike:["32.4 cm","27.6 cm"]},
        {text:"Answer: 2.4 cm."}],
      trap:"Using the object distance as i. Each distance is measured from the lens: o to the object, i to the retina."},
    teach:[{text:"First, **find each distance** and what it measures.",marks:[{t:"24 mm in front of the retina",note:"lens → retina"},{t:"a book 30 cm away",note:"lens → object"},{t:"image distance",note:"what we must find"}]},
      {text:"**Where does the image go?** A focused eye places the image on the retina, where it is sensed."},
      {text:"**Match the letters.**",calc:["o = 30 cm (book)","i = 24 mm = 2.4 cm (retina)"]},
      {text:"**Rule to reuse:** in any eye problem, the image distance is the lens-to-retina distance; the object distance is lens-to-object."}]},
  // pe1-cp:14 (V = IR at fixed R)
  {id:"cpt-pe1-14a",s:"Electricity & Magnetism",disc:"physics",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:14#1"],
    q:"A sensor with a constant resistance of 40 Ω carries 0.20 A, then 0.80 A. What happens to the voltage across the sensor?",
    choices:["It quadruples","It drops to a quarter","It stays the same","It doubles"],ans:0,
    exp:"Since **V = IR** and R is held constant, voltage scales directly with current. The current grows fourfold, so V goes from 8.0 V to 32 V: it **quadruples**.",
    how:{ask:"With R fixed, how does the voltage across the sensor depend on the current?",
      know:"• **Ohm's law: V = IR** (V in volts, I in amperes, R in ohms).\n• Fixed R → **V ∝ I**: multiply I by a factor and V is multiplied by the same factor.",
      steps:[{text:"R is constant, so V follows I.",hl:"a constant resistance of 40 Ω",calc:["V = IR","R fixed → V ∝ I"]},
        {text:"Find the factor by which the current changes.",hl:"0.20 A, then 0.80 A",calc:["0.80 A ÷ 0.20 A = **4**"]},
        {text:"Check with V = IR.",calc:["V₁ = 0.20 A × 40 Ω = **8.0 V**","V₂ = 0.80 A × 40 Ω = **32 V**","32 ÷ 8.0 = 4"]},
        {text:"A quarter would need V ∝ 1/I; staying the same would need V independent of I; doubling uses the wrong factor.",strike:["It drops to a quarter","It stays the same","It doubles"]},
        {text:"Answer: it quadruples."}],
      trap:"Thinking a constant resistance keeps the voltage constant. Constant R makes V proportional to I, so V changes whenever I does."},
    teach:[{text:"First, **find what is fixed and what changes**.",marks:[{t:"constant resistance",note:"R fixed"},{t:"0.20 A, then 0.80 A",note:"current rises 4×"},{t:"voltage",note:"what we must find"}]},
      {text:"**Ohm's law ties the three together.**",calc:["V = I × R"]},
      {text:"**Fixed R means V and I rise and fall together.** Same factor for both.",calc:["I × 4 → V × 4"]},
      {text:"**Rule to reuse:** at constant resistance, V = IR makes voltage directly proportional to current."}]},
  // pe1-cp:15 (n = c/v ≥ 1)
  {id:"cpt-pe1-15a",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 2",from:["pe1-cp:15#1"],
    q:"In vacuum, light travels at 300,000 km/s; inside a plastic lens it travels at 200,000 km/s. What is the plastic's index of refraction?",
    choices:["1.5","0.67","0.50","0.33"],ans:0,
    exp:"**n = c/v** = 300,000 ÷ 200,000 = **1.5**. Light is never faster in a material than in vacuum, so every real index is at least 1; the three values below 1 are impossible.",
    how:{ask:"Divide the speed of light in vacuum by its speed in the plastic, then check that n ≥ 1.",
      know:"• **Index of refraction: n = c/v** (c = speed in vacuum, v = speed in the material).\n• Since v ≤ c, **n ≥ 1 always** (n = 1 only for vacuum).",
      steps:[{text:"Pick out the two speeds.",hl:"300,000 km/s",calc:["c = 300,000 km/s","v = 200,000 km/s"]},
        {text:"Apply n = c/v; the units cancel.",hl:"200,000 km/s",calc:["n = c ÷ v","n = 300,000 ÷ 200,000","n = **1.5**"]},
        {text:"0.67 is v/c, the ratio upside down. 0.50 and 0.33 compare the speed difference with v or c. All are below 1, which would mean light moves faster than in vacuum.",strike:["0.67","0.50","0.33"]},
        {text:"Answer: 1.5."}],
      trap:"Writing v/c instead of c/v. Any index below 1 is a red flag that the ratio is flipped."},
    teach:[{text:"First, **find the two speeds**.",marks:[{t:"300,000 km/s",note:"c, in vacuum"},{t:"200,000 km/s",note:"v, in plastic"},{t:"index of refraction",note:"n = c/v"}]},
      {text:"**The index says how many times slower light is** in the material than in vacuum.",calc:["n = c ÷ v"]},
      {text:"**Fast over slow.** The bigger speed goes on top, so n comes out at least 1.",calc:["300,000 ÷ 200,000 = 1.5"]},
      {text:"**Rule to reuse:** n = c/v, and n ≥ 1 for every material; a value below 1 means the ratio was flipped."}]},
  // pe1-cp:18 (substitute one definition into another, then isolate)
  {id:"cpt-pe1-18a",s:"Fluids",disc:"physics",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:18#1"],
    q:"A fluid's gauge pressure at depth h is P = ρgh, and its density is ρ = m/V. Which expression gives the depth h?",
    choices:["PV/(mg)","mg/(PV)","Pm/(Vg)","P/(mVg)"],ans:0,
    exp:"Substitute the density definition: P = (m/V)gh. Multiply both sides by V to clear the fraction: PV = mgh. Divide by mg: **h = PV/(mg)**.",
    how:{ask:"Put the density definition into the pressure equation, clear the fraction, then isolate h.",
      know:"• **Substitution**: replace ρ with m/V.\n• **Clear a fraction** by multiplying both sides by its denominator (here V).\n• Then divide both sides by everything still multiplying h.",
      steps:[{text:"Substitute ρ = m/V into P = ρgh.",hl:"ρ = m/V",calc:["P = (m/V) g h"]},
        {text:"Multiply through by the denominator V.",hl:"P = ρgh",calc:["P × V = m g h","PV = mgh"]},
        {text:"Divide both sides by mg.",calc:["h = **PV/(mg)**"]},
        {text:"mg/(PV) is the result flipped. Pm/(Vg) comes from substituting ρ = V/m, the density definition upside down. P/(mVg) treats density as m × V instead of m ÷ V.",strike:["mg/(PV)","Pm/(Vg)","P/(mVg)"]},
        {text:"Answer: PV/(mg)."}],
      trap:"Putting V in the denominator: since ρ = m/V, the V sits under m, and moving it across the equals sign puts it on top with P."},
    teach:[{text:"First, **find the two definitions** and the unknown.",marks:[{t:"P = ρgh",note:"pressure equation"},{t:"ρ = m/V",note:"density definition"},{t:"depth h",note:"isolate this"}]},
      {text:"**Substitute.** Wherever ρ appears, write m/V.",calc:["P = (m/V)gh"]},
      {text:"**Clear the fraction.** Multiply every term by V.",calc:["PV = mgh"]},
      {text:"**Isolate h.** Divide by what multiplies it, then check units: (Pa·m³)/(kg·m/s²) = m ✓.",calc:["h = PV/(mg)"]},
      {text:"**Rule to reuse:** substitute one definition into the other, multiply through by the fraction's denominator, then divide to isolate the variable."}]},
  // pe1-cp:21 (flow rate in the graph's units → read power → W = P × t)
  {id:"cpt-pe1-21a",s:"Fluids",disc:"physics",aamc:"4A",skill:"SIRS 4",from:["pe1-cp:21#1"],
    q:"An infusion pump moves 900 mL of saline in 6.0 min. Its power-versus-flow graph uses L/min. What flow rate should be read on the graph?",
    choices:["0.15 L/min","150 L/min","5.4 L/min","0.0025 L/min"],ans:0,
    exp:"**Flow rate = volume ÷ time**, in the graph's units. 900 mL = 0.900 L, and 0.900 L ÷ 6.0 min = **0.15 L/min**. Keeping millilitres gives 150, a thousand times too big.",
    how:{ask:"Convert the volume and time into the units on the graph's axis, then divide.",
      know:"• **Flow rate Q = volume ÷ time**.\n• Match the axis units: here litres per minute.\n• 1000 mL = 1 L.",
      steps:[{text:"The graph's axis is in L/min, so the volume must be in litres and the time in minutes.",hl:"uses L/min"},
        {text:"Convert the volume.",hl:"900 mL",calc:["900 mL ÷ 1000 mL/L = **0.900 L**"]},
        {text:"Divide by the time, already in minutes.",hl:"6.0 min",calc:["Q = 0.900 L ÷ 6.0 min","Q = **0.15 L/min**"],
          chart:{type:"line",caption:"Saline delivered at a steady rate",x:{label:"Time (min)",min:0,max:6,step:1},y:{label:"Volume delivered (L)",min:0,max:1,step:0.25},series:[{name:"Volume",marker:"circle",line:"straight",points:[[0,0],[2,0.3],[4,0.6],[6,0.9]]}]}},
        {text:"150 L/min keeps millilitres. 5.4 L/min multiplies instead of dividing. 0.0025 L/min is the per-second rate (0.900 L ÷ 360 s) labelled as per minute.",strike:["150 L/min","5.4 L/min","0.0025 L/min"]},
        {text:"Answer: 0.15 L/min."}],
      trap:"Dividing 900 by 6.0 and stopping: 150 is mL/min, not L/min. Read the axis label before you look up a value."},
    teach:[{text:"First, **find every number** and the graph's unit.",marks:[{t:"900 mL",note:"volume"},{t:"6.0 min",note:"time"},{t:"uses L/min",note:"axis unit to match"}]},
      {text:"**Flow rate is volume per time.** On the graph of volume against time, the slope is the flow rate.",calc:["Q = V ÷ t"],
        chart:{type:"line",caption:"Slope = flow rate",x:{label:"Time (min)",min:0,max:6,step:1},y:{label:"Volume delivered (L)",min:0,max:1,step:0.25},series:[{name:"Volume",marker:"circle",line:"straight",points:[[0,0],[2,0.3],[4,0.6],[6,0.9]]}]}},
      {text:"**Match the axis units** before dividing.",calc:["900 mL = 0.900 L","0.900 L ÷ 6.0 min = 0.15 L/min"]},
      {text:"**Rule to reuse:** compute a rate in exactly the units of the graph's axis before reading the graph."}]},
  {id:"cpt-pe1-21b",s:"Reading Data",disc:"physics",aamc:"4A",skill:"SIRS 4",from:["pe1-cp:21#2"],
    q:"A pump moves 24 L in 4.0 min. Its power curve passes through 4 W at 0 L/min, 10 W at 2 L/min, 16 W at 4 L/min and 22 W at 6 L/min. What power does the pump draw?",
    choices:["22 W","16 W","4 W","88 W"],ans:0,
    exp:"First find the operating flow: 24 L ÷ 4.0 min = **6 L/min**. Then read the curve at that flow: **22 W**. Reading at 4 confuses the time with the flow.",
    how:{ask:"Work out the flow rate in L/min, then read the power at that flow on the curve.",
      know:"• **Flow rate = volume ÷ time**, in the axis units (L/min).\n• To read a graph: find the x value, go up to the curve, read across to y.",
      steps:[{text:"Compute the flow rate in the graph's units.",hl:"24 L in 4.0 min",calc:["Q = 24 L ÷ 4.0 min = **6 L/min**"]},
        {text:"Read the curve at 6 L/min.",hl:"22 W at 6 L/min",calc:["P(6 L/min) = **22 W**"],
          chart:{type:"line",caption:"Pump power versus flow rate",x:{label:"Flow rate (L/min)",min:0,max:8,step:2},y:{label:"Power (W)",min:0,max:30,step:5},series:[{name:"Power",marker:"circle",line:"straight",points:[[0,4],[2,10],[4,16],[6,22],[8,28]]}]}},
        {text:"16 W is read at x = 4, the number of minutes. 4 W is the curve at almost zero flow, what you get by using the per-second rate (0.1 L/s) on a per-minute axis. 88 W multiplies the power by the time, which gives work, not power.",strike:["16 W","4 W","88 W"]},
        {text:"Answer: 22 W."}],
      trap:"Reading the graph at a number from the stem (4.0 min) instead of at the computed flow rate."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"24 L",note:"volume"},{t:"4.0 min",note:"time"},{t:"power curve",note:"P read from flow"}]},
      {text:"**Get the x value.** The curve's x-axis is flow in L/min.",calc:["24 L ÷ 4.0 min = 6 L/min"]},
      {text:"**Go up to the curve, then across.** At 6 L/min the line sits at 22 W.",
        chart:{type:"line",caption:"Read power at the operating flow",x:{label:"Flow rate (L/min)",min:0,max:8,step:2},y:{label:"Power (W)",min:0,max:30,step:5},series:[{name:"Power",marker:"circle",line:"straight",points:[[0,4],[2,10],[4,16],[6,22],[8,28]]}]}},
      {text:"**Rule to reuse:** compute the x value in the axis's units, then read the curve at that x; never read at a raw number from the question."}]},
  {id:"cpt-pe1-21c",s:"Mechanics & Energy",disc:"physics",aamc:"4A",skill:"SIRS 4",from:["pe1-cp:21#3"],
    q:"A heart-assist pump runs at a steady 25 W, read from its power graph, for 6.0 min. How much work does the pump do in that time?",
    choices:["9.0 kJ","0.15 kJ","540 kJ","4.2 J"],ans:0,
    exp:"A watt is a joule per second, so **W = P × t** needs seconds: 6.0 min = 360 s, and 25 J/s × 360 s = 9000 J = **9.0 kJ**.",
    how:{ask:"Multiply the power by the time, with the time converted to seconds.",
      know:"• **P = W/t**, so **W = P × t**.\n• 1 W = 1 J/s, so t must be in **seconds**: 1 min = 60 s.\n• 1 kJ = 1000 J.",
      steps:[{text:"Power is joules per second.",hl:"a steady 25 W",calc:["W = P × t"]},
        {text:"Convert the time.",hl:"6.0 min",calc:["t = 6.0 min × 60 s/min = **360 s**"]},
        {text:"Multiply.",calc:["W = 25 J/s × 360 s","W = 9000 J = **9.0 kJ**"],
          chart:{type:"line",caption:"Work done at a steady 25 W",x:{label:"Time (s)",min:0,max:360,step:60},y:{label:"Work (kJ)",min:0,max:10,step:2},series:[{name:"Work",marker:"circle",line:"straight",points:[[0,0],[120,3],[240,6],[360,9]]}]}},
        {text:"0.15 kJ uses minutes (25 × 6.0 = 150 J). 540 kJ treats the minutes as hours (× 3600). 4.2 J divides power by time.",strike:["0.15 kJ","540 kJ","4.2 J"]},
        {text:"Answer: 9.0 kJ."}],
      trap:"Multiplying watts by minutes. A watt is per second, so minutes give a number 60 times too small."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"25 W",note:"power P"},{t:"6.0 min",note:"time t"},{t:"work",note:"energy in joules"}]},
      {text:"**Power is how fast work is done**: 25 W means 25 J every second.",calc:["W = P × t"]},
      {text:"**Seconds, then multiply.**",calc:["6.0 min = 360 s","25 × 360 = 9000 J = 9.0 kJ"]},
      {text:"**See it:** at constant power, work grows in a straight line with time.",
        chart:{type:"line",caption:"Work piles up at 25 J each second",x:{label:"Time (s)",min:0,max:360,step:60},y:{label:"Work (kJ)",min:0,max:10,step:2},series:[{name:"Work",marker:"circle",line:"straight",points:[[0,0],[120,3],[240,6],[360,9]]}]}},
      {text:"**Rule to reuse:** work = power × time, with power in watts and time in seconds, giving joules."}]},
  // pe1-cp:52 (raise the current: lower R; wire geometry and temperature; ion concentration and cell voltage)
  {id:"cpt-pe1-52a",s:"Electricity & Magnetism",disc:"physics",aamc:"4C",skill:"SIRS 3",from:["pe1-cp:52#1"],
    q:"A 9.0-V battery powers a 30-Ω heater coil. Which replacement coil would draw the largest current from the battery?",
    choices:["A 12-Ω coil","A 45-Ω coil","A 60-Ω coil","A 90-Ω coil"],ans:0,
    exp:"By **Ohm's law, I = V/R**, a fixed battery voltage drives more current through a smaller resistance. The 12-Ω coil draws 9.0 V ÷ 12 Ω = **0.75 A**, more than the 0.30 A now.",
    how:{ask:"With the battery voltage fixed, which resistance gives the biggest I = V/R?",
      know:"• **Ohm's law: I = V/R**.\n• Fixed V → current is **inversely proportional** to resistance: lower R, more current.",
      steps:[{text:"The battery sets V; only R changes.",hl:"A 9.0-V battery",calc:["I = V ÷ R"]},
        {text:"Current now.",hl:"30-Ω heater coil",calc:["I = 9.0 V ÷ 30 Ω = **0.30 A**"]},
        {text:"Compare the replacements.",calc:["12 Ω: 9.0 ÷ 12 = **0.75 A**","45 Ω: 9.0 ÷ 45 = 0.20 A","60 Ω: 9.0 ÷ 60 = 0.15 A","90 Ω: 9.0 ÷ 90 = 0.10 A"]},
        {text:"The larger coils all lower the current below 0.30 A.",strike:["A 45-Ω coil","A 60-Ω coil","A 90-Ω coil"]},
        {text:"Answer: the 12-Ω coil."}],
      trap:"Thinking a bigger resistor \"uses more\" current. At fixed voltage, more resistance means less current."},
    teach:[{text:"First, **find the givens**.",marks:[{t:"9.0-V battery",note:"V fixed"},{t:"30-Ω heater coil",note:"R now"},{t:"largest current",note:"goal"}]},
      {text:"**Ohm's law:** the battery's push divided by the resistance gives the current.",calc:["I = V ÷ R"]},
      {text:"**Smaller R, bigger I.** Halve R and the current doubles.",calc:["R ↓ → I ↑"]},
      {text:"**Rule to reuse:** to raise the current from a fixed voltage, lower the resistance (I = V/R)."}]},
  {id:"cpt-pe1-52b",s:"Electricity & Magnetism",disc:"physics",aamc:"4C",skill:"SIRS 3",from:["pe1-cp:52#2"],
    q:"Which change to the copper wire in a battery-and-lamp circuit would lower its resistance and raise the current?",
    choices:["Cooling it","Heating it","Lengthening it","Thinning it"],ans:0,
    exp:"Wire resistance is **R = ρL/A**. A longer wire (larger L) or a thinner one (smaller A) has more resistance, and heating a metal raises its resistivity ρ. **Cooling** lowers ρ, so R falls and the current rises.",
    how:{ask:"For each change, does the wire's resistance go up or down?",
      know:"• **R = ρL/A**: ρ = resistivity, L = length, A = cross-sectional area.\n• For metals, **ρ rises with temperature** (atoms vibrate more and scatter electrons).\n• With V fixed, lower R → larger I = V/R.",
      steps:[{text:"The goal is lower resistance.",hl:"lower its resistance",calc:["R = ρL/A"]},
        {text:"Length is on top: a longer wire has more resistance.",strike:["Lengthening it"]},
        {text:"Area is on the bottom: a thinner wire (smaller A) has more resistance.",strike:["Thinning it"]},
        {text:"A hotter metal has a larger ρ, so heating raises R.",strike:["Heating it"]},
        {text:"Answer: cooling it lowers ρ, and so R."}],
      trap:"Reading R = ρL/A backwards: a thinner wire has a smaller A in the denominator, so R goes up, not down."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"copper wire",note:"a metal"},{t:"lower its resistance",note:"goal"}]},
      {text:"**Resistance of a wire** depends on its material, length and thickness.",calc:["R = ρL/A"]},
      {text:"**Read the formula.** Longer → more R; thicker → less R; hotter metal → larger ρ → more R.",calc:["L ↑ → R ↑","A ↓ → R ↑","T ↑ → ρ ↑ → R ↑"]},
      {text:"**Rule to reuse:** a longer, thinner or hotter metal wire has more resistance; shorter, thicker or cooler has less."}]},
  {id:"cpt-pe1-52c",s:"Electrochemistry & Redox",disc:"physics",aamc:"4C",skill:"SIRS 3",from:["pe1-cp:52#3"],
    q:"A zinc–copper cell lights a small lamp. Which change to the copper(II) sulfate solution at the cathode would make the lamp's current larger?",
    choices:["Raise its Cu²⁺ concentration","Lower its Cu²⁺ concentration","Dilute it with water","Replace it with pure water"],ans:0,
    exp:"Cu²⁺ is a **reactant** at the cathode (Cu²⁺ + 2e⁻ → Cu). More Cu²⁺ pushes the cell reaction forward and **raises the cell voltage**; with the lamp's resistance fixed, I = V/R rises. Lower ion concentrations lower the voltage and the current.",
    how:{ask:"How does the cathode's Cu²⁺ concentration change the cell voltage, and so the current?",
      know:"• Cell reaction: Zn + Cu²⁺ → Zn²⁺ + Cu.\n• By Le Châtelier, **more reactant ion → larger cell voltage**; **lower reactant ion concentration → smaller voltage**.\n• Lamp R fixed → **I = V/R** follows the voltage.",
      steps:[{text:"At the cathode Cu²⁺ is reduced, so it is a reactant.",hl:"copper(II) sulfate solution at the cathode",calc:["Cu²⁺ + 2e⁻ → Cu"]},
        {text:"More reactant drives the reaction harder, so the voltage rises; with R fixed, the current rises.",calc:["[Cu²⁺] ↑ → V ↑ → I ↑"]},
        {text:"Lowering the concentration, or diluting with water, lowers the voltage and the current.",strike:["Lower its Cu²⁺ concentration","Dilute it with water"]},
        {text:"Pure water removes the Cu²⁺ altogether, so the cathode has almost nothing to reduce.",strike:["Replace it with pure water"]},
        {text:"Answer: raise its Cu²⁺ concentration."}],
      trap:"Thinking dilution helps because ions move more freely. Fewer reactant ions lower the cell's voltage, and so its current."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"zinc–copper cell",note:"galvanic cell"},{t:"at the cathode",note:"Cu²⁺ is reduced here"},{t:"current larger",note:"goal"}]},
      {text:"**Current comes from the cell's voltage** pushing through the lamp's fixed resistance.",calc:["I = V ÷ R"]},
      {text:"**Concentration sets the voltage.** More reactant ion makes the reaction more favourable; fewer makes it less.",calc:["[Cu²⁺] ↓ → V ↓ → I ↓"]},
      {text:"**Rule to reuse:** lowering the ion concentrations a cell runs on lowers its voltage, and at fixed R that lowers the current."}]},
  // ── Practice Exam 1 · Chem/Phys, general chemistry: Q13, 19, 20, 27, 37, 42 (the first full 50-card day) ──
  // ── Practice Exam 1 · Chem/Phys: Q13, Q19, Q20, Q27, Q37, Q42 ──
  // pe1-cp:13 (what lowers the percent ionization of a weak acid)
  {id:"cpt-pe1-13a",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:13#1"],
    q:"A 0.20 M solution of formic acid is prepared. Adding which substance would lower the percent ionization of the formic acid?",
    choices:["Nitric acid","Pure water","Sodium hydroxide","Sodium bicarbonate"],ans:0,
    exp:"HCOOH ⇌ H⁺ + HCOO⁻. Nitric acid is a **strong acid**, so it floods the solution with **H⁺, an ion already in the equilibrium**. By **Le Châtelier** the equilibrium shifts **left** and a smaller fraction of formic acid ionizes (the **common-ion effect**). Water dilutes the acid, and the two bases remove H⁺; all three raise ionization.",
    how:{ask:"For each added substance, decide whether the formic acid equilibrium shifts left (less ionized) or right (more ionized).",
      know:"• **Percent ionization** = [A⁻] at equilibrium ÷ starting [HA] × 100.\n• **Le Châtelier**: adding a product pushes the equilibrium toward reactants; removing a product pulls it toward products.\n• **Common-ion effect**: a strong acid adds H⁺, a product of HA ⇌ H⁺ + A⁻, so HA ionizes less.",
      steps:[{text:"Write the equilibrium for the weak acid in the stem.",hl:"0.20 M solution of formic acid",calc:["HCOOH ⇌ H⁺ + HCOO⁻   (Ka ≈ 1.8 × 10⁻⁴)","alone: x = √(Ka·C) = √(1.8 × 10⁻⁴ × 0.20) = √(3.6 × 10⁻⁵) = 6.0 × 10⁻³ M","% = 6.0 × 10⁻³ ÷ 0.20 × 100 = **3.0%**"]},
        {text:"Nitric acid is a strong acid: it adds H⁺, a product, so the equilibrium shifts left. With 0.050 M HNO₃ present:",calc:["x ≈ Ka·C ÷ [H⁺] = 1.8 × 10⁻⁴ × 0.20 ÷ 0.050","x = 7.2 × 10⁻⁴ M","% = 7.2 × 10⁻⁴ ÷ 0.20 × 100 = **0.36%**  (down from 3.0%)"]},
        {text:"Water dilutes the acid, and a diluted weak acid ionizes to a larger fraction.",strike:["Pure water"]},
        {text:"Both bases remove H⁺ (OH⁻ + H⁺ → H₂O; HCO₃⁻ + H⁺ → H₂CO₃), so the equilibrium shifts right: more ionization.",strike:["Sodium hydroxide","Sodium bicarbonate"]},
        {text:"Answer: nitric acid."}],
      trap:"Choosing a base because it \"neutralizes\" the acid: removing H⁺ pulls the equilibrium to the right, so the weak acid ionizes more, not less."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"formic acid",note:"weak acid: HCOOH ⇌ H⁺ + HCOO⁻"},{t:"lower the percent ionization",note:"shift the equilibrium left"}]},
      {text:"**Percent ionization** is the fraction of the acid molecules that have given up their H⁺.",calc:["% ionization = [A⁻] ÷ [HA]₀ × 100"]},
      {text:"**Le Châtelier:** add a product and the equilibrium moves back toward the reactant. H⁺ is a product, so an extra source of H⁺ makes less HA ionize.",calc:["add H⁺ → shift left → % ionization down","remove H⁺ → shift right → % ionization up"]},
      {text:"**Rule to reuse:** adding a strong acid (a common ion, H⁺) lowers a weak acid's percent ionization; adding a base raises it."}]},
  {id:"cpt-pe1-13b",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:13#2"],
    q:"A 0.50 M solution of hypochlorous acid is diluted with water to 0.0050 M. What happens to the percent ionization of HOCl?",
    choices:["It increases","It decreases","It stays the same","It falls to zero"],ans:0,
    exp:"For a weak acid, x ≈ √(Ka·C), so percent ionization = x ÷ C × 100 = √(Ka ÷ C) × 100. Making C **100 times smaller** makes the percent ionization **√100 = 10 times larger**: about 0.024% → 0.24%. Dilution favors the side with more dissolved particles (the ions).",
    how:{ask:"Find how the fraction of HOCl that ionizes depends on its concentration, then compare the two concentrations.",
      know:"• Weak acid: x = [H⁺] ≈ √(Ka·C).\n• % ionization = x ÷ C × 100 = √(Ka ÷ C) × 100, so it **rises as C falls**.\n• Le Châtelier view: dilution favors the side with more particles (H⁺ + A⁻).",
      steps:[{text:"Note the two concentrations.",hl:"0.50 M",calc:["before: C = 0.50 M","after: C = 0.0050 M (100 times more dilute)"]},
        {text:"Compute percent ionization before dilution (Ka of HOCl ≈ 3.0 × 10⁻⁸).",calc:["x = √(3.0 × 10⁻⁸ × 0.50) = √(1.5 × 10⁻⁸) = 1.2 × 10⁻⁴ M","% = 1.2 × 10⁻⁴ ÷ 0.50 × 100 = **0.024%**"]},
        {text:"Compute it after dilution.",hl:"0.0050 M",calc:["x = √(3.0 × 10⁻⁸ × 0.0050) = √(1.5 × 10⁻¹⁰) = 1.2 × 10⁻⁵ M","% = 1.2 × 10⁻⁵ ÷ 0.0050 × 100 = **0.24%**  (10 times larger)"]},
        {text:"[H⁺] itself falls, but the fraction ionized rises, so it neither drops nor stays fixed; a weak acid in water never stops ionizing.",strike:["It decreases","It stays the same","It falls to zero"]},
        {text:"Answer: it increases."}],
      trap:"Confusing [H⁺] with percent ionization: dilution lowers [H⁺] (pH rises) but raises the fraction of the acid that is ionized."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"hypochlorous acid",note:"weak acid"},{t:"diluted with water",note:"C becomes smaller"},{t:"percent ionization",note:"fraction ionized, not [H⁺]"}]},
      {text:"**Weak-acid shortcut:** x ≈ √(Ka·C). Divide by C to get the fraction ionized.",calc:["fraction = √(Ka·C) ÷ C = √(Ka ÷ C)"]},
      {text:"**Smaller C → bigger fraction.** A 100-fold dilution raises the fraction √100 = 10-fold.",calc:["C ÷ 100 → % ionization × 10"]},
      {text:"**Rule to reuse:** diluting a weak acid lowers [H⁺] but raises its percent ionization."}]},
  {id:"cpt-pe1-13c",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:13#3"],
    q:"How does the percent ionization of 2-chloropropanoic acid compare with that of propanoic acid at the same concentration in water?",
    choices:["It is higher","It is lower","It is the same","It depends on volume"],ans:0,
    exp:"The **electronegative Cl** on the carbon next to the COOH pulls electron density toward itself (an **inductive, electron-withdrawing** effect). That spreads out and **stabilizes the negative charge** of the carboxylate, so the acid is **stronger** (Ka ≈ 1.5 × 10⁻³ vs 1.3 × 10⁻⁵) and ionizes to a larger fraction.",
    how:{ask:"Decide whether the Cl makes the conjugate base more or less stable, and so whether the acid is stronger or weaker.",
      know:"• A **more stable conjugate base** → a **stronger acid** → larger Ka → higher percent ionization at the same C.\n• **Electron-withdrawing** groups (Cl, F, NO₂) near the COOH stabilize the carboxylate by pulling charge away.\n• The effect is strongest when the group is close to the COOH.",
      steps:[{text:"The two acids differ only by a Cl on the carbon next to the COOH.",hl:"2-chloropropanoic acid",calc:["CH₃CH₂COOH vs CH₃CHClCOOH"]},
        {text:"Cl withdraws electron density and stabilizes the carboxylate, so the chloro acid is stronger.",calc:["propanoic acid: Ka ≈ 1.3 × 10⁻⁵","2-chloropropanoic acid: Ka ≈ 1.5 × 10⁻³ (about 100 times larger)"]},
        {text:"Compare at 0.10 M: % ionization ≈ √(Ka ÷ C) × 100.",calc:["propanoic: √(1.3 × 10⁻⁴) × 100 ≈ **1.1%**","2-chloro: √(1.5 × 10⁻²) × 100 ≈ 12% (the quadratic gives ≈ 11.5%)"],strike:["It is lower","It is the same"]},
        {text:"The stem fixes the concentration, and percent ionization depends on concentration, not on the volume of solution.",strike:["It depends on volume"]},
        {text:"Answer: it is higher."}],
      trap:"Thinking Cl, a bigger and heavier atom, makes the acid weaker: what matters is that Cl pulls electron density away and stabilizes the anion."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"2-chloropropanoic acid",note:"Cl beside the COOH"},{t:"propanoic acid",note:"same acid without Cl"},{t:"same concentration",note:"compare Ka only"}]},
      {text:"**Acid strength = stability of the conjugate base.** The more easily the anion holds its negative charge, the more the acid ionizes."},
      {text:"**Electron-withdrawing groups help.** An electronegative Cl pulls charge away from the COO⁻ through the bonds, so the anion is more stable.",calc:["Cl near COOH → stabler COO⁻ → larger Ka"]},
      {text:"**Rule to reuse:** an electron-withdrawing substituent (such as Cl) near the acidic group makes the acid stronger, so it ionizes more."}]},
  {id:"cpt-pe1-13d",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:13#4"],
    q:"A student adds a single drop of methyl orange indicator, a weak base, to 50 mL of 0.30 M lactic acid. How does the acid's percent ionization change?",
    choices:["No real change","A large increase","A large decrease","It doubles"],ans:0,
    exp:"An indicator is added in a **tiny amount**: a drop holds roughly 10⁻⁷ mol of dye, while the flask holds 0.050 L × 0.30 M = 1.5 × 10⁻² mol of lactic acid. A base that small can remove only a negligible amount of H⁺, so the equilibrium, and the percent ionization, **barely move**.",
    how:{ask:"Compare the moles of indicator in one drop with the moles of acid in the flask.",
      know:"• Indicators are weak acids or bases used at **very low concentration**, so they signal pH without changing it.\n• A shift in a weak-acid equilibrium needs a **meaningful amount** of added H⁺ or OH⁻.\n• moles = volume (L) × molarity.",
      steps:[{text:"Find the moles of acid.",hl:"50 mL of 0.30 M lactic acid",calc:["n(acid) = 0.050 L × 0.30 mol/L = **1.5 × 10⁻² mol**"]},
        {text:"Estimate the moles of indicator in one drop.",hl:"a single drop of methyl orange indicator",calc:["one drop ≈ 0.05 mL ≈ 5 × 10⁻⁵ L","indicator ≈ 3 × 10⁻³ M → n ≈ 5 × 10⁻⁵ × 3 × 10⁻³ ≈ **1.5 × 10⁻⁷ mol**","ratio ≈ 1.5 × 10⁻⁷ ÷ 1.5 × 10⁻² = 10⁻⁵"]},
        {text:"A base 100 000 times smaller than the acid cannot shift the equilibrium noticeably in either direction, let alone double it.",strike:["A large increase","A large decrease","It doubles"]},
        {text:"Answer: no real change."}],
      trap:"Treating \"weak base\" as if a full dose of base had been added: one drop of indicator is far too little to change the acid equilibrium."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"a single drop",note:"tiny amount"},{t:"a weak base",note:"could remove some H⁺"},{t:"50 mL of 0.30 M",note:"plenty of acid"}]},
      {text:"**Compare amounts, not just identities.** A base shifts the equilibrium right only in proportion to how much H⁺ it removes."},
      {text:"**Count moles.** Acid: volume × molarity. Indicator: one drop of a dilute dye.",calc:["acid ≈ 10⁻² mol","indicator ≈ 10⁻⁷ mol"]},
      {text:"**Rule to reuse:** a drop of indicator is too small an amount to change an acid's equilibrium or its percent ionization."}]},

  // pe1-cp:19 (pulse pressure as a percentage of 1 atm)
  {id:"cpt-pe1-19a",s:"Fluids",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:19#1"],
    q:"Which blood pressure reading is closest to the typical resting value for a healthy young adult?",
    choices:["118/78 mmHg","165/105 mmHg","85/45 mmHg","210/150 mmHg"],ans:0,
    exp:"A healthy adult at rest has a blood pressure of about **120/80 mmHg**: about 120 mmHg **systolic** (heart contracting) over about 80 mmHg **diastolic** (heart relaxing). 118/78 is closest. 165/105 is high (hypertension), 85/45 is low (hypotension), and 210/150 is a dangerous crisis.",
    how:{ask:"Recall the normal adult blood pressure and pick the reading nearest to it.",
      know:"• Blood pressure is written **systolic/diastolic** in mmHg.\n• Typical healthy resting adult: about **120/80 mmHg**.\n• Well above (≥ 140/90) is hypertension; well below (≈ 90/60 or less) is hypotension.",
      steps:[{text:"The stem asks for a typical, healthy, resting value.",hl:"typical resting value for a healthy young adult",calc:["normal ≈ **120/80 mmHg**"]},
        {text:"Compare each reading with 120/80.",calc:["118/78: within a few mmHg ✓","165/105: about 45/25 too high","85/45: about 35/35 too low","210/150: about 90/70 too high"]},
        {text:"Hypertension, hypotension and a hypertensive crisis are not typical healthy values.",strike:["165/105 mmHg","85/45 mmHg","210/150 mmHg"]},
        {text:"Answer: 118/78 mmHg."}],
      trap:"Taking a high reading as normal-ish: values well above 120/80, such as 165/105, are hypertension, not a typical healthy adult."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"typical resting value",note:"normal, not exercise"},{t:"healthy young adult",note:"no hypertension"}]},
      {text:"**Read the two numbers.** Top = systolic, the peak while the heart squeezes; bottom = diastolic, the low point while it relaxes."},
      {text:"**Memorize the benchmark.**",calc:["normal ≈ 120/80 mmHg"]},
      {text:"**Rule to reuse:** a typical healthy adult's blood pressure is about 120/80 mmHg (systolic/diastolic)."}]},
  {id:"cpt-pe1-19b",s:"Fluids",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:19#2"],
    q:"After a sprint, a runner's blood pressure reads 146/92 mmHg. What is the runner's pulse pressure?",
    choices:["54 mmHg","238 mmHg","92 mmHg","73 mmHg"],ans:0,
    exp:"**Pulse pressure = systolic − diastolic** = 146 − 92 = **54 mmHg**. It is the swing in arterial pressure during each heartbeat. Adding the two values or halving the systolic value does not give the difference.",
    how:{ask:"Identify the systolic and diastolic values, then subtract.",
      know:"• Blood pressure = **systolic/diastolic** (top/bottom).\n• **Pulse pressure = systolic − diastolic**.",
      steps:[{text:"Read the two values.",hl:"146/92 mmHg",calc:["systolic = 146 mmHg","diastolic = 92 mmHg"]},
        {text:"Subtract.",hl:"pulse pressure",calc:["pulse pressure = 146 − 92 = **54 mmHg**"]},
        {text:"Eliminate the slips: 238 adds the two values (146 + 92); 92 is just the diastolic value; 73 halves the systolic value (146 ÷ 2).",strike:["238 mmHg","92 mmHg","73 mmHg"]},
        {text:"Answer: 54 mmHg."}],
      trap:"Reporting the diastolic value or the sum: pulse pressure is the difference between the two numbers."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"146",note:"systolic (top)"},{t:"92 mmHg",note:"diastolic (bottom)"}]},
      {text:"**Pulse pressure is the swing.** Each beat raises arterial pressure from the diastolic low to the systolic peak.",calc:["pulse pressure = systolic − diastolic"]},
      {text:"**Check with the normal value.** At 120/80 the swing is 40 mmHg; exercise widens it.",calc:["120 − 80 = 40 mmHg"]},
      {text:"**Rule to reuse:** pulse pressure = systolic − diastolic."}]},
  {id:"cpt-pe1-19c",s:"Fluids",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:19#3"],
    q:"A hyperbaric oxygen chamber is pressurized to 2.5 atm. What is this pressure expressed in mmHg?",
    choices:["1900 mmHg","304 mmHg","253 mmHg","3800 mmHg"],ans:0,
    exp:"**1 atm = 760 mmHg**, so multiply: 2.5 atm × 760 mmHg/atm = **1900 mmHg**. Dividing gives 304, using the kPa value (101) gives 253, and 3800 doubles the correct value.",
    how:{ask:"Use the atm-to-mmHg conversion factor and decide whether to multiply or divide.",
      know:"• **1 atm = 760 mmHg** (= 760 torr = 101 kPa).\n• Converting a larger unit (atm) into a smaller one (mmHg) gives a **bigger number**: multiply.",
      steps:[{text:"Note the pressure and the unit wanted.",hl:"2.5 atm",calc:["want: mmHg","factor: 760 mmHg per 1 atm"]},
        {text:"Multiply, letting atm cancel.",calc:["2.5 atm × (760 mmHg ÷ 1 atm)","= **1900 mmHg**"]},
        {text:"Eliminate the slips: 304 = 760 ÷ 2.5 (divided instead of multiplied); 253 ≈ 2.5 × 101 (the kPa value, not mmHg); 3800 = 5 × 760 (doubled the pressure).",strike:["304 mmHg","253 mmHg","3800 mmHg"]},
        {text:"Answer: 1900 mmHg."}],
      trap:"Using 101 instead of 760: 101 is the number of kilopascals in 1 atm, not millimeters of mercury."},
    teach:[{text:"First, **find the number and the units**.",marks:[{t:"2.5 atm",note:"given in atmospheres"},{t:"mmHg",note:"unit wanted"}]},
      {text:"**Know the conversion.** Air pressure at sea level holds up a 760 mm column of mercury.",calc:["1 atm = 760 mmHg = 101 kPa"]},
      {text:"**Set up the factor so units cancel.**",calc:["atm × (mmHg ÷ atm) = mmHg"]},
      {text:"**Rule to reuse:** 1 atm = 760 mmHg; multiply atm by 760 to get mmHg."}]},
  {id:"cpt-pe1-19d",s:"Fluids",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:19#4"],
    q:"A patient's systolic pressure is 95 mmHg. Expressed as a percentage of atmospheric pressure, about how large is this value?",
    choices:["12.5%","8.0%","94%","0.13%"],ans:0,
    exp:"Write both pressures in **the same unit**, mmHg: 95 ÷ 760 = 0.125, and 0.125 × 100 = **12.5%**. 8.0 inverts the ratio, 94% divides mmHg by kPa, and 0.13% forgets to multiply by 100.",
    how:{ask:"Divide the patient's pressure by atmospheric pressure in matching units, then convert to a percentage.",
      know:"• **1 atm = 760 mmHg**.\n• **% = value ÷ 760 mmHg × 100** when the value is in mmHg.\n• Never divide mmHg by kPa.",
      steps:[{text:"Note the value and its unit.",hl:"95 mmHg",calc:["value = 95 mmHg","1 atm = 760 mmHg"]},
        {text:"Divide, then multiply by 100.",calc:["95 ÷ 760 = 0.125","0.125 × 100 = **12.5%**"]},
        {text:"Eliminate the slips: 8.0 = 760 ÷ 95 (inverted); 94% ≈ 95 ÷ 101 (mmHg over kPa); 0.13% ≈ 0.125 written as a percent without the × 100.",strike:["8.0%","94%","0.13%"]},
        {text:"Answer: 12.5%."}],
      trap:"Dividing by 101: that is atmospheric pressure in kPa, and dividing mmHg by kPa gives a meaningless number near 94%."},
    teach:[{text:"First, **find the number and what to compare it with**.",marks:[{t:"95 mmHg",note:"the value"},{t:"atmospheric pressure",note:"760 mmHg"}]},
      {text:"**Same units first.** The value is in mmHg, so use 1 atm = 760 mmHg."},
      {text:"**Percentage = fraction × 100.**",calc:["% = value ÷ 760 × 100"]},
      {text:"**Rule to reuse:** percent of 1 atm = (pressure in mmHg ÷ 760) × 100."}]},

  // pe1-cp:20 (fraction of a radioactive sample decayed after a given time)
  {id:"cpt-pe1-20a",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:20#1"],
    q:"Technetium-99m has a half-life of 6.0 hours. A dose is stored for 30 hours before use. How many half-lives have passed?",
    choices:["5","24","180","0.2"],ans:0,
    exp:"**Number of half-lives n = elapsed time ÷ half-life** = 30 h ÷ 6.0 h = **5**. Subtracting (24), multiplying (180) or dividing the wrong way (0.2) does not count how many half-lives fit into the time.",
    how:{ask:"Count how many half-life intervals fit into the storage time.",
      know:"• **Half-life (t½)**: the time for half of the remaining nuclei to decay.\n• **n = t ÷ t½** (same time unit for both).",
      steps:[{text:"Note the half-life and the elapsed time, both in hours.",hl:"6.0 hours",calc:["t½ = 6.0 h","t = 30 h"]},
        {text:"Divide.",hl:"30 hours",calc:["n = 30 h ÷ 6.0 h = **5**"]},
        {text:"See it on the decay curve: the amount halves at 6, 12, 18, 24 and 30 h.",chart:{type:"line",caption:"Technetium-99m remaining over time",x:{label:"Time (h)",min:0,max:30,step:6},y:{label:"Remaining (%)",min:0,max:100,step:20},series:[{name:"Remaining",marker:"circle",line:"smooth",points:[[0,100],[6,50],[12,25],[18,12.5],[24,6.25],[30,3.13]]}]}},
        {text:"Eliminate the slips: 24 = 30 − 6; 180 = 30 × 6; 0.2 = 6 ÷ 30.",strike:["24","180","0.2"]},
        {text:"Answer: 5."}],
      trap:"Writing 0.2 by dividing the half-life by the time: n = time ÷ half-life, so the longer time goes on top."},
    teach:[{text:"First, **find every number**.",marks:[{t:"half-life of 6.0 hours",note:"t½"},{t:"30 hours",note:"elapsed time t"}]},
      {text:"**Each half-life halves what is left.** Count the 6-hour steps along the time axis.",chart:{type:"line",caption:"Halving every 6 hours",x:{label:"Time (h)",min:0,max:30,step:6},y:{label:"Remaining (%)",min:0,max:100,step:20},series:[{name:"Remaining",marker:"circle",line:"smooth",points:[[0,100],[6,50],[12,25],[18,12.5],[24,6.25],[30,3.13]]}]}},
      {text:"**Divide time by half-life.**",calc:["n = t ÷ t½"]},
      {text:"**Rule to reuse:** number of half-lives n = elapsed time ÷ half-life."}]},
  {id:"cpt-pe1-20b",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:20#2"],
    q:"Strontium-90 has a half-life of 29 years. How much of a 40 mg sample of it remains after 87 years?",
    choices:["5 mg","10 mg","20 mg","35 mg"],ans:0,
    exp:"n = 87 ÷ 29 = **3** half-lives. **Remaining = starting amount × (½)ⁿ** = 40 mg × ⅛ = **5 mg**. 35 mg is the amount that decayed, not the amount left.",
    how:{ask:"Count the half-lives, then halve the starting amount that many times.",
      know:"• n = t ÷ t½.\n• **Remaining = N₀ × (½)ⁿ**.\n• Decayed = N₀ − remaining.",
      steps:[{text:"Note the starting mass, the half-life and the time.",hl:"40 mg",calc:["N₀ = 40 mg","t½ = 29 y, t = 87 y"]},
        {text:"Count half-lives.",hl:"87 years",calc:["n = 87 ÷ 29 = **3**"]},
        {text:"Halve three times.",calc:["(½)³ = ⅛","40 mg × ⅛ = **5 mg**","40 → 20 → 10 → 5 mg"],chart:{type:"line",caption:"Strontium-90 remaining in a 40 mg sample",x:{label:"Time (years)",min:0,max:87,step:29},y:{label:"Mass remaining (mg)",min:0,max:40,step:10},series:[{name:"Sr-90 left",marker:"circle",line:"smooth",points:[[0,40],[29,20],[58,10],[87,5]]}]}},
        {text:"20 mg is after one half-life and 10 mg after two; 35 mg (40 − 5) is what decayed.",strike:["20 mg","10 mg","35 mg"]},
        {text:"Answer: 5 mg."}],
      trap:"Answering 35 mg: that is the decayed mass. The question asks what remains."},
    teach:[{text:"First, **find every number**.",marks:[{t:"half-life of 29 years",note:"t½"},{t:"40 mg",note:"starting amount"},{t:"87 years",note:"elapsed time"}]},
      {text:"**Count half-lives:** n = t ÷ t½.",calc:["n = 87 ÷ 29 = 3"]},
      {text:"**Halve n times**, which is the same as multiplying by (½)ⁿ.",chart:{type:"line",caption:"Each half-life halves the mass",x:{label:"Time (years)",min:0,max:87,step:29},y:{label:"Mass remaining (mg)",min:0,max:40,step:10},series:[{name:"Sr-90 left",marker:"circle",line:"smooth",points:[[0,40],[29,20],[58,10],[87,5]]}]}},
      {text:"**Rule to reuse:** amount remaining = starting amount × (½)ⁿ, with n = time ÷ half-life."}]},
  {id:"cpt-pe1-20c",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:20#3"],
    q:"Cobalt-60 has a half-life of about 5.3 years. What percentage of the cobalt-60 nuclei in a sample has decayed after 26.5 years?",
    choices:["97%","3%","94%","100%"],ans:0,
    exp:"n = 26.5 ÷ 5.3 = **5** half-lives, so (½)⁵ = 1/32 ≈ 3% **remains**. **Decayed = 1 − remaining** = 31/32 ≈ **97%**. 3% is what is left; 94% stops at four half-lives; decay never reaches 100%.",
    how:{ask:"Find the fraction remaining after the given number of half-lives, then subtract it from the whole.",
      know:"• n = t ÷ t½.\n• Remaining = (½)ⁿ.\n• **Decayed = 1 − (½)ⁿ**.\n• Exponential decay approaches zero but never reaches it.",
      steps:[{text:"Count half-lives.",hl:"26.5 years",calc:["n = 26.5 ÷ 5.3 = **5**"]},
        {text:"Find what remains, then what decayed.",calc:["remaining = (½)⁵ = 1/32 ≈ 0.031 ≈ 3%","decayed = 1 − 1/32 = 31/32 ≈ 0.969 ≈ **97%**"],chart:{type:"line",caption:"Cobalt-60: remaining and decayed",x:{label:"Time (years)",min:0,max:26.5,step:5.3},y:{label:"Percent of original nuclei",min:0,max:100,step:20},series:[{name:"Remaining",marker:"circle",line:"smooth",points:[[0,100],[5.3,50],[10.6,25],[15.9,12.5],[21.2,6.25],[26.5,3.13]]},{name:"Decayed",marker:"square-open",line:"smooth",points:[[0,0],[5.3,50],[10.6,75],[15.9,87.5],[21.2,93.75],[26.5,96.88]]}]}},
        {text:"3% is the fraction remaining; 94% is the decayed share after only four half-lives (1 − 1/16); 100% would need infinite time.",strike:["3%","94%","100%"]},
        {text:"Answer: 97%."}],
      trap:"Stopping at (½)ⁿ: that is what remains. The question asks for the decayed part, 1 − (½)ⁿ."},
    teach:[{text:"First, **find the numbers and the word that decides the answer**.",marks:[{t:"5.3 years",note:"t½"},{t:"26.5 years",note:"elapsed time"},{t:"has decayed",note:"1 − remaining"}]},
      {text:"**Two curves, one sample.** What remains falls by half each half-life; what has decayed rises to fill the gap. They always add to 100%.",chart:{type:"line",caption:"Remaining + decayed = 100%",x:{label:"Time (years)",min:0,max:26.5,step:5.3},y:{label:"Percent of original nuclei",min:0,max:100,step:20},series:[{name:"Remaining",marker:"circle",line:"smooth",points:[[0,100],[5.3,50],[10.6,25],[15.9,12.5],[21.2,6.25],[26.5,3.13]]},{name:"Decayed",marker:"square-open",line:"smooth",points:[[0,0],[5.3,50],[10.6,75],[15.9,87.5],[21.2,93.75],[26.5,96.88]]}]}},
      {text:"**Compute remaining first, then subtract.**",calc:["remaining = (½)ⁿ","decayed = 1 − (½)ⁿ"]},
      {text:"**Rule to reuse:** fraction decayed = 1 − (½)ⁿ, where n = time ÷ half-life."}]},

  // pe1-cp:27 (reading a potential–pH (Pourbaix) diagram)
  {id:"cpt-pe1-27a",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4E",skill:"SIRS 4",from:["pe1-cp:27#1"],
    q:"On a potential–pH diagram, the boundary between Cu²⁺ and copper metal stays at +0.34 V from pH 0 to 5. Which species is absent from its half-reaction?",
    choices:["H⁺ and OH⁻","The two electrons","The Cu²⁺ ions","The copper metal"],ans:0,
    exp:"A **horizontal** boundary keeps the same potential whatever the pH, so the equilibrium **does not depend on pH**: its half-reaction, Cu²⁺ + 2e⁻ ⇌ Cu, contains **no H⁺ or OH⁻**. It still transfers electrons, and both copper forms appear in it.",
    how:{ask:"Decide what a boundary at one fixed potential across a range of pH says about the half-reaction.",
      know:"• Pourbaix diagram: potential E (y) versus pH (x); each line is an equilibrium between two forms.\n• **Horizontal line**: E does not change with pH → **pH-independent** → no H⁺ or OH⁻ in the half-reaction, but electrons are transferred.",
      steps:[{text:"The boundary is flat: one potential across several pH values.",hl:"stays at +0.34 V from pH 0 to 5",calc:["E constant while pH changes → pH-independent"]},
        {text:"Write the half-reaction it represents.",calc:["Cu²⁺ + 2e⁻ ⇌ Cu   (E° = +0.34 V)","no H⁺, no OH⁻"],chart:{type:"line",caption:"Boundary lines on a simplified iron potential–pH diagram",x:{label:"pH",min:0,max:8,step:1},y:{label:"Potential (V)",min:-0.8,max:1.2,step:0.4},series:[{name:"Fe³⁺/Fe²⁺: horizontal",marker:"circle",line:"straight",points:[[0,0.77],[2,0.77]]},{name:"Fe³⁺/Fe(OH)₃: vertical",marker:"square-open",line:"straight",points:[[2,0.77],[2,1.2]]},{name:"Fe(OH)₃/Fe²⁺",marker:"diamond",line:"straight",points:[[2,0.77],[8,-0.29]]},{name:"Fe²⁺/Fe: horizontal",marker:"triangle",line:"straight",points:[[0,-0.44],[8,-0.44]]}]}},
        {text:"A line set at a potential is a redox couple, so electrons must be in it; Cu²⁺ and Cu are the two forms the line separates.",strike:["The two electrons","The Cu²⁺ ions","The copper metal"]},
        {text:"Answer: H⁺ and OH⁻."}],
      trap:"Thinking a flat line means \"no electrons\": that describes a vertical line. A flat line is a redox couple with no H⁺ or OH⁻."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"potential–pH diagram",note:"E on y, pH on x"},{t:"stays at +0.34 V",note:"horizontal line"},{t:"from pH 0 to 5",note:"pH changes, E does not"}]},
      {text:"**Read the slope of each boundary.** A flat line sits at one potential, whatever the pH.",chart:{type:"line",caption:"Boundary lines on a simplified iron potential–pH diagram",x:{label:"pH",min:0,max:8,step:1},y:{label:"Potential (V)",min:-0.8,max:1.2,step:0.4},series:[{name:"Fe³⁺/Fe²⁺: horizontal",marker:"circle",line:"straight",points:[[0,0.77],[2,0.77]]},{name:"Fe³⁺/Fe(OH)₃: vertical",marker:"square-open",line:"straight",points:[[2,0.77],[2,1.2]]},{name:"Fe(OH)₃/Fe²⁺",marker:"diamond",line:"straight",points:[[2,0.77],[8,-0.29]]},{name:"Fe²⁺/Fe: horizontal",marker:"triangle",line:"straight",points:[[0,-0.44],[8,-0.44]]}]}},
      {text:"**Flat = pH has no say.** If changing pH does not move the line, H⁺ and OH⁻ are not in the equilibrium.",calc:["horizontal → electrons yes, H⁺/OH⁻ no"]},
      {text:"**Rule to reuse:** a horizontal Pourbaix boundary is a redox equilibrium that does not depend on pH (no H⁺ or OH⁻ involved)."}]},
  {id:"cpt-pe1-27b",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4E",skill:"SIRS 4",from:["pe1-cp:27#2"],
    q:"On a potential–pH diagram for manganese, the boundary between Mn²⁺(aq) and solid Mn(OH)₂ is a vertical line. What does that boundary represent?",
    choices:["No electron transfer","A one-electron reduction","A two-electron oxidation","A pH-independent change"],ans:0,
    exp:"A **vertical** boundary sits at one pH at every potential, so changing the potential does not move it: the equilibrium involves **no electrons**. Here Mn²⁺ + 2OH⁻ ⇌ Mn(OH)₂, and Mn is +2 on both sides; it is a pH-dependent precipitation, not a redox step.",
    how:{ask:"Decide what a boundary at one fixed pH across every potential says about electrons and about pH.",
      know:"• Pourbaix diagram: potential (y) versus pH (x).\n• **Vertical line**: fixed pH at all potentials → depends on pH, **no electron transfer** (an acid–base or precipitation step).\n• Horizontal line: electron transfer, no H⁺/OH⁻.",
      steps:[{text:"The boundary is vertical.",hl:"is a vertical line",calc:["pH fixed, E varies → potential does not matter → no e⁻"]},
        {text:"Check oxidation states of the two forms.",hl:"Mn²⁺(aq) and solid Mn(OH)₂",calc:["Mn²⁺: Mn = +2","Mn(OH)₂: Mn = +2","Mn²⁺ + 2OH⁻ ⇌ Mn(OH)₂   (no e⁻)"]},
        {text:"Without a change in oxidation state there is no reduction or oxidation, and a line located at one pH depends on pH rather than ignoring it.",strike:["A one-electron reduction","A two-electron oxidation","A pH-independent change"]},
        {text:"Answer: no electron transfer."}],
      trap:"\"A pH-independent change\" belongs to a horizontal line; a vertical line is exactly the case where pH decides which form is stable."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Mn²⁺(aq)",note:"Mn is +2"},{t:"solid Mn(OH)₂",note:"Mn is still +2"},{t:"vertical line",note:"one pH, every potential"}]},
      {text:"**Vertical lines ignore the potential.** Moving up or down (changing E) never crosses them, so electrons play no part.",chart:{type:"line",caption:"Vertical boundary on a simplified iron diagram: Fe³⁺ ⇌ Fe(OH)₃",x:{label:"pH",min:0,max:8,step:1},y:{label:"Potential (V)",min:-0.8,max:1.2,step:0.4},series:[{name:"Fe³⁺/Fe(OH)₃: vertical",marker:"square-open",line:"straight",points:[[2,0.77],[2,1.2]]},{name:"Fe³⁺/Fe²⁺: horizontal",marker:"circle",line:"straight",points:[[0,0.77],[2,0.77]]},{name:"Fe(OH)₃/Fe²⁺",marker:"diamond",line:"straight",points:[[2,0.77],[8,-0.29]]}]}},
      {text:"**Confirm with oxidation states.** If the metal has the same oxidation state on both sides, the step is acid–base or precipitation.",calc:["same oxidation state → no e⁻ → vertical line"]},
      {text:"**Rule to reuse:** a vertical Pourbaix boundary means the equilibrium depends on pH but transfers no electrons."}]},
  {id:"cpt-pe1-27c",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4E",skill:"SIRS 4",from:["pe1-cp:27#3"],
    q:"In basic solution, which chromium species occupies the region at the most positive potentials of a potential–pH diagram?",
    choices:["CrO₄²⁻ (Cr +6)","Cr(OH)₃ (Cr +3)","Cr(OH)₂ (Cr +2)","Cr metal (Cr 0)"],ans:0,
    exp:"The y-axis is the potential: **higher on the diagram = more oxidizing conditions**, so the stable form there is the **most oxidized** one. Among these, chromate, with Cr in the **+6** state, is the highest oxidation state; Cr metal (0) sits at the most negative potentials.",
    how:{ask:"Match the most positive potentials with the highest oxidation state of chromium.",
      know:"• Pourbaix y-axis: potential E. **High E = oxidizing** → most oxidized species are stable at the top.\n• Low E = reducing → the element (oxidation state 0) is stable at the bottom.\n• Oxidation state of Cr in CrO₄²⁻: x + 4(−2) = −2 → x = +6.",
      steps:[{text:"The region asked about is at the top of the potential axis.",hl:"the most positive potentials",calc:["high E → most oxidized form"]},
        {text:"Rank the chromium oxidation states.",calc:["CrO₄²⁻: x − 8 = −2 → **+6**","Cr(OH)₃: +3   Cr(OH)₂: +2   Cr: 0"]},
        {text:"Lower oxidation states are stable lower on the diagram, with the metal at the very bottom.",strike:["Cr(OH)₃ (Cr +3)","Cr(OH)₂ (Cr +2)","Cr metal (Cr 0)"]},
        {text:"Answer: CrO₄²⁻ (Cr +6)."}],
      trap:"Picking the metal because it is \"the element itself\": the metal is the most reduced form and lives at the lowest potentials."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"most positive potentials",note:"top of the diagram"},{t:"chromium species",note:"compare oxidation states"}]},
      {text:"**Up = more oxidized.** On any potential–pH diagram, the metal sits at the bottom and each higher region holds a more oxidized form.",chart:{type:"line",caption:"Simplified iron diagram: Fe (0) below, Fe²⁺ (+2) in the middle, Fe³⁺ and Fe(OH)₃ (+3) on top",x:{label:"pH",min:0,max:8,step:1},y:{label:"Potential (V)",min:-0.8,max:1.2,step:0.4},series:[{name:"Fe³⁺/Fe²⁺",marker:"circle",line:"straight",points:[[0,0.77],[2,0.77]]},{name:"Fe(OH)₃/Fe²⁺",marker:"diamond",line:"straight",points:[[2,0.77],[8,-0.29]]},{name:"Fe²⁺/Fe",marker:"triangle",line:"straight",points:[[0,-0.44],[8,-0.44]]}]}},
      {text:"**Find each oxidation state** (O is −2, H is +1, the total equals the charge).",calc:["CrO₄²⁻ → +6","Cr(OH)₃ → +3"]},
      {text:"**Rule to reuse:** the higher a region lies on a potential–pH diagram, the more oxidized the species stable there."}]},

  // pe1-cp:37 (factor change in [H⁺] between two pH values)
  {id:"cpt-pe1-37a",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:37#1"],
    q:"A urine sample from patient A has a pH of 5.8, and a sample from patient B has a pH of 7.8. How does [H⁺] in sample B compare with sample A?",
    choices:["100 times lower","100 times higher","2 times lower","20 times lower"],ans:0,
    exp:"Because **pH = −log[H⁺]**, one pH unit corresponds to a **tenfold** change in [H⁺]. Sample B is 7.8 − 5.8 = 2 units higher, so its [H⁺] is 10² = **100 times lower**: about 1.6 × 10⁻⁸ M versus 1.6 × 10⁻⁶ M.",
    how:{ask:"Find the pH difference, turn it into a power of ten, and decide whether a higher pH means more or less H⁺.",
      know:"• **pH = −log[H⁺]** → [H⁺] = 10^(−pH).\n• A difference of Δ pH units = a factor of **10^Δ** in [H⁺].\n• **Higher pH = less H⁺**.",
      steps:[{text:"Find the pH change from A to B.",hl:"a pH of 5.8",calc:["ΔpH = 7.8 − 5.8 = **2** units"]},
        {text:"Convert to a factor and check with real concentrations.",hl:"a pH of 7.8",calc:["factor = 10² = **100**","pH 5.8: [H⁺] = 10^−5.8 ≈ 1.6 × 10⁻⁶ M","pH 7.8: [H⁺] = 10^−7.8 ≈ 1.6 × 10⁻⁸ M","1.6 × 10⁻⁶ ÷ 1.6 × 10⁻⁸ = **100**"],strike:["2 times lower","20 times lower"]},
        {text:"Direction: B has the higher pH, so it has less H⁺.",strike:["100 times higher"]},
        {text:"Answer: 100 times lower."}],
      trap:"\"2 times lower\" treats pH as linear; every pH unit is a tenfold change, so 2 units is 10 × 10 = 100."},
    teach:[{text:"First, **find the numbers** and what you must compare.",marks:[{t:"a pH of 5.8",note:"sample A"},{t:"a pH of 7.8",note:"sample B"},{t:"[H⁺]",note:"H⁺ concentration"}]},
      {text:"**pH counts powers of ten:** [H⁺] = 10^(−pH).",calc:["pH 5 → 10⁻⁵ M","pH 6 → 10⁻⁶ M (10 times less)"]},
      {text:"**Subtract, then raise 10 to that power.** Then set the direction: higher pH, less H⁺.",calc:["factor = 10^(ΔpH)"]},
      {text:"**Rule to reuse:** a change of Δ pH units changes [H⁺] by a factor of 10^Δ, and a lower pH means more H⁺."}]},

  // pe1-cp:42 (daughter nuclei after β⁻ decay)
  {id:"cpt-pe1-42a",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:42#1"],
    q:"A nucleus undergoes β⁻ decay. How do its mass number A and its atomic number Z change?",
    choices:["A unchanged; Z up by 1","A unchanged; Z down by 1","A down by 4; Z down by 2","A up by 1; Z unchanged"],ans:0,
    exp:"In **β⁻ decay a neutron becomes a proton**, releasing an electron and an antineutrino: n → p + e⁻ + ν̄. The nucleus gains a proton (**Z + 1**) and loses a neutron, so the total nucleon count **A stays the same**. Example: ³H → ³He.",
    how:{ask:"Track what happens to the protons and neutrons when a neutron changes into a proton.",
      know:"• **β⁻ decay**: n → p + e⁻ + ν̄ → **A unchanged, Z + 1**.\n• β⁺ decay: p → n + e⁺ → A unchanged, Z − 1.\n• α decay: loses ⁴He → A − 4, Z − 2.",
      steps:[{text:"β⁻ means an electron is created in the nucleus as a neutron turns into a proton.",hl:"β⁻ decay",calc:["n → p + e⁻ + ν̄","protons +1, neutrons −1, nucleons unchanged"]},
        {text:"Check with tritium and cobalt-60.",calc:["³₁H → ³₂He + ⁰₋₁e + ν̄","⁶⁰₂₇Co → ⁶⁰₂₈Ni + ⁰₋₁e + ν̄","A: same   Z: up by 1 ✓"]},
        {text:"Z − 1 is positron emission; A − 4 with Z − 2 is alpha decay; nothing adds a nucleon, so A cannot rise; the electron carries A = 0.",strike:["A unchanged; Z down by 1","A down by 4; Z down by 2","A up by 1; Z unchanged"]},
        {text:"Answer: A unchanged; Z up by 1."}],
      trap:"Thinking that losing a negative particle lowers Z: losing negative charge leaves the nucleus more positive, so Z rises."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"β⁻ decay",note:"electron emission"},{t:"mass number A",note:"protons + neutrons"},{t:"atomic number Z",note:"protons"}]},
      {text:"**What changes inside.** A neutron turns into a proton and throws out an electron.",calc:["n → p + e⁻ + ν̄"]},
      {text:"**Balance the top and bottom numbers.** The electron is ⁰₋₁e, so A is untouched and Z must go up by 1.",calc:["A: A = A + 0","Z: Z = (Z + 1) + (−1)"]},
      {text:"**Rule to reuse:** β⁻ decay keeps A the same and raises Z by 1."}]},
  {id:"cpt-pe1-42b",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:42#2"],
    q:"Strontium-90 and iodine-131, two fission products in reactor waste, are both β⁻ emitters. Which daughter nuclides do they form?",
    choices:["Yttrium-90 and xenon-131","Rubidium-90 and tellurium-131","Yttrium-90 and tellurium-131","Krypton-86 and antimony-127"],ans:0,
    exp:"β⁻ decay keeps **A** and raises **Z by 1**. Sr (Z = 38) → **Y (39)**, A stays 90; I (Z = 53) → **Xe (54)**, A stays 131. Rubidium and tellurium lower Z (β⁺), and krypton-86 with antimony-127 lose 4 mass units (α).",
    how:{ask:"Apply A unchanged, Z + 1 to each parent, then name the element with the new Z.",
      know:"• **β⁻ decay**: A unchanged, **Z + 1**.\n• Z sets the element: Kr 36, Rb 37, Sr 38, Y 39; Sb 51, Te 52, I 53, Xe 54.",
      steps:[{text:"Both parents are β⁻ emitters: keep A, add 1 to Z.",hl:"both β⁻ emitters",calc:["A → A, Z → Z + 1"]},
        {text:"Strontium-90 (Z = 38).",hl:"Strontium-90",calc:["⁹⁰₃₈Sr → ⁹⁰₃₉Y + ⁰₋₁e + ν̄","Z: 38 = 39 + (−1) ✓   A: 90 = 90 ✓"]},
        {text:"Iodine-131 (Z = 53).",hl:"iodine-131",calc:["¹³¹₅₃I → ¹³¹₅₄Xe + ⁰₋₁e + ν̄","Z: 53 = 54 + (−1) ✓   A: 131 = 131 ✓"]},
        {text:"Rubidium and tellurium have Z − 1 (positron emission); one correct daughter paired with tellurium is still wrong; krypton-86 and antimony-127 are alpha products.",strike:["Rubidium-90 and tellurium-131","Yttrium-90 and tellurium-131","Krypton-86 and antimony-127"]},
        {text:"Answer: yttrium-90 and xenon-131."}],
      trap:"Moving one step left on the periodic table (rubidium, tellurium): that is β⁺ decay. β⁻ moves one step right."},
    teach:[{text:"First, **find the parents and the decay type**.",marks:[{t:"Strontium-90",note:"Z = 38, A = 90"},{t:"iodine-131",note:"Z = 53, A = 131"},{t:"β⁻ emitters",note:"A same, Z + 1"}]},
      {text:"**Keep the mass number.** The emitted electron carries no nucleons.",calc:["daughters: A = 90 and A = 131"]},
      {text:"**Step one element to the right.** Z + 1 is the next element in the periodic table.",calc:["Sr (38) → Y (39)","I (53) → Xe (54)"]},
      {text:"**Rule to reuse:** for β⁻ decay, keep A and move one element right (Z + 1) to name the daughter."}]},
  // ── Practice Exam 1 · Chem/Phys, biochemistry: Q12, 22, 23, 32, 34, 41 (the first full 50-card day) ──
  // pe1-cp:12 (an enzyme lowers Ea by stabilizing the transition state; ΔG and K do not change; over-tight substrate binding does not help)
  {id:"cpt-pe1-12a",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:12#1"],
    q:"A protease binds the tetrahedral intermediate of peptide hydrolysis much more tightly than it binds the intact peptide. How does this binding speed the reaction?",
    choices:["Lowers activation energy","Makes the reaction exergonic","Shifts equilibrium to products","Raises the temperature"],ans:0,
    exp:"The tetrahedral intermediate resembles the **transition state**. Binding it tightly **stabilizes the transition state**, so the top of the energy hill drops and the **activation energy (Ea)** falls. Reactant and product energies are untouched, so ΔG and the equilibrium stay the same, and an enzyme does not heat the solution.",
    how:{ask:"Decide which part of the energy diagram the enzyme changes when it grips the transition-state-like species.",
      know:"• **Ea = transition-state energy − reactant energy**; a lower Ea means a faster reaction.\n• An enzyme binds the **transition state** more tightly than the substrate, lowering the peak of the curve.\n• **ΔG = products − reactants**: the enzyme does not move either end, so ΔG and K are unchanged.",
      steps:[{text:"The enzyme grips the species that looks like the transition state, not the starting peptide.",hl:"binds the tetrahedral intermediate of peptide hydrolysis much more tightly than it binds the intact peptide"},
        {text:"Stabilizing the transition state lowers the peak; read both barriers from the curves.",chart:{type:"line",caption:"Peptide hydrolysis with and without the protease",x:{label:"Reaction progress",min:0,max:10,step:2},y:{label:"Free energy (kJ/mol)",min:-40,max:100,step:20},series:[{name:"No enzyme",marker:"circle",line:"smooth",points:[[0,0],[1,0],[3,40],[5,90],[7,30],[9,-30],[10,-30]]},{name:"With protease",marker:"square-open",line:"smooth",points:[[0,0],[1,0],[3,20],[5,50],[7,10],[9,-30],[10,-30]]}]},calc:["Ea without enzyme = 90 − 0 = **90 kJ/mol**","Ea with protease = 50 − 0 = **50 kJ/mol**","ΔG = −30 − 0 = **−30 kJ/mol** on both curves"]},
        {text:"Both curves start and end at the same heights, so ΔG and the position of equilibrium are unchanged.",strike:["Makes the reaction exergonic","Shifts equilibrium to products"]},
        {text:"An enzyme works at the temperature of its surroundings; it does not heat them.",strike:["Raises the temperature"]},
        {text:"Answer: it lowers the activation energy."}],
      trap:"Thinking a faster reaction must also be a more favorable one: speed depends on Ea, favorability on ΔG, and an enzyme changes only Ea."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"tetrahedral intermediate",note:"looks like the transition state"},{t:"much more tightly",note:"preferential binding"},{t:"speed the reaction",note:"a rate question"}]},
      {text:"**Read the energy diagram.** The left plateau is the reactants, the right plateau the products, the peak the transition state. The enzyme's curve has a lower peak but the same ends.",chart:{type:"line",caption:"Same reaction, two paths",x:{label:"Reaction progress",min:0,max:10,step:2},y:{label:"Free energy (kJ/mol)",min:-40,max:100,step:20},series:[{name:"No enzyme",marker:"circle",line:"smooth",points:[[0,0],[1,0],[3,40],[5,90],[7,30],[9,-30],[10,-30]]},{name:"With protease",marker:"square-open",line:"smooth",points:[[0,0],[1,0],[3,20],[5,50],[7,10],[9,-30],[10,-30]]}]}},
      {text:"**Measure the hill.** Ea is peak minus start.",calc:["no enzyme: 90 − 0 = 90 kJ/mol","with protease: 50 − 0 = 50 kJ/mol","barrier is 40 kJ/mol lower → faster"]},
      {text:"**Why tight binding of the transition state works:** the binding energy is released at the peak, which pulls the peak down."},
      {text:"**Rule to reuse:** an enzyme speeds a reaction by stabilizing the transition state, which lowers Ea; it never changes the start or end energies."}]},
  {id:"cpt-pe1-12b",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:12#2"],
    q:"An uncatalyzed isomerization has equilibrium constant K at 30 °C. A catalyst is added and the temperature is held constant. Which property of the reaction changes?",
    choices:["Equilibrium constant","Standard free energy","Time to equilibrium","Equilibrium yield"],ans:2,
    exp:"A catalyst lowers the activation energy of the forward **and** reverse reactions by the same amount, so equilibrium is reached **sooner**. It does not change the energies of reactants or products, so **ΔG°**, **K** (still 6) and the amount of product at equilibrium all stay the same.",
    how:{ask:"Separate the properties set by the start and end energies from the one set by the height of the barrier.",
      know:"• **ΔG° = −RT ln K**: both depend only on reactant and product energies.\n• A catalyst lowers Ea for **both directions** equally, so forward and reverse rates rise by the same factor.\n• Same K → same equilibrium mixture; only the **speed of getting there** changes.",
      steps:[{text:"The temperature is fixed, so K can change only if ΔG° changes.",hl:"the temperature is held constant"},
        {text:"Compare the two paths: the ends sit at the same heights; only the peak is lower.",chart:{type:"line",caption:"Isomerization with and without the catalyst",x:{label:"Reaction progress",min:0,max:10,step:2},y:{label:"Free energy (kJ/mol)",min:-40,max:80,step:20},series:[{name:"Uncatalyzed",marker:"circle",line:"smooth",points:[[0,0],[1,0],[3,35],[5,70],[7,20],[9,-20],[10,-20]]},{name:"Catalyzed",marker:"square-open",line:"smooth",points:[[0,0],[1,0],[3,15],[5,40],[7,0],[9,-20],[10,-20]]}]},calc:["ΔG° = −20 − 0 = **−20 kJ/mol** on both curves","Ea forward: 70 → 40 kJ/mol","Ea reverse: 70 − (−20) = 90 → 40 − (−20) = 60 kJ/mol","both barriers drop by **30 kJ/mol**"]},
        {text:"Same ΔG° means the same K and the same mixture at equilibrium.",strike:["Equilibrium constant","Standard free energy","Equilibrium yield"]},
        {text:"Answer: the time to equilibrium, which becomes shorter."}],
      trap:"Thinking a catalyst pushes the reaction toward products: it speeds the reverse reaction just as much, so the final mixture is the same."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"equilibrium constant K",note:"set by ΔG°"},{t:"A catalyst is added",note:"lowers Ea"},{t:"held constant",note:"no temperature effect"}]},
      {text:"**Two different questions.** \"How far?\" is answered by ΔG° and K. \"How fast?\" is answered by Ea."},
      {text:"**Link ΔG° and K.** At a fixed temperature they move together, and both depend only on the ends of the diagram.",calc:["ΔG° = −RT ln K","same ends → same ΔG° → same K"]},
      {text:"**Both directions speed up.** The catalyst lowers the forward and reverse barriers equally, so the ratio of the forward and reverse rate constants (k_f/k_r = K) is unchanged."},
      {text:"**Rule to reuse:** a catalyst changes only how fast equilibrium is reached, never ΔG°, K or the equilibrium mixture."}]},
  {id:"cpt-pe1-12c",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:12#3"],
    q:"A mutant enzyme binds its substrate far more tightly than the wild type but binds the transition state equally well, just as the wild type does. How does the activation energy from the ES complex change?",
    choices:["It increases","It decreases","It is unchanged","It drops to zero"],ans:0,
    exp:"Tighter substrate binding **lowers the energy of the ES complex** (a deeper valley), but the transition state sits at the **same height**. The climb from ES to the transition state is therefore **taller**, so the activation energy increases and catalysis slows. Enzymes work by binding the transition state more tightly than the substrate.",
    how:{ask:"Find what moves when only substrate binding gets tighter: the ES valley or the transition-state peak.",
      know:"• **Ea from ES = transition-state energy − ES energy.**\n• Tighter substrate binding → ES lower; tighter transition-state binding → peak lower.\n• Only lowering the peak relative to ES speeds catalysis.",
      steps:[{text:"Two facts: ES drops lower, and the transition state stays where it was.",hl:"binds its substrate far more tightly than the wild type but binds the transition state equally well"},
        {text:"Read the two barriers from ES up to the peak.",chart:{type:"line",caption:"Free energy from E + S through ES to products",x:{label:"Reaction progress",min:0,max:10,step:2},y:{label:"Free energy (kJ/mol)",min:-40,max:60,step:20},series:[{name:"Wild type",marker:"circle",line:"smooth",points:[[0,0],[2,-10],[4,-10],[6,50],[8,-20],[10,-20]]},{name:"Tight-binding mutant",marker:"square-open",line:"smooth",points:[[0,0],[2,-35],[4,-35],[6,50],[8,-20],[10,-20]]}]},calc:["wild type: 50 − (−10) = **60 kJ/mol**","mutant: 50 − (−35) = **85 kJ/mol**","barrier is **25 kJ/mol higher**"]},
        {text:"The barrier grew, so it did not fall, stay the same, or vanish.",strike:["It decreases","It is unchanged","It drops to zero"]},
        {text:"Answer: it increases."}],
      trap:"Assuming tighter binding always means better catalysis: binding the substrate too tightly digs a pit the enzyme must climb out of."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"far more tightly",note:"ES valley deeper"},{t:"transition state equally well",note:"peak unchanged"},{t:"from the ES complex",note:"measure from ES"}]},
      {text:"**Draw the valley and the peak.** E + S drops into an ES valley, then climbs to the transition state.",chart:{type:"line",caption:"Deeper ES valley, same peak",x:{label:"Reaction progress",min:0,max:10,step:2},y:{label:"Free energy (kJ/mol)",min:-40,max:60,step:20},series:[{name:"Wild type",marker:"circle",line:"smooth",points:[[0,0],[2,-10],[4,-10],[6,50],[8,-20],[10,-20]]},{name:"Tight-binding mutant",marker:"square-open",line:"smooth",points:[[0,0],[2,-35],[4,-35],[6,50],[8,-20],[10,-20]]}]}},
      {text:"**Measure from where the enzyme starts its chemistry**, the ES complex.",calc:["Ea = peak − ES","lower ES, same peak → larger Ea"]},
      {text:"**What a good enzyme does:** it binds the transition state more tightly than the substrate, so the peak falls more than the valley."},
      {text:"**Rule to reuse:** catalysis needs the transition state stabilized more than the substrate; extra substrate binding alone raises the barrier."}]},

  // pe1-cp:22 (oxidized cysteines form covalent, intermolecular disulfides; reducing agents break them)
  {id:"cpt-pe1-22a",s:"Protein Structure",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:22#1"],
    q:"A purified enzyme left in air slowly forms a link between two of its cysteine side chains. What kind of interaction is this link?",
    choices:["Covalent bond","Hydrogen bond","Salt bridge","London dispersion"],ans:0,
    exp:"O₂ from the air **oxidizes** the side chains: each cysteine **thiol (–SH)** loses its H and the two sulfurs bond, giving a **disulfide (–S–S–)**. Electrons are shared between the sulfurs, so it is a **covalent bond**, far stronger than hydrogen bonds, salt bridges or dispersion forces.",
    how:{ask:"Name the link that forms when cysteine side chains are oxidized, then classify it.",
      know:"• Cysteine side chain: –CH₂–**SH** (a thiol).\n• **Oxidation**: 2 R–SH → R–S–S–R + 2 H⁺ + 2 e⁻ (a **disulfide**).\n• The S–S bond is a shared electron pair: **covalent**.\n• Hydrogen bonds, salt bridges and dispersion forces are noncovalent and do not need oxidation.",
      steps:[{text:"Air is the oxidant and cysteine is the residue.",hl:"left in air slowly forms a link between two of its cysteine side chains"},
        {text:"Write the reaction.",calc:["2 Cys–SH + ½ O₂ → Cys–S–S–Cys + H₂O","S–S = shared electron pair → **covalent**"]},
        {text:"These are noncovalent attractions, and none needs oxidation to form.",strike:["Hydrogen bond","Salt bridge","London dispersion"]},
        {text:"Answer: a covalent bond (a disulfide)."}],
      trap:"Calling the disulfide a weak side-chain interaction like the others in tertiary structure: it is the one covalent cross-link among them."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"left in air",note:"O₂ oxidizes"},{t:"cysteine side chains",note:"thiols, –SH"}]},
      {text:"**Cysteine carries a thiol.** Its side chain ends in S–H.",fig:"cysteine"},
      {text:"**Oxidation joins two thiols.** Both H's leave and the sulfurs bond to each other.",calc:["R–SH + HS–R → R–S–S–R"]},
      {text:"**Classify the bond.** The sulfurs share electrons: a covalent bond, unlike the noncovalent forces that also shape proteins."},
      {text:"**Rule to reuse:** oxidizing two cysteine thiols makes a disulfide, a covalent S–S bond."}]},
  {id:"cpt-pe1-22b",s:"Protein Structure",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:22#2"],
    q:"In wool, a disulfide bond joins a cysteine on one keratin chain to a cysteine on a separate keratin chain. How is this cross-link classified?",
    choices:["Covalent and intermolecular","Covalent and intramolecular","Noncovalent and intermolecular","Noncovalent and intramolecular"],ans:0,
    exp:"An S–S bond is a shared electron pair, so it is **covalent**. It joins **two separate molecules** (two different chains), so it is **intermolecular**. A disulfide between two cysteines of the **same** chain would be intramolecular.",
    how:{ask:"Answer two questions in turn: what type of bond is S–S, and does it join one molecule to itself or two molecules?",
      know:"• **Disulfide** = covalent S–S bond between two cysteines.\n• **Intra**molecular = within one molecule; **inter**molecular = between different molecules.\n• Two separate polypeptide chains are two molecules.",
      steps:[{text:"The bond type is given: a disulfide.",hl:"a disulfide bond",calc:["S–S = shared electrons → **covalent**"]},
        {text:"Disulfides are covalent, so the noncovalent pair is out.",strike:["Noncovalent and intermolecular","Noncovalent and intramolecular"]},
        {text:"The two cysteines sit on different chains.",hl:"a separate keratin chain",calc:["chain 1 ↔ chain 2 → **intermolecular**"]},
        {text:"A link within one chain would be intramolecular, which is not the case here.",strike:["Covalent and intramolecular"]},
        {text:"Answer: covalent and intermolecular."}],
      trap:"Reading \"intermolecular\" as \"noncovalent\": the prefix only tells you that two different molecules are joined, whatever the bond type."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"disulfide bond",note:"covalent S–S"},{t:"one keratin chain",note:"molecule 1"},{t:"a separate keratin chain",note:"molecule 2"}]},
      {text:"**Bond type.** Two cysteine sulfurs share electrons, so the link is covalent.",fig:"cysteine"},
      {text:"**Count the molecules.** Inter = between; intra = within.",calc:["same chain → intramolecular","different chains → intermolecular"]},
      {text:"**Rule to reuse:** a disulfide is always covalent; it is intermolecular when its two cysteines belong to different molecules."}]},
  {id:"cpt-pe1-22c",s:"Protein Structure",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:22#3"],
    q:"Hair proteins held together by disulfide cross-links are soaked in β-mercaptoethanol, a reducing agent. What happens to the cross-links?",
    choices:["Reduced to thiols","Oxidized further","Converted to peptide bonds","Made stronger"],ans:0,
    exp:"A disulfide forms by **oxidation**, so a **reducing agent** reverses it: it adds electrons (as H atoms) back to the sulfurs, giving two separate **–SH thiols**. The cross-links break, so the chains are no longer covalently tied together.",
    how:{ask:"Decide which direction a reducing agent drives the thiol ⇌ disulfide reaction.",
      know:"• 2 R–SH ⇌ R–S–S–R + 2 H⁺ + 2 e⁻.\n• **Oxidation** (losing electrons) goes right and forms S–S; **reduction** (gaining electrons) goes left and breaks it.\n• Common reducing agents: β-mercaptoethanol, dithiothreitol (DTT).",
      steps:[{text:"The reagent is a reducing agent.",hl:"a reducing agent"},
        {text:"Reduction runs the disulfide reaction backward.",calc:["R–S–S–R + 2 H⁺ + 2 e⁻ → 2 R–SH","the S–S bond is **broken**"]},
        {text:"A reducing agent cannot oxidize, and breaking a link does not strengthen it.",strike:["Oxidized further","Made stronger"]},
        {text:"Sulfurs cannot become amide links between C=O and N–H.",strike:["Converted to peptide bonds"]},
        {text:"Answer: the disulfides are reduced to thiols."}],
      trap:"Mixing up the directions: oxidation makes disulfides, reduction breaks them."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"disulfide cross-links",note:"S–S, made by oxidation"},{t:"a reducing agent",note:"adds electrons back"}]},
      {text:"**One reaction, two directions.**",calc:["oxidation: 2 R–SH → R–S–S–R","reduction: R–S–S–R → 2 R–SH"]},
      {text:"**After reduction** each cysteine has its own –SH again, and the two chains are no longer tied.",fig:"cysteine"},
      {text:"**Rule to reuse:** reducing agents such as β-mercaptoethanol or DTT break disulfides back into two thiols."}]},

  // pe1-cp:23 (charged side chains bind electrostatically; Gly has no side chain; match each residue to its region)
  {id:"cpt-pe1-23a",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:23#1"],
    q:"A cell-surface protein has a patch of negatively charged carboxylate groups. Which residue in a ligand peptide could bind this patch electrostatically at physiological pH?",
    choices:["Arginine","Leucine","Glutamate","Phenylalanine"],ans:0,
    exp:"An **electrostatic** (ionic) attraction needs opposite charges, so the peptide must offer a **positive** side chain. Arginine's guanidinium group stays **+** at body pH. Glutamate is **−** like the patch and would repel it; leucine and phenylalanine are nonpolar and uncharged.",
    how:{ask:"Decide which charge the peptide must carry, then find the residue whose side chain has it at body pH.",
      know:"• **Charged side chains at body pH**: Asp (−), Glu (−), Lys (+), Arg (+); His is partly +.\n• Opposite charges attract (salt bridge); like charges repel.\n• Nonpolar side chains (Leu, Phe, Val …) carry no charge.",
      steps:[{text:"The patch is negative, so the peptide needs a positive side chain.",hl:"negatively charged carboxylate groups"},
        {text:"Sort the choices by side-chain charge.",calc:["Arg: **+** (guanidinium)","Glu: **−** (carboxylate)","Leu, Phe: **0** (hydrocarbon)"]},
        {text:"Glutamate would repel the negative patch.",strike:["Glutamate"]},
        {text:"Leucine and phenylalanine have no charge to attract with.",strike:["Leucine","Phenylalanine"]},
        {text:"Answer: arginine."}],
      trap:"Picking glutamate because it is charged: it carries the same charge as the patch, so it repels rather than binds."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"negatively charged",note:"partner must be +"},{t:"electrostatically",note:"charge–charge attraction"},{t:"physiological pH",note:"use body-pH charges"}]},
      {text:"**Know the charged five.** Asp and Glu are − ; Lys and Arg are + ; His can be + .",fig:["aspartate","glutamate","lysine","arginine","histidine"]},
      {text:"**Arginine's side chain** ends in a guanidinium group that holds a + charge at body pH.",fig:"arginine"},
      {text:"**Match opposites.** + binds −; − repels −; uncharged side chains cannot form ionic bonds."},
      {text:"**Rule to reuse:** for an electrostatic contact, choose a side chain charged opposite to the partner: Lys or Arg for a − site, Asp or Glu for a + site."}]},
  {id:"cpt-pe1-23b",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:23#2"],
    q:"A designer replaces every lysine in a cell-binding peptide with glycine, and binding to the charged cell surface is lost. What does glycine supply as its side chain?",
    choices:["Only a hydrogen","A positive charge","A negative charge","A thiol group"],ans:0,
    exp:"Glycine's R group is a **single hydrogen atom**, so it effectively has **no side chain**: no charge and no functional group. Swapping lysine (a + amine) for glycine removes the + charges the peptide used to attract the surface, so binding is lost.",
    how:{ask:"Recall glycine's R group and ask whether it can carry a charge.",
      know:"• Amino acid = H₂N–CH(**R**)–COOH; the R group is the side chain.\n• **Glycine**: R = H, the smallest possible, with no charge.\n• Lysine: R ends in –NH₃⁺ (positive); Cys: R = –CH₂SH (thiol).",
      steps:[{text:"Binding was lost when lysine became glycine.",hl:"replaces every lysine in a cell-binding peptide with glycine"},
        {text:"Compare the two R groups.",calc:["Lys: R = –(CH₂)₄–NH₃⁺ → **+**","Gly: R = **–H** → no charge, no group"]},
        {text:"The positive charge belonged to lysine and left with it; glycine has no carboxylate either.",strike:["A positive charge","A negative charge"]},
        {text:"A thiol is cysteine's side chain, not glycine's.",strike:["A thiol group"]},
        {text:"Answer: only a hydrogen."}],
      trap:"Treating every residue as if it brings some group to the surface: glycine brings none, which is why it is used as a flexible spacer."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"lysine",note:"+ side chain"},{t:"glycine",note:"R = H"},{t:"binding to the charged cell surface is lost",note:"a charge was removed"}]},
      {text:"**Glycine is the bare backbone.** Its R group is just H.",fig:"glycine"},
      {text:"**Lysine brought the charge.** Its long chain ends in an amine that is + at body pH.",fig:"lysine"},
      {text:"**Rule to reuse:** glycine has no side chain (R = H), so it adds no charge or functional group to a binding site."}]},
  {id:"cpt-pe1-23c",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:23#3"],
    q:"A designed peptide has a cross-linking region A (Gly–Cys–Gly–Cys) and a cell-binding region B (Lys–Glu–Arg–Asp). Which residue gives cells a charged group to bind?",
    choices:["Arg in region B","Cys in region A","Gly in region A","Cys in region B"],ans:0,
    exp:"Match each residue to its region first. Region A holds **Gly** (no side chain) and **Cys** (a thiol for disulfide cross-links), so it offers no charge. Region B holds Lys, Glu, Arg and Asp, all **charged** at body pH; **Arg** is one of them. There is no Cys in region B.",
    how:{ask:"List the residues in each region, then find a charged one in the region where it actually sits.",
      know:"• Charged at body pH: Asp −, Glu −, Lys +, Arg +.\n• **Cys** = thiol for **disulfide cross-links**, not a charge.\n• **Gly** = no side chain.\n• A choice must name a residue that is really in the region it names.",
      steps:[{text:"Write out the two regions.",hl:"Gly–Cys–Gly–Cys",calc:["region A: Gly, Cys → cross-linking","region B: Lys, Glu, Arg, Asp → all charged"]},
        {text:"Region A has no charged side chain: Gly has none, and Cys forms disulfides.",strike:["Cys in region A","Gly in region A"]},
        {text:"Cys does not appear in region B, so that pairing is wrong.",hl:"Lys–Glu–Arg–Asp",strike:["Cys in region B"]},
        {text:"Answer: Arg in region B."}],
      trap:"Choosing cysteine because its sulfur looks reactive: it belongs to the cross-linking region and gives a covalent link between strands, not a charge for cells."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"cross-linking region A",note:"Cys for disulfides"},{t:"cell-binding region B",note:"charged residues"},{t:"charged group",note:"Asp, Glu, Lys, Arg"}]},
      {text:"**Sort by job.** Cys makes S–S cross-links; Gly is a spacer; charged residues bind cells.",fig:["cysteine","glycine"]},
      {text:"**Check the charged ones.**",calc:["Lys +, Arg +","Glu −, Asp −"],fig:["arginine","glutamate"]},
      {text:"**Check the location too.** A right residue in the wrong region is a wrong answer."},
      {text:"**Rule to reuse:** match each residue to its labeled region and its job: Cys cross-links, Gly adds nothing, and Asp, Glu, Lys, Arg give charges."}]},

  // pe1-cp:32 (a kinase transfers ATP's γ phosphate; the kinase is the catalyst, not the source)
  {id:"cpt-pe1-32a",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:32#1"],
    q:"ATP is synthesized with ³³P in its β-phosphate only. After hexokinase converts glucose to glucose 6-phosphate with this ATP, where is the label found?",
    choices:["In ADP","In glucose 6-phosphate","In free phosphate","In AMP"],ans:0,
    exp:"Hexokinase, like every kinase, transfers ATP's **terminal (γ) phosphate** to its substrate. The **α and β phosphates stay** behind as ADP, so a label on β ends up in **ADP**, not in glucose 6-phosphate.",
    how:{ask:"Find which of ATP's three phosphates the kinase moves, then see where the β phosphate ends up.",
      know:"• ATP phosphates, from the ribose outward: **α, β, γ**.\n• Kinase: ATP + R–OH → **ADP + R–O–PO₃²⁻**; only **γ** moves.\n• ADP keeps α and β; AMP would keep only α.",
      steps:[{text:"The label is on β, the middle phosphate.",hl:"³³P in its β-phosphate only"},
        {text:"Write the kinase reaction.",calc:["glucose + ATP(α–β*–γ) → glucose–O–P(γ) + ADP(α–β*)","label (*) stays in **ADP**"]},
        {text:"Only γ reaches the glucose, and no phosphate is released free.",strike:["In glucose 6-phosphate","In free phosphate"]},
        {text:"AMP would form only if β and γ left together, which a kinase does not do.",strike:["In AMP"]},
        {text:"Answer: in ADP."}],
      trap:"Assuming any phosphorus label in ATP is passed on: a kinase moves only the γ phosphate."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"β-phosphate",note:"the middle one"},{t:"hexokinase",note:"a kinase"},{t:"glucose 6-phosphate",note:"gets one phosphate"}]},
      {text:"**Name ATP's phosphates** from the sugar out: α, β, γ.",fig:"atp"},
      {text:"**A kinase moves the end one.** The γ phosphate goes to the substrate; α and β stay as ADP.",calc:["ATP → ADP + γ-phosphate (to substrate)"]},
      {text:"**Rule to reuse:** kinases transfer ATP's γ (terminal) phosphate; any label on α or β stays in ADP."}]},
  {id:"cpt-pe1-32b",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:32#2"],
    q:"Protein kinase A attaches a phosphoryl group to a serine on its target protein. What is the direct source of that phosphoryl group?",
    choices:["ATP","Protein kinase A","Inorganic phosphate","The serine residue"],ans:0,
    exp:"Protein kinase A is the **enzyme**: it catalyzes the transfer and is unchanged afterward. The phosphoryl group comes from the **γ phosphate of ATP**, which leaves as ADP. Free inorganic phosphate is not the donor, and serine is the acceptor.",
    how:{ask:"Separate the catalyst from the donor and the acceptor in the reaction.",
      know:"• Kinase reaction: ATP + protein–Ser–OH → ADP + protein–Ser–O–PO₃²⁻.\n• **Donor** = ATP (γ phosphate); **acceptor** = the serine –OH; **catalyst** = the kinase.\n• A catalyst is not consumed and does not supply atoms to the product.",
      steps:[{text:"Write the reaction with each role.",hl:"attaches a phosphoryl group to a serine",calc:["ATP + Ser–OH → ADP + Ser–O–PO₃²⁻","kinase over the arrow = **catalyst**"]},
        {text:"The kinase only speeds the transfer and comes out unchanged.",strike:["Protein kinase A"]},
        {text:"Serine receives the phosphate, and kinases use ATP, not free phosphate.",strike:["The serine residue","Inorganic phosphate"]},
        {text:"Answer: ATP."}],
      trap:"Naming the kinase as the source because it \"adds\" the phosphate: the enzyme moves the group but does not provide it."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Protein kinase A",note:"the enzyme"},{t:"a serine",note:"the acceptor"},{t:"direct source",note:"the donor"}]},
      {text:"**Three roles.** Donor gives the group, acceptor takes it, enzyme makes it happen.",calc:["donor: ATP","acceptor: Ser–OH","catalyst: kinase"]},
      {text:"**Where the phosphate starts**: the end (γ) phosphate of ATP.",fig:"atp"},
      {text:"**Rule to reuse:** a kinase is the catalyst; the phosphate it attaches comes from ATP's γ phosphate."}]},

  // pe1-cp:34 (lipases hydrolyze triacylglycerol esters; pancreatic lipase cuts positions 1 and 3)
  {id:"cpt-pe1-34a",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:34#1"],
    q:"In fat cells, a lipase breaks down stored triacylglycerol with water. Which bond does it hydrolyze, and which product is released?",
    choices:["Ester; fatty acid","Amide; amino acid","Glycosidic; glucose","Ether; fatty acid"],ans:0,
    exp:"A triacylglycerol is glycerol joined to three fatty acids by **ester** bonds. A lipase adds water across an ester, giving back the **free fatty acid** (a carboxylic acid) and an –OH on glycerol. Amide bonds join amino acids, glycosidic bonds join sugars, and a triacylglycerol has no ether link.",
    how:{ask:"Identify the bond that links fatty acids to glycerol, then what hydrolysis of it releases.",
      know:"• **Triacylglycerol** = glycerol + 3 fatty acids, each attached by an **ester** (C(=O)–O–C).\n• **Ester hydrolysis**: R–C(=O)–O–R′ + H₂O → R–COOH + HO–R′.\n• Amide = protein link; glycosidic = carbohydrate link.",
      steps:[{text:"The substrate is a fat and the reaction uses water.",hl:"breaks down stored triacylglycerol with water"},
        {text:"Find the bond and write its hydrolysis.",calc:["fatty acid–C(=O)–O–glycerol + H₂O","→ fatty acid–COOH + HO–glycerol"]},
        {text:"Amide and glycosidic bonds belong to proteins and sugars, not fats.",strike:["Amide; amino acid","Glycosidic; glucose"]},
        {text:"The acyl chains are attached through C=O, an ester, not an ether.",strike:["Ether; fatty acid"]},
        {text:"Answer: ester; fatty acid."}],
      trap:"Choosing ether because an oxygen bridges the chain and glycerol: the carbon on one side is a C=O, which makes it an ester."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"lipase",note:"fat-splitting enzyme"},{t:"triacylglycerol",note:"three esters"},{t:"with water",note:"hydrolysis"}]},
      {text:"**Read the fat.** Glycerol carries three acyl chains, each through an ester.",fig:"triacylglycerol"},
      {text:"**Hydrolysis splits each ester** into an acid and an alcohol.",calc:["ester + H₂O → carboxylic acid + alcohol"]},
      {text:"**Rule to reuse:** lipases hydrolyze the ester bonds of triacylglycerols, releasing free fatty acids."}]},
  {id:"cpt-pe1-34b",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:34#2"],
    q:"Pancreatic lipase digests a dietary triacylglycerol made of three oleic acid chains. Which final products does the enzyme release?",
    choices:["Two fatty acids; 2-monoacylglycerol","Three fatty acids; glycerol","One fatty acid; 1,2-diacylglycerol","Two fatty acids; 1-monoacylglycerol"],ans:0,
    exp:"Pancreatic lipase cuts only the esters at **positions 1 and 3** of glycerol. Two cuts free **two oleic acids**, and the acyl chain at **C2** stays on: a **2-monoacylglycerol**. Glycerol would need three cuts and a diacylglycerol only one, and a 1-monoacylglycerol would mean the middle ester had been cut.",
    how:{ask:"Use the enzyme's position rule to count the cuts and see which chain stays on glycerol.",
      know:"• Glycerol carbons: C1 and C3 are the ends; C2 is the middle.\n• **Pancreatic lipase** hydrolyzes the **C1 and C3** esters only.\n• Products: **2 fatty acids + 2-monoacylglycerol** (named for the carbon still holding a chain).",
      steps:[{text:"The enzyme is pancreatic lipase, which works at the end positions.",hl:"Pancreatic lipase"},
        {text:"Apply the position rule.",calc:["cut C1 ester → 1 oleic acid","cut C3 ester → 1 oleic acid","C2 ester kept → **2-monoacylglycerol**","total: **2** fatty acids"]},
        {text:"Three cuts or one cut does not match the two end positions.",strike:["Three fatty acids; glycerol","One fatty acid; 1,2-diacylglycerol"]},
        {text:"A chain left on C1 would mean the middle ester was cut, which this enzyme does not do.",strike:["Two fatty acids; 1-monoacylglycerol"]},
        {text:"Answer: two fatty acids and a 2-monoacylglycerol."}],
      trap:"Assuming digestion goes all the way to glycerol: pancreatic lipase leaves the middle chain in place."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Pancreatic lipase",note:"cuts C1 and C3"},{t:"three oleic acid chains",note:"three esters to start"}]},
      {text:"**Number glycerol's carbons** 1, 2, 3; each holds one ester.",fig:"triacylglycerol"},
      {text:"**Cut only the ends.** Two acids leave; the middle chain stays.",calc:["3 chains − 2 cut = 1 left, on C2"]},
      {text:"**Rule to reuse:** pancreatic lipase hydrolyzes positions 1 and 3, giving two fatty acids and a 2-monoacylglycerol."}]},

  // pe1-cp:41 (a phosphatase removes phosphate, so a ³²P label is lost; a ¹⁴C label in the sugar stays)
  {id:"cpt-pe1-41a",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:41#1"],
    q:"A phosphorylated enzyme carries ³²P in its phosphoserines and ³H in its leucines. It is incubated with a protein phosphatase. Which label is lost from the enzyme?",
    choices:["³²P only","³H only","Both labels","Neither label"],ans:0,
    exp:"A phosphatase **hydrolyzes phosphate esters**, releasing the phosphate as free Pᵢ. The ³²P rides on that phosphate, so it leaves the enzyme. The ³H is built into the leucine side chains, which the phosphatase does not touch, so it stays.",
    how:{ask:"Place each label on its chemical group, then ask which group the phosphatase removes.",
      know:"• **Phosphatase**: R–O–PO₃²⁻ + H₂O → R–OH + Pᵢ (removes phosphate).\n• A radioactive label goes wherever its atom goes.\n• Kinase adds phosphate; phosphatase takes it off.",
      steps:[{text:"Locate each label.",hl:"³²P in its phosphoserines and ³H in its leucines",calc:["³²P → phosphate groups","³H → leucine side chains"]},
        {text:"The phosphatase cuts off the phosphate.",calc:["Ser–O–PO₃²⁻(³²P) + H₂O → Ser–OH + Pᵢ(³²P)","³²P **leaves**; ³H **stays**"]},
        {text:"Leucine is untouched, so ³H cannot be lost; and removing phosphate must take ³²P with it.",strike:["³H only","Both labels","Neither label"]},
        {text:"Answer: ³²P only."}],
      trap:"Thinking the phosphatase degrades the whole protein: it removes only phosphate groups."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"³²P in its phosphoserines",note:"label on phosphate"},{t:"³H in its leucines",note:"label on the protein"},{t:"protein phosphatase",note:"removes phosphate"}]},
      {text:"**Each isotope tags one part.** Phosphorus is only in the phosphate; hydrogen here is in leucine.",fig:"leucine"},
      {text:"**Phosphatase = phosphate off.** The phosphate leaves as free Pᵢ.",calc:["phospho-protein + H₂O → protein + Pᵢ"]},
      {text:"**Rule to reuse:** a phosphatase removes phosphate groups, so a ³²P label on them leaves while labels elsewhere stay."}]},
  {id:"cpt-pe1-41b",s:"Enzymes & Kinetics",disc:"biochemistry",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:41#2"],
    q:"Glucose 6-phosphate labeled with ¹⁴C in all six carbons is treated with glucose-6-phosphatase. Where is the ¹⁴C found afterward?",
    choices:["In free glucose","In free phosphate","Split between both","Released as CO₂"],ans:0,
    exp:"Glucose-6-phosphatase hydrolyzes the O–P bond of the phosphate ester at C6, giving **glucose + Pᵢ**. All six carbons belong to the **sugar**, and phosphate contains no carbon, so every ¹⁴C stays in the **free glucose**. No carbon–carbon bond is broken, so no CO₂ forms.",
    how:{ask:"Decide which product contains the carbon atoms after the phosphate is removed.",
      know:"• **Phosphatase**: sugar–O–PO₃²⁻ + H₂O → sugar–OH + Pᵢ.\n• Phosphate (PO₄³⁻) has **no carbon**.\n• Releasing CO₂ requires breaking C–C bonds (decarboxylation), which a phosphatase does not do.",
      steps:[{text:"The label is in the sugar's carbons.",hl:"¹⁴C in all six carbons"},
        {text:"Write the hydrolysis.",calc:["glucose-6-O–PO₃²⁻ + H₂O → glucose + Pᵢ","6 labeled C → all in **glucose**","Pᵢ: 0 C"]},
        {text:"Phosphate has no carbon, so it cannot carry any ¹⁴C, alone or shared.",strike:["In free phosphate","Split between both"]},
        {text:"No C–C bond breaks, so no CO₂ is made.",strike:["Released as CO₂"]},
        {text:"Answer: in free glucose."}],
      trap:"Assuming the label follows whatever is cut off: a label stays with the atoms it is part of, and carbon is only in the sugar."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"¹⁴C in all six carbons",note:"label on the sugar"},{t:"glucose-6-phosphatase",note:"removes the phosphate"}]},
      {text:"**Split the molecule** into its sugar part and its phosphate part.",calc:["sugar: C₆ (all ¹⁴C)","phosphate: P and O only"]},
      {text:"**Only the phosphate leaves**; the carbon skeleton stays intact.",fig:"beta-glucopyranose"},
      {text:"**Rule to reuse:** a phosphatase removes only phosphate, so a ¹⁴C label in the sugar backbone stays with the sugar."}]},
  // ── Practice Exam 1 · Chem/Phys, physics, biology and organic: Q16, 17, 26, 30, 45, 46, 56, 59 ──
  // pe1-cp:16 (at a fixed color, intensity tracks the number of photons per second)
  {id:"cpt-pe1-16a",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 1",from:["pe1-cp:16#1"],
    q:"Two lamps emit the same 590-nm yellow light, but lamp X is three times as intense as lamp Y. What is tripled for lamp X?",
    choices:["Photon arrival rate","Energy of each photon","Speed of the photons","Degree of polarization"],ans:0,
    exp:"**Intensity = (photons per second × energy per photon) ÷ area.** One wavelength means one photon energy (E = hc/λ), so the only way to triple the intensity is to deliver **three times as many photons each second**. Light speed and polarization do not set intensity.",
    how:{ask:"Split intensity into its two factors. Which factor can change while the wavelength stays fixed?",
      know:"• **Intensity** = power ÷ area = (photons per second) × (energy per photon) ÷ area.\n• **E = hf = hc/λ**: the energy of one photon depends only on its color.\n• Light speed in air is fixed at about c = 3.00 × 10⁸ m/s, whatever the brightness.\n• **Polarization** is the direction the electric field oscillates in; it describes orientation, not amount.",
      steps:[{text:"Same wavelength for both lamps, so every photon carries the same energy.",hl:"the same 590-nm yellow light",calc:["E = hc ÷ λ","E = (6.63 × 10⁻³⁴ J·s)(3.00 × 10⁸ m/s) ÷ (590 × 10⁻⁹ m)","E ≈ **3.4 × 10⁻¹⁹ J** per photon, for both lamps"],strike:["Energy of each photon"]},
        {text:"Light from both lamps travels at c, and polarization only describes the direction of the field's oscillation, not how much light arrives.",strike:["Speed of the photons","Degree of polarization"]},
        {text:"Write intensity as a product and triple it: the only factor left to change is the photon rate.",hl:"three times as intense",calc:["I = (photons/s × E) ÷ A","3I = (**3** × photons/s) × (same E) ÷ A"],
          chart:{type:"line",caption:"Intensity of 590-nm light versus photon arrival rate",x:{label:"Photons per second (relative)",min:0,max:4,step:1},y:{label:"Intensity (relative)",min:0,max:4,step:1},series:[{name:"Intensity",marker:"circle",line:"straight",points:[[0,0],[1,1],[2,2],[3,3],[4,4]]}]}},
        {text:"Answer: photon arrival rate."}],
      trap:"Picking 'Energy of each photon' because intensity is an energy flow. If each photon carried more energy, the wavelength, and so the color, would have changed."},
    teach:[{text:"First, **find what is the same and what differs**.",marks:[{t:"the same 590-nm yellow light",note:"same color: same λ"},{t:"three times as intense",note:"brighter by 3×"},{t:"What is tripled",note:"find the factor that grew"}]},
      {text:"**Light comes in photons.** Each photon's energy is set by its color alone.",calc:["E = hf = hc/λ","same λ → same E"]},
      {text:"**Intensity counts energy arriving per second on each square metre.** It is photons per second times energy per photon.",calc:["I = (photons/s × E) ÷ A"]},
      {text:"**See it:** at one color, intensity rises in a straight line with the photon rate.",chart:{type:"line",caption:"Fixed color: intensity is proportional to photons per second",x:{label:"Photons per second (relative)",min:0,max:4,step:1},y:{label:"Intensity (relative)",min:0,max:4,step:1},series:[{name:"Intensity",marker:"circle",line:"straight",points:[[0,0],[1,1],[2,2],[3,3],[4,4]]}]}},
      {text:"**Rule to reuse:** for light of one color, intensity is proportional to the number of photons per second; speed, wavelength and polarization do not set it."}]},

  // pe1-cp:17 (E = hf with a THz frequency)
  {id:"cpt-pe1-17a",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 2",from:["pe1-cp:17#1"],
    q:"A green LED emits light at a frequency of 580 THz. Using Planck's constant in eV·s, how much energy does each emitted photon carry?",
    choices:["2.4 eV","0.0024 eV","0.24 eV","2400 eV"],ans:0,
    exp:"**E = hf** with **tera = 10¹²**: f = 5.8 × 10¹⁴ Hz, and E = (4.14 × 10⁻¹⁵ eV·s)(5.8 × 10¹⁴ s⁻¹) = 24 × 10⁻¹ eV = **2.4 eV**, a typical visible-light photon energy.",
    how:{ask:"Convert THz to Hz, multiply by Planck's constant in eV·s, and combine the powers of ten.",
      know:"• **E = hf**: E = photon energy, h = Planck's constant, f = frequency (Hz = s⁻¹).\n• **h = 6.63 × 10⁻³⁴ J·s = 4.14 × 10⁻¹⁵ eV·s** (1 eV = 1.60 × 10⁻¹⁹ J).\n• Prefixes: giga 10⁹, **tera 10¹²**, peta 10¹⁵.\n• Visible photons carry roughly 1.7–3.1 eV.",
      steps:[{text:"The frequency is given, so use E = hf.",hl:"a frequency of 580 THz",calc:["E = h × f"]},
        {text:"Convert the prefix: tera = 10¹².",calc:["580 THz = 580 × 10¹² Hz","= **5.8 × 10¹⁴ Hz**"]},
        {text:"Multiply the numbers and add the exponents separately.",calc:["E = (4.14 × 10⁻¹⁵ eV·s)(5.8 × 10¹⁴ s⁻¹)","4.14 × 5.8 = 24.0","10⁻¹⁵ × 10¹⁴ = 10⁻¹","E = 24.0 × 10⁻¹ eV = **2.4 eV**"]},
        {text:"Check in joules: (6.63 × 10⁻³⁴)(5.8 × 10¹⁴) = 3.8 × 10⁻¹⁹ J, and 3.8 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ ≈ 2.4 eV.",calc:["3.8 × 10⁻¹⁹ J ÷ 1.60 × 10⁻¹⁹ J/eV ≈ **2.4 eV**"]},
        {text:"0.0024 eV treats tera as giga (10⁹). 2400 eV treats it as peta (10¹⁵). 0.24 eV writes 580 THz as 5.8 × 10¹³ Hz, one power of ten short.",strike:["0.0024 eV","2400 eV","0.24 eV"]},
        {text:"Answer: 2.4 eV."}],
      trap:"Slipping one prefix step (tera as giga) shifts the answer by a factor of 1000. A visible photon always carries a few eV, so 0.0024 eV or 2400 eV is a unit slip."},
    teach:[{text:"First, **find the number and its unit**.",marks:[{t:"580 THz",note:"frequency f"},{t:"eV·s",note:"use h in eV·s"},{t:"each emitted photon",note:"energy of a single photon"}]},
      {text:"**One photon's energy is Planck's constant times frequency.**",calc:["E = hf","h = 4.14 × 10⁻¹⁵ eV·s"]},
      {text:"**Tera means 10¹².** Write the frequency in scientific notation before multiplying.",calc:["580 THz = 5.8 × 10¹⁴ Hz"]},
      {text:"**Numbers and powers of ten separately.** Multiply 4.14 × 5.8, then add −15 and +14.",calc:["4.14 × 5.8 = 24.0","10⁻¹⁵ × 10¹⁴ = 10⁻¹","E = 2.4 eV"]},
      {text:"**Rule to reuse:** E = hf with f in hertz (THz × 10¹²); multiply the leading numbers and add the exponents, then check that a visible photon comes out near 2–3 eV."}]},

  // pe1-cp:26 (continuity: the largest total area gives the slowest flow)
  {id:"cpt-pe1-26a",s:"Fluids",disc:"biology",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:26#1"],
    q:"In a muscle bed, blood moves at 2.0 cm/s through arterioles with a combined cross-sectional area of 40 cm². The capillaries they feed total 800 cm². What is the capillary blood speed?",
    choices:["0.10 cm/s","2.0 cm/s","40 cm/s","0.0025 cm/s"],ans:0,
    exp:"**Continuity: Q = A·v is the same at every level.** Q = 40 cm² × 2.0 cm/s = 80 cm³/s, so v = 80 ÷ 800 = **0.10 cm/s**. Blood crawls through capillaries because their **total** area is twenty times larger, not because each one is thin.",
    how:{ask:"The same volume per second passes the arterioles and the capillaries. How fast must it move through twenty times the total area?",
      know:"• **Continuity: Q = A·v** (Q = flow rate in cm³/s, A = cross-sectional area, v = mean speed). For blood, Q is the same at every level of the circulation.\n• Vessels in parallel: use their **combined** area.\n• Larger total A → smaller v. Capillaries have the largest total area, so blood is slowest there.",
      steps:[{text:"Find the flow rate in the arterioles.",hl:"2.0 cm/s through arterioles with a combined cross-sectional area of 40 cm²",calc:["Q = A × v","Q = 40 cm² × 2.0 cm/s = **80 cm³/s**"]},
        {text:"The same Q passes the capillaries; divide by their total area.",hl:"total 800 cm²",calc:["v = Q ÷ A = 80 cm³/s ÷ 800 cm²","v = **0.10 cm/s**","area × 20 → speed ÷ 20"],
          chart:{type:"line",caption:"Same flow (80 cm³/s): speed falls as total area grows",x:{label:"Total cross-sectional area (cm²)",min:0,max:800,step:200},y:{label:"Mean speed (cm/s)",min:0,max:2,step:0.5},series:[{name:"v = Q ÷ A",marker:"circle",line:"smooth",points:[[40,2],[80,1],[160,0.5],[400,0.2],[800,0.1]]}]}},
        {text:"2.0 cm/s assumes equal flow means equal speed. 40 cm/s treats the thin capillaries like a nozzle and multiplies by 20. 0.0025 cm/s divides the arteriole speed by the capillary area and skips Q.",strike:["2.0 cm/s","40 cm/s","0.0025 cm/s"]},
        {text:"Answer: 0.10 cm/s."}],
      trap:"Thinking narrow vessels speed blood up. One narrow tube would, but the blood is split among countless capillaries whose combined area is far larger than the arterioles'."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"2.0 cm/s",note:"arteriole speed"},{t:"40 cm²",note:"arteriole total area"},{t:"800 cm²",note:"capillary total area"}]},
      {text:"**Continuity:** blood is not lost between levels, so the volume per second is the same everywhere.",calc:["Q = A·v = constant"]},
      {text:"**Combined area decides the speed.** More total area for the same Q means slower blood.",calc:["v = Q ÷ A"],chart:{type:"line",caption:"Speed versus total area at a fixed flow of 80 cm³/s",x:{label:"Total cross-sectional area (cm²)",min:0,max:800,step:200},y:{label:"Mean speed (cm/s)",min:0,max:2,step:0.5},series:[{name:"v = Q ÷ A",marker:"circle",line:"smooth",points:[[40,2],[80,1],[160,0.5],[400,0.2],[800,0.1]]}]}},
      {text:"**Rule to reuse:** Q = A·v is the same at every level, so speed is smallest where the total cross-sectional area is largest: the capillaries."}]},

  // pe1-cp:30 (color vision needs pigments with different absorption peaks)
  {id:"cpt-pe1-30a",s:"Light & Optics",disc:"organic_chem",aamc:"4D",skill:"SIRS 2",from:["pe1-cp:30#1"],
    q:"A deep-sea fish sees with a single visual pigment that absorbs most strongly at 490 nm. Which change would most directly give it color vision?",
    choices:["A pigment with another peak","Twice as much of its pigment","A peak shifted to 550 nm","A narrower absorption band"],ans:0,
    exp:"One pigment only counts absorbed photons, so a dim light at 490 nm and a brighter light elsewhere can give the **same signal**. A **second pigment with a different absorption peak** responds differently to each wavelength, and the brain **compares the two responses** to tell colors apart.",
    how:{ask:"With one pigment, can the brain tell a change in color from a change in brightness? What would let it compare?",
      know:"• A photoreceptor reports only how many photons it absorbs, not their wavelength (**univariance**).\n• **Color vision** needs at least two pigments with **different absorption peaks**; the brain compares their responses (their ratio).\n• More pigment, a shifted peak or a narrower band still leaves one pigment, so still no comparison.",
      steps:[{text:"With one pigment, 450-nm and 530-nm light are absorbed equally well, so after matching brightness they give identical signals.",hl:"a single visual pigment",calc:["one pigment → one number (photons absorbed)","color and brightness mixed together"]},
        {text:"More pigment raises sensitivity; a shifted peak or a narrower band changes which light is absorbed best. Each still leaves one pigment and one signal.",strike:["Twice as much of its pigment","A peak shifted to 550 nm","A narrower absorption band"]},
        {text:"Add a second pigment peaking elsewhere: the two pigments now absorb in a different ratio at each wavelength.",calc:["450 nm: first 0.7, second ≈ 0.0","530 nm: first 0.7, second 0.7","different ratios → different colors"],
          chart:{type:"line",caption:"The fish pigment and a second pigment with another peak",x:{label:"Wavelength (nm)",min:400,max:650,step:50},y:{label:"Relative absorbance",min:0,max:1,step:0.2},series:[{name:"Fish pigment (490 nm)",marker:"circle",line:"smooth",points:[[400,0.1],[430,0.4],[450,0.7],[470,0.92],[490,1],[510,0.92],[530,0.7],[550,0.4],[580,0.1],[600,0.03]]},{name:"Second pigment (560 nm)",marker:"square-open",line:"smooth",points:[[450,0.01],[480,0.1],[510,0.4],[530,0.7],[545,0.92],[560,1],[575,0.92],[590,0.7],[610,0.4],[640,0.1]]}]}},
        {text:"Answer: a pigment with another peak."}],
      trap:"Choosing more pigment: it makes the fish more sensitive in dim light, but one pigment, however much of it, cannot separate color from brightness."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"a single visual pigment",note:"only one kind"},{t:"490 nm",note:"its absorption peak"},{t:"color vision",note:"telling wavelengths apart"}]},
      {text:"**One pigment sends one number:** photons absorbed. A dim light near the peak and a bright light off the peak can give the same number.",calc:["signal = brightness × absorbance"]},
      {text:"**Two pigments with different peaks** absorb each wavelength in a different ratio; the brain compares them.",chart:{type:"line",caption:"Two pigments, two peaks",x:{label:"Wavelength (nm)",min:400,max:650,step:50},y:{label:"Relative absorbance",min:0,max:1,step:0.2},series:[{name:"Fish pigment (490 nm)",marker:"circle",line:"smooth",points:[[400,0.1],[430,0.4],[450,0.7],[470,0.92],[490,1],[510,0.92],[530,0.7],[550,0.4],[580,0.1],[600,0.03]]},{name:"Second pigment (560 nm)",marker:"square-open",line:"smooth",points:[[450,0.01],[480,0.1],[510,0.4],[530,0.7],[545,0.92],[560,1],[575,0.92],[590,0.7],[610,0.4],[640,0.1]]}]}},
      {text:"**Rule to reuse:** color vision comes from comparing the responses of pigments with different absorption peaks; one pigment alone cannot tell wavelength from brightness."}]},

  // pe1-cp:45 (thin lens, magnification; object at 3f)
  {id:"cpt-pe1-45a",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 2",from:["pe1-cp:45#1"],
    q:"An object 1.5 cm tall stands 25 cm from a converging lens of focal length 20 cm. What are the image's height and orientation?",
    choices:["6.0 cm, inverted","6.0 cm, upright","0.38 cm, inverted","1.2 cm, inverted"],ans:0,
    exp:"**Thin-lens equation, solved for i: 1/i = 1/f − 1/o** = 1/20 − 1/25 = 1/100, so i = 100 cm. **m = −i/o** = −100/25 = −4.0, so the image is 4.0 × 1.5 cm = **6.0 cm** tall, and the minus sign means **inverted**.",
    how:{ask:"Find the image distance from the thin-lens equation, then the magnification; its size scales the height and its sign gives the orientation.",
      know:"• **Thin lens: 1/f = 1/o + 1/i** (f > 0 for converging; i > 0 is a real image).\n• **Magnification m = −i/o = image height ÷ object height**.\n• m < 0 → inverted; |m| > 1 → enlarged.",
      steps:[{text:"Solve the thin-lens equation for i.",hl:"25 cm from a converging lens of focal length 20 cm",calc:["1/i = 1/f − 1/o","1/i = 1/20 − 1/25 = 5/100 − 4/100 = 1/100","i = **+100 cm** (real image)"]},
        {text:"Find the magnification.",calc:["m = −i/o = −100/25","m = **−4.0**"]},
        {text:"Scale the height.",hl:"An object 1.5 cm tall",calc:["image height = m × object height","= −4.0 × 1.5 cm = **−6.0 cm**","6.0 cm tall, minus sign → inverted"]},
        {text:"0.38 cm uses o/i instead of i/o (0.25 × 1.5). 1.2 cm uses f/o (0.80 × 1.5). An upright image would need a positive m.",strike:["0.38 cm, inverted","1.2 cm, inverted","6.0 cm, upright"]},
        {text:"Answer: 6.0 cm, inverted."}],
      trap:"Dropping the minus sign in m = −i/o. A real image from a single converging lens is always inverted."},
    teach:[{text:"First, **find every number**.",marks:[{t:"1.5 cm tall",note:"object height"},{t:"25 cm",note:"object distance o"},{t:"focal length 20 cm",note:"f"}]},
      {text:"**Thin-lens equation** finds where the image forms.",calc:["1/f = 1/o + 1/i","1/i = 1/20 − 1/25 → i = 100 cm"]},
      {text:"**Magnification** compares heights; its sign gives the orientation.",calc:["m = −i/o = −4.0","height = 4.0 × 1.5 cm = 6.0 cm, inverted"]},
      {text:"**Rule to reuse:** solve 1/f = 1/o + 1/i for i, then m = −i/o: |m| scales the height and a negative m means inverted."}]},
  {id:"cpt-pe1-45b",s:"Light & Optics",disc:"physics",aamc:"4D",skill:"SIRS 2",from:["pe1-cp:45#2"],
    q:"An object is placed 18 cm from a converging lens whose focal length is 6.0 cm. How does the image compare with the object?",
    choices:["Half as tall, inverted","Half as tall, upright","Twice as tall, inverted","One-third as tall, inverted"],ans:0,
    exp:"The object is at **three focal lengths**. 1/i = 1/6.0 − 1/18 = 2/18, so **i = 9.0 cm = 1.5f**. m = −i/o = −9.0/18 = **−0.5**: half the object's height and **inverted**.",
    how:{ask:"Find the image distance for an object at three focal lengths, then use m = −i/o for size and orientation.",
      know:"• **1/f = 1/o + 1/i**, then **m = −i/o**.\n• Object at **3f** → image at **1.5f** → |m| = 1.5f ÷ 3f = **½**, inverted.\n• Object at 2f → image at 2f, |m| = 1. Beyond 2f → smaller image.",
      steps:[{text:"Compare o with f: the object sits at three focal lengths.",hl:"18 cm from a converging lens whose focal length is 6.0 cm",calc:["o ÷ f = 18 ÷ 6.0 = **3**"]},
        {text:"Solve for the image distance.",calc:["1/i = 1/6.0 − 1/18 = 3/18 − 1/18 = 2/18","i = **9.0 cm** = 1.5f"],
          chart:{type:"line",caption:"Image distance versus object distance, f = 6.0 cm",x:{label:"Object distance o (cm)",min:6,max:36,step:6},y:{label:"Image distance i (cm)",min:0,max:24,step:6},series:[{name:"i",marker:"circle",line:"smooth",points:[[8,24],[9,18],[12,12],[18,9],[24,8],[30,7.5],[36,7.2]]}]}},
        {text:"Magnification gives size and orientation.",calc:["m = −i/o = −9.0/18","m = **−0.5** → half as tall, inverted"]},
        {text:"Twice as tall flips the ratio to o/i. One-third as tall uses f/o. Upright would need a positive m, but a real image is inverted.",strike:["Twice as tall, inverted","One-third as tall, inverted","Half as tall, upright"]},
        {text:"Answer: half as tall, inverted."}],
      trap:"Assuming the image is one-third as tall because the object is three focal lengths away. The image sits at 1.5f, so the ratio is 1.5f ÷ 3f = ½."},
    teach:[{text:"First, **find the two distances**.",marks:[{t:"18 cm",note:"object distance o"},{t:"6.0 cm",note:"focal length f"},{t:"How does the image compare",note:"size and orientation"}]},
      {text:"**Express o in focal lengths:** 18 cm = 3f.",calc:["1/i = 1/f − 1/o = 1/f − 1/(3f) = 2/(3f)","i = 1.5f = 9.0 cm"]},
      {text:"**See it:** as the object moves out past 2f, the image moves in toward f and shrinks.",chart:{type:"line",caption:"Converging lens, f = 6.0 cm",x:{label:"Object distance o (cm)",min:6,max:36,step:6},y:{label:"Image distance i (cm)",min:0,max:24,step:6},series:[{name:"i",marker:"circle",line:"smooth",points:[[8,24],[9,18],[12,12],[18,9],[24,8],[30,7.5],[36,7.2]]}]}},
      {text:"**Magnification:** m = −i/o = −1.5f ÷ 3f = −½.",calc:["|m| = ½ (half as tall)","m < 0 → inverted"]},
      {text:"**Rule to reuse:** an object at 3f in front of a converging lens forms a real, inverted image at 1.5f, half the object's height (m = −½)."}]},

  // pe1-cp:46 (gamma decay emits a photon; A and Z unchanged)
  {id:"cpt-pe1-46a",s:"Atomic & Nuclear Physics",disc:"physics",aamc:"4E",skill:"SIRS 1",from:["pe1-cp:46#1"],
    q:"Which emission leaves a nucleus with the same mass number A and the same atomic number Z as before?",
    choices:["A gamma photon","An alpha particle","A beta-minus electron","A positron"],ans:0,
    exp:"A **gamma ray is a photon**: no mass number and no charge, so A and Z stay put. **α** (a ⁴He nucleus) lowers A by 4 and Z by 2; **β⁻** (an electron) raises Z by 1; **β⁺** (a positron) lowers Z by 1.",
    how:{ask:"For each emission, write what it carries away in A and Z; find the one that carries away zero of both.",
      know:"• **α** = ⁴₂He: A − 4, Z − 2.\n• **β⁻** = electron (⁰₋₁e): Z + 1, A same.\n• **β⁺** = positron (⁰₊₁e): Z − 1, A same.\n• **γ** = high-energy photon (⁰₀γ): A and Z unchanged; the nucleus just drops from an excited state.",
      steps:[{text:"Alpha decay removes two protons and two neutrons.",calc:["²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He","A: 222 → 218, Z: 86 → 84"],strike:["An alpha particle"]},
        {text:"Beta decays keep A but change Z by one.",calc:["β⁻: ³₁H → ³₂He + ⁰₋₁e (Z + 1)","β⁺: ¹⁸₉F → ¹⁸₈O + ⁰₊₁e (Z − 1)"],strike:["A beta-minus electron","A positron"]},
        {text:"Gamma emission carries away energy only.",hl:"the same mass number A and the same atomic number Z",calc:["¹³⁷ᵐ₅₆Ba → ¹³⁷₅₆Ba + ⁰₀γ","A: 137 → 137, Z: 56 → 56"]},
        {text:"Answer: a gamma photon."}],
      trap:"Choosing the positron or electron because A is unchanged. Beta particles carry charge, so Z changes by one."},
    teach:[{text:"First, **find what must stay the same**.",marks:[{t:"mass number A",note:"protons + neutrons"},{t:"atomic number Z",note:"protons: the element"}]},
      {text:"**Track A and Z for each emission.**",calc:["α (⁴He): A − 4, Z − 2","β⁻ (electron): Z + 1","β⁺ (positron): Z − 1","γ (photon): no change"]},
      {text:"**A gamma ray is light.** An excited nucleus releases its extra energy as a photon, like an excited atom emitting light.",calc:["X* → X + γ"]},
      {text:"**Rule to reuse:** gamma decay emits a photon and changes neither A nor Z; α is ⁴He, β⁻ is an electron, β⁺ is a positron."}]},

  // pe1-cp:56 (I = V/R with R in milliohms)
  {id:"cpt-pe1-56a",s:"Electricity & Magnetism",disc:"physics",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:56#1"],
    q:"A heating element with a resistance of 750 mΩ is connected across a 3.0-V supply. Assuming constant resistance, how much current does it draw?",
    choices:["4.0 A","4.0 mA","2.3 A","250 A"],ans:0,
    exp:"Convert first: **750 mΩ = 0.750 Ω**. Then **Ohm's law, I = V/R** = 3.0 V ÷ 0.750 Ω = **4.0 A**. A resistance under 1 Ω gives a current larger than the voltage number.",
    how:{ask:"Put the resistance in ohms, then divide the voltage by it.",
      know:"• **Ohm's law: I = V/R** (A = V ÷ Ω).\n• **m (milli) = 10⁻³**: 1 mΩ = 0.001 Ω. Capital **M (mega) = 10⁶**.",
      steps:[{text:"Convert milliohms to ohms.",hl:"a resistance of 750 mΩ",calc:["750 mΩ = 750 × 10⁻³ Ω = **0.750 Ω**"]},
        {text:"Apply Ohm's law.",hl:"3.0-V supply",calc:["I = V ÷ R","I = 3.0 V ÷ 0.750 Ω","I = **4.0 A**"],
          chart:{type:"line",caption:"Current from a 3.0-V supply versus resistance",x:{label:"Resistance (Ω)",min:0,max:3,step:0.5},y:{label:"Current (A)",min:0,max:7,step:1},series:[{name:"I = V ÷ R",marker:"circle",line:"smooth",points:[[0.5,6],[0.75,4],[1,3],[1.5,2],[2,1.5],[3,1]]}]}},
        {text:"4.0 mA divides by 750 Ω, skipping the milli conversion. 2.3 A multiplies V × R (3.0 × 0.750). 250 A divides 750 by 3.0, which is R ÷ V and unconverted.",strike:["4.0 mA","2.3 A","250 A"]},
        {text:"Answer: 4.0 A."}],
      trap:"Treating 750 mΩ as 750 Ω gives 4.0 mA, a thousand times too small."},
    teach:[{text:"First, **find the givens**.",marks:[{t:"750 mΩ",note:"resistance R (milliohms)"},{t:"3.0-V supply",note:"voltage V"},{t:"how much current",note:"I in amps"}]},
      {text:"**Milli means one thousandth.** Convert before dividing.",calc:["750 mΩ = 750 ÷ 1000 Ω = 0.750 Ω"]},
      {text:"**Ohm's law:** current = voltage ÷ resistance.",calc:["I = V ÷ R = 3.0 ÷ 0.750 = 4.0 A"]},
      {text:"**Rule to reuse:** I = V/R with R in ohms; convert mΩ by dividing by 1000 first, and expect more amps than volts when R is under 1 Ω."}]},

  // pe1-cp:59 (units of power: W = J/s = kg·m²·s⁻³; kg·m²·s⁻² is energy; F·d/t is power)
  {id:"cpt-pe1-59a",s:"Mechanics & Energy",disc:"physics",aamc:"4A",skill:"SIRS 1",from:["pe1-cp:59#1"],
    q:"A muscle physiologist records a quantity whose SI base units are kg·m²·s⁻³. Which physical quantity is being recorded?",
    choices:["Power","Energy","Force","Pressure"],ans:0,
    exp:"Build up from force: N = kg·m·s⁻², a joule is N·m = kg·m²·s⁻², and dividing by seconds gives **kg·m²·s⁻³, the watt**. The extra s⁻¹ beyond a joule marks **energy per second**.",
    how:{ask:"Build each candidate's base units from F = ma and see which one ends in s⁻³.",
      know:"• **Force**: N = kg·m·s⁻² (F = ma).\n• **Energy**: J = N·m = kg·m²·s⁻².\n• **Power**: W = J/s = **kg·m²·s⁻³**.\n• **Pressure**: Pa = N/m² = kg·m⁻¹·s⁻².",
      steps:[{text:"Write the base units of each choice.",hl:"kg·m²·s⁻³",calc:["Force: kg·m·s⁻²","Energy: kg·m·s⁻² × m = kg·m²·s⁻²","Pressure: kg·m·s⁻² ÷ m² = kg·m⁻¹·s⁻²","Power: kg·m²·s⁻² ÷ s = **kg·m²·s⁻³**"]},
        {text:"Force has only one metre; energy is one s⁻¹ short; pressure has m⁻¹.",strike:["Force","Energy","Pressure"]},
        {text:"Answer: power, a joule per second."}],
      trap:"Choosing energy because kg·m² looks like a joule. Count the seconds: a joule has s⁻², a watt has s⁻³."},
    teach:[{text:"First, **read the unit closely**.",marks:[{t:"kg·m²·s⁻³",note:"note the s⁻³"},{t:"Which physical quantity",note:"match units to a quantity"}]},
      {text:"**Start from F = ma**, then multiply by distance for energy.",calc:["N = kg·m·s⁻²","J = N·m = kg·m²·s⁻²"]},
      {text:"**Divide by time for power.**",calc:["W = J ÷ s = kg·m²·s⁻³"]},
      {text:"**Rule to reuse:** W = J/s = kg·m²·s⁻³; one more s⁻¹ than a joule means power."}]},
  {id:"cpt-pe1-59b",s:"Mechanics & Energy",disc:"physics",aamc:"4A",skill:"SIRS 1",from:["pe1-cp:59#2"],
    q:"An exercise log records a rower's output for each stroke in kg·m²·s⁻². Which named SI unit equals kg·m²·s⁻²?",
    choices:["Joule","Watt","Newton","Pascal"],ans:0,
    exp:"Force × distance: kg·m·s⁻² × m = **kg·m²·s⁻² = 1 J**, a unit of **energy**. With no extra 'per second' it is not power; a watt would be kg·m²·s⁻³.",
    how:{ask:"Reduce each named unit to kg, m and s and find the one with m² and s⁻².",
      know:"• **N** = kg·m·s⁻².\n• **J** = N·m = **kg·m²·s⁻²** (energy, work).\n• **W** = J/s = kg·m²·s⁻³ (power).\n• **Pa** = N/m² = kg·m⁻¹·s⁻² (pressure).",
      steps:[{text:"Work is force times distance.",hl:"kg·m²·s⁻²",calc:["J = N × m","= kg·m·s⁻² × m = **kg·m²·s⁻²**"]},
        {text:"A watt is a joule per second, so it carries one more s⁻¹. A newton lacks the second metre; a pascal divides by m².",calc:["W = kg·m²·s⁻³","N = kg·m·s⁻²","Pa = kg·m⁻¹·s⁻²"],strike:["Watt","Newton","Pascal"]},
        {text:"So the log reports energy per stroke, not power. Answer: joule."}],
      trap:"Calling kg·m²·s⁻² a watt because 'output' sounds like power. Without a division by time it is energy."},
    teach:[{text:"First, **find the unit to name**.",marks:[{t:"kg·m²·s⁻²",note:"m² and s⁻²"},{t:"output for each stroke",note:"an amount per stroke, not per second"}]},
      {text:"**Energy = force × distance.**",calc:["kg·m·s⁻² × m = kg·m²·s⁻² = J"]},
      {text:"**Power needs one more division by time.**",calc:["J ÷ s = kg·m²·s⁻³ = W"]},
      {text:"**Rule to reuse:** kg·m²·s⁻² is a joule (energy), not power; power needs kg·m²·s⁻³."}]},
  {id:"cpt-pe1-59c",s:"Mechanics & Energy",disc:"physics",aamc:"4A",skill:"SIRS 1",from:["pe1-cp:59#3"],
    q:"A rehab patient pushes a weighted sled with a steady 120-N force through 15 m in 6.0 s. What average power does the patient deliver?",
    choices:["300 W","1800 W","48 W","20 W"],ans:0,
    exp:"**Power = force × distance ÷ time**: W = 120 N × 15 m = 1800 J, and P = 1800 J ÷ 6.0 s = **300 W**. N·m/s = J/s = W.",
    how:{ask:"Find the work as force × distance, then divide by the time.",
      know:"• **Work W = F·d** (N·m = J) when force and motion are in the same direction.\n• **Power P = W/t = F·d/t** (J/s = W).\n• Equivalently P = F·v.",
      steps:[{text:"Work done on the sled.",hl:"a steady 120-N force through 15 m",calc:["W = F × d = 120 N × 15 m","W = **1800 J**"]},
        {text:"Divide by the time.",hl:"6.0 s",calc:["P = W ÷ t = 1800 J ÷ 6.0 s","P = **300 W**","check: v = 15 m ÷ 6.0 s = 2.5 m/s; F·v = 120 × 2.5 = 300 W"]},
        {text:"1800 W is the work in joules, never divided by time. 48 W uses F × t ÷ d (120 × 6.0 ÷ 15). 20 W uses F ÷ t and ignores the distance.",strike:["1800 W","48 W","20 W"]},
        {text:"Answer: 300 W."}],
      trap:"Stopping at force × distance: 1800 J is energy. Power needs the division by time."},
    teach:[{text:"First, **find every number**.",marks:[{t:"120-N force",note:"F"},{t:"15 m",note:"distance d"},{t:"6.0 s",note:"time t"}]},
      {text:"**Force × distance is work (energy).**",calc:["N·m = J","120 × 15 = 1800 J"]},
      {text:"**Work ÷ time is power.**",calc:["J ÷ s = W","1800 ÷ 6.0 = 300 W"]},
      {text:"**Rule to reuse:** force × distance ÷ time is power (N·m/s = J/s = W); force × distance alone is energy."}]},
  // ── Practice Exam 1 · Chem/Phys, biochemistry: Q24, 25, 35, 36, 38, 39, 40, 43 ──
  // ── Q24: phosphorylation site ──
  {id:"cpt-pe1-24a",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:24#1"],
    q:"Which amino acid is correctly paired with the functional group at the end of its side chain?",
    choices:["Tyrosine: phenol","Serine: secondary alcohol","Threonine: primary alcohol","Alanine: primary alcohol"],ans:0,
    exp:"Tyrosine's side chain is a benzene ring carrying an –OH: a **phenol**. Serine ends in –CH₂–OH, a **primary** alcohol (the OH carbon has one C neighbor); threonine's –CH(OH)–CH₃ is a **secondary** alcohol (two C neighbors); alanine's side chain is just **–CH₃**, with no –OH at all.",
    how:{ask:"Draw each side chain, then classify any –OH by what the carbon bearing it is bonded to.",
      know:"• **Alcohol class** = number of carbons bonded to the C that holds the –OH: 1 → primary, 2 → secondary.\n• An –OH on an aromatic ring is a **phenol**.\n• Ser: –CH₂OH (1°). Thr: –CH(OH)CH₃ (2°). Tyr: –CH₂–C₆H₄–OH (phenol). Ala: –CH₃ (no OH).",
      steps:[{text:"The task is to match each residue with its side-chain group.",hl:"functional group at the end of its side chain"},
        {text:"Classify the four side chains.",fig:["tyrosine-sc","serine-sc","threonine-sc","alanine-sc"],calc:["Tyr: OH on a ring → **phenol**","Ser: OH on CH₂ (1 C neighbor) → **1° alcohol**","Thr: OH on CH (2 C neighbors) → **2° alcohol**","Ala: CH₃ → **no OH**"]},
        {text:"Serine's OH carbon has one carbon neighbor, so it is primary; threonine's has two, so it is secondary. The two labels are swapped.",strike:["Serine: secondary alcohol","Threonine: primary alcohol"]},
        {text:"Alanine has a methyl side chain and no alcohol of any kind.",strike:["Alanine: primary alcohol"]},
        {text:"Answer: tyrosine: phenol."}],
      trap:"Swapping serine and threonine: count the carbons on the OH-bearing carbon. Serine's CH₂ has one (Cα), threonine's CH has two (Cα and CH₃)."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"functional group",note:"classify it"},{t:"side chain",note:"the R group, not the backbone"}]},
      {text:"**Count carbons on the –OH carbon.** One carbon neighbor → primary; two → secondary.",calc:["R–CH₂–OH → 1°","R–CH(OH)–R′ → 2°"]},
      {text:"**Four side chains to know.** Ser –CH₂OH; Thr –CH(OH)CH₃; Tyr ring–OH; Ala –CH₃.",fig:["serine-sc","threonine-sc","tyrosine-sc","alanine-sc"]},
      {text:"**Rule to reuse:** serine is a primary alcohol, threonine a secondary alcohol, tyrosine a phenol, and alanine only a methyl group."}]},
  {id:"cpt-pe1-24b",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:24#2"],
    q:"A protein kinase transfers a phosphoryl group from ATP to a side chain of its substrate. Which residue could it modify?",
    choices:["Threonine","Phenylalanine","Alanine","Valine"],ans:0,
    exp:"A kinase forms a **phosphate ester**: it joins the phosphoryl group to an **oxygen of a side-chain –OH**. Threonine has an –OH (a secondary alcohol), so it can be phosphorylated. Phenylalanine has a ring with no –OH, and alanine and valine are hydrocarbon side chains.",
    how:{ask:"Which side chain has the –OH that a phosphoryl group bonds to?",
      know:"• **Kinase**: ATP + R–OH → ADP + R–O–PO₃²⁻ (a phosphate ester).\n• The usual sites are the three hydroxyl side chains: **Ser, Thr, Tyr**.\n• A side chain made only of C and H has no oxygen to link to.",
      steps:[{text:"The enzyme is a kinase, and the target is a side chain.",hl:"transfers a phosphoryl group from ATP to a side chain"},
        {text:"Phosphorylation needs a side-chain hydroxyl.",calc:["R–OH + ATP → R–O–PO₃²⁻ + ADP","Thr: –CH(OH)CH₃ → has **OH** ✓"],fig:["t6-thr-oh","t6-phosphothr"]},
        {text:"Phenylalanine's ring has no –OH (tyrosine is the ring residue that does).",strike:["Phenylalanine"],fig:"phenylalanine-sc"},
        {text:"Alanine (–CH₃) and valine (–CH(CH₃)₂) are pure hydrocarbon.",strike:["Alanine","Valine"]},
        {text:"Answer: threonine."}],
      trap:"Picking phenylalanine because tyrosine phosphorylation is famous: phenylalanine is tyrosine without the –OH, so it has nothing to phosphorylate."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"protein kinase",note:"adds phosphate"},{t:"phosphoryl group",note:"–PO₃²⁻"},{t:"side chain",note:"needs an –OH"}]},
      {text:"**A kinase makes a phosphate ester.** The phosphoryl group bonds to the oxygen of an –OH.",calc:["R–OH + ATP → R–O–PO₃²⁻ + ADP"]},
      {text:"**Only three residues offer a side-chain –OH**: serine, threonine and tyrosine.",fig:["t6-ser-oh","t6-thr-oh","t6-tyr-oh"]},
      {text:"**Rule to reuse:** phosphorylation goes on a side-chain –OH, so look for Ser, Thr or Tyr and reject side chains with no hydroxyl."}]},
  {id:"cpt-pe1-24c",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:24#3"],
    q:"A report states that a regulatory phosphate is attached to a residue whose side chain is a primary alcohol. Which residue carries the phosphate?",
    choices:["Serine","Threonine","Tyrosine","Cysteine"],ans:0,
    exp:"A **primary alcohol** has its –OH on a carbon bonded to only one other carbon: **–CH₂–OH**. That is serine's side chain. Threonine's –OH is on a carbon with two carbon neighbors (secondary), tyrosine's is on a ring (a phenol), and cysteine has –SH, not –OH.",
    how:{ask:"Which side chain matches the description the report gives: an –OH on a carbon with one carbon neighbor?",
      know:"• **Primary alcohol**: –CH₂–OH (1 C on the carbinol carbon).\n• Ser –CH₂OH (1°); Thr –CH(OH)CH₃ (2°); Tyr ring–OH (phenol); Cys –CH₂SH (thiol).\n• Use the description given, not the residue you expect to see phosphorylated.",
      steps:[{text:"The report's clue is the class of alcohol.",hl:"side chain is a primary alcohol"},
        {text:"Find the side chain that ends in –CH₂–OH.",fig:["serine-sc","t1-phosphoserine"],calc:["Ser: –CH₂–OH → C bearing OH has 1 C neighbor → **1°** ✓"]},
        {text:"Threonine's OH carbon has two carbon neighbors (secondary), and tyrosine's OH sits on a ring (phenol).",strike:["Threonine","Tyrosine"]},
        {text:"Cysteine ends in –CH₂–SH: a thiol, not an alcohol.",strike:["Cysteine"]},
        {text:"Answer: serine."}],
      trap:"Picking tyrosine or threonine because they are also phosphorylated: the report names a primary alcohol, and only serine fits."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"primary alcohol",note:"–CH₂–OH"},{t:"regulatory phosphate",note:"on an –OH"}]},
      {text:"**Translate the description into a structure.** Primary means the –OH carbon has one carbon neighbor.",calc:["primary: R–CH₂–OH","secondary: R–CH(OH)–R′","phenol: ring–OH"]},
      {text:"**Match it to a side chain.** Only serine ends in –CH₂–OH.",fig:"serine-sc"},
      {text:"**Rule to reuse:** turn the description into a structure first (primary alcohol → –CH₂OH → serine), then pick the residue that matches it."}]},

  // ── Q25: pH-dependent self-assembly ──
  {id:"cpt-pe1-25a",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:25#1"],
    q:"As the pH of a peptide solution is raised from 2 to 6, which side chain changes from mostly neutral to mostly negatively charged?",
    choices:["Aspartate","Lysine","Asparagine","Serine"],ans:0,
    exp:"Aspartate's side-chain –COOH has a pKa near **3.9**, inside the range. At pH 2 it is mostly –COOH (neutral); at pH 6 it is mostly –COO⁻ (−1). Lysine stays +1 over this range (pKa ≈ 10.5), and asparagine (an amide) and serine (an alcohol) do not ionize near these pH values.",
    how:{ask:"Which side chain has a pKa between 2 and 6, so that it loses a proton across the range?",
      know:"• A side chain changes charge when the pH passes its **pKa**.\n• pH < pKa → protonated; pH > pKa → deprotonated.\n• Asp/Glu: –COOH ⇌ –COO⁻ (pKa ≈ 4). Lys: –NH₃⁺ ⇌ –NH₂ (pKa ≈ 10.5).\n• Asn/Gln amides and Ser/Thr alcohols do not ionize in the physiological range.",
      steps:[{text:"The pH window and the direction of the change.",hl:"from mostly neutral to mostly negatively charged"},
        {text:"An acid that loses H⁺ goes from 0 to −1; aspartate's pKa sits in the window.",fig:"aspartate-sc",calc:["Asp pKa ≈ 3.9","pH 2 < 3.9 → –COOH (0)","pH 6 > 3.9 → –COO⁻ (**−1**)"]},
        {text:"Lysine's pKa is far above 6, so it stays +1 throughout and never turns negative.",strike:["Lysine"]},
        {text:"Asparagine's amide and serine's alcohol have no pKa in this range.",strike:["Asparagine","Serine"]},
        {text:"Answer: aspartate."}],
      trap:"Choosing asparagine because its name resembles aspartate: it carries an amide (–CONH₂), which does not lose a proton near these pH values."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"from 2 to 6",note:"the pH window"},{t:"mostly neutral to mostly negatively charged",note:"an acid losing H⁺"}]},
      {text:"**Charge changes where pH crosses pKa.** Below the pKa the group holds its H⁺; above it, the H⁺ is gone.",calc:["–COOH (0) ⇌ –COO⁻ (−1) + H⁺"]},
      {text:"**Side-chain pKa values to know:** Asp ≈ 3.9, Glu ≈ 4.1, His ≈ 6.0, Lys ≈ 10.5, Arg ≈ 12.5.",fig:["aspartate-sc","lysine-sc"]},
      {text:"**Rule to reuse:** a side chain's charge changes only when the pH moves past its pKa; acids go 0 → −1, bases go +1 → 0 as pH rises."}]},
  {id:"cpt-pe1-25b",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:25#2"],
    q:"A glutamate-rich peptide stays dissolved at pH 7 but clumps into aggregates at pH 2.5. Which change best explains the aggregation?",
    choices:["Repulsion is lost","Charge is gained","Ion pairs form","Hydration increases"],ans:0,
    exp:"At pH 7 the glutamate side chains are –COO⁻, so every strand carries many **negative charges**, and like charges push the strands apart and keep them in solution. At pH 2.5, below the pKa (≈ 4.1), they become neutral **–COOH**; with nothing pushing them apart, strands can **pack together**. No + groups appear to pair with the − groups, so no salt bridges form.",
    how:{ask:"What happens to the glutamate charges between pH 7 and pH 2.5, and how does that change the forces between strands?",
      know:"• Glu side chain pKa ≈ 4.1: above it –COO⁻ (−1), below it –COOH (0).\n• **Like charges repel**: many −1 charges keep strands apart and dissolved.\n• **Neutral side chains** let strands approach and pack.\n• A **salt bridge** needs a + group and a − group.",
      steps:[{text:"The peptide is acidic and the pH drops.",hl:"stays dissolved at pH 7 but clumps into aggregates at pH 2.5"},
        {text:"Compare the side-chain charge at the two pH values.",fig:"glutamate",calc:["pH 7 > 4.1 → –COO⁻ → strands repel → dissolved","pH 2.5 < 4.1 → –COOH → neutral → strands **pack**"]},
        {text:"Lowering the pH removes the charge here; it does not add any.",strike:["Charge is gained"]},
        {text:"An ion pair (salt bridge) needs both + and − groups, and at pH 2.5 the − groups are gone.",strike:["Ion pairs form"]},
        {text:"Neutral –COOH groups bind water less well than –COO⁻, so hydration drops.",strike:["Hydration increases"]},
        {text:"Answer: repulsion is lost."}],
      trap:"Assuming assembly needs attractive charges: here the strands aggregate because the repulsive charges are removed, not because new attractions appear."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"glutamate-rich",note:"acidic side chains"},{t:"dissolved at pH 7",note:"charged"},{t:"aggregates at pH 2.5",note:"neutral"}]},
      {text:"**Charge sets the spacing.** Strands with many like charges push each other apart and stay in solution.",calc:["many −1 → repel → soluble"]},
      {text:"**Remove the charge and they pack.** Below the pKa the side chains are neutral, and strands can stack.",calc:["0 charge → no repulsion → aggregate"]},
      {text:"**Rule to reuse:** charged side chains repel and keep peptides apart; when the pH neutralizes them, the strands can pack together."}]},
  {id:"cpt-pe1-25c",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:25#3"],
    q:"A peptide's only ionizable side chains are histidines, with pKa 6.0. At pH 8.0, what is the main form of these side chains?",
    choices:["Mostly neutral","Mostly positive","Half positive","Mostly negative"],ans:0,
    exp:"pH 8.0 is **two units above** the pKa, so by Henderson–Hasselbalch the neutral (base) form outnumbers the protonated (+1) form **100 : 1**. About 99% of the histidines are neutral. They would be half positive only at pH 6.0 and mostly positive below it; a histidine side chain never turns negative.",
    how:{ask:"How far is the pH from the pKa, and which side of it is the pH on?",
      know:"• **pH = pKa + log([base]/[acid])**.\n• Histidine: acid form = imidazolium (+1); base form = neutral imidazole (0).\n• Each pH unit away from the pKa is a 10-fold change in the ratio.",
      steps:[{text:"Pick out the pKa and the pH.",hl:"pKa 6.0"},
        {text:"Apply Henderson–Hasselbalch.",calc:["log([base]/[acid]) = pH − pKa","= 8.0 − 6.0 = 2.0","[base]/[acid] = 10² = **100 : 1**","fraction neutral = 100/101 ≈ **99%**"]},
        {text:"See it on the titration curve: at pH 8 almost none is protonated.",chart:{type:"line",caption:"Histidine side chain protonated (pKa 6.0)",x:{label:"pH",min:3,max:9,step:1},y:{label:"Protonated, +1 (%)",min:0,max:100,step:20},series:[{name:"Protonated",marker:"circle",line:"smooth",points:[[3,99.9],[4,99],[5,91],[5.5,76],[6,50],[6.5,24],[7,9],[8,1],[9,0.1]]}]}},
        {text:"Half positive happens only at pH = pKa; mostly positive needs pH below 6.0.",strike:["Half positive","Mostly positive"]},
        {text:"Losing its proton leaves histidine neutral, not negative.",strike:["Mostly negative"]},
        {text:"Answer: mostly neutral."}],
      trap:"Thinking of histidine as a 'basic, positive' residue regardless of pH: above its pKa of 6.0 it is mostly uncharged."},
    teach:[{text:"First, **find every number**.",marks:[{t:"pKa 6.0",note:"histidine side chain"},{t:"pH 8.0",note:"two units above"}]},
      {text:"**Compare pH with pKa.** pH above pKa → mostly deprotonated; below → mostly protonated.",calc:["8.0 − 6.0 = +2"]},
      {text:"**Each unit is a factor of 10.** Two units above the pKa → 100 base : 1 acid.",fig:"histidine-sc",calc:["10² = 100 → ≈ 99% neutral"]},
      {text:"**Rule to reuse:** compare pH with each side chain's pKa; one unit past it is about 90% converted, two units about 99%."}]},

  // ── Q35: net charge change from substitutions ──
  {id:"cpt-pe1-35a",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:35#1"],
    q:"At pH 7, which of these side chains is mostly uncharged even though it can accept a proton?",
    choices:["Histidine","Lysine","Arginine","Glutamate"],ans:0,
    exp:"Histidine's imidazole side chain has a pKa near **6.0**. At pH 7 the pH is above the pKa, so only about 1 in 10 is protonated: the side chain is **mostly neutral (≈ 0)**. Lysine and arginine (pKa 10.5 and 12.5) are **+1**, and glutamate (pKa ≈ 4.1) is **−1** at pH 7.",
    how:{ask:"For each side chain, is pH 7 above or below its pKa, and what charge does that give?",
      know:"• At pH 7: **Arg, Lys → +1**; **Asp, Glu → −1**; **His → ≈ 0** (pKa ≈ 6.0, about 10% protonated); all other side chains → 0.\n• pH < pKa → protonated; pH > pKa → deprotonated.",
      steps:[{text:"The question asks for a basic group that is not protonated at pH 7.",hl:"mostly uncharged even though it can accept a proton"},
        {text:"Assign each charge at pH 7.",fig:["histidine-sc","lysine-sc","arginine-sc"],calc:["His: pKa 6.0 < 7 → mostly neutral, **≈ 0**","Lys: pKa 10.5 > 7 → **+1**","Arg: pKa 12.5 > 7 → **+1**","Glu: pKa 4.1 < 7 → **−1**"]},
        {text:"Lysine and arginine stay protonated (+1) at pH 7.",strike:["Lysine","Arginine"]},
        {text:"Glutamate is an acid and is fully deprotonated (−1) at pH 7.",strike:["Glutamate"]},
        {text:"Answer: histidine."}],
      trap:"Listing histidine with lysine and arginine as +1: its pKa is below 7, so at pH 7 it is mostly neutral."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"pH 7",note:"compare with each pKa"},{t:"mostly uncharged",note:"≈ 0"},{t:"accept a proton",note:"a base"}]},
      {text:"**Memorize the pH 7 charges.** Arg, Lys +1; Asp, Glu −1; His ≈ 0; the rest 0.",calc:["Arg +1, Lys +1","Asp −1, Glu −1","His ≈ 0 (pKa ≈ 6)"]},
      {text:"**Histidine is the borderline base.** Its pKa is just below 7, so most side chains have already lost the proton.",fig:"histidine-sc"},
      {text:"**Rule to reuse:** at pH 7, count Arg and Lys as +1, Asp and Glu as −1, and His and everything else as 0."}]},
  {id:"cpt-pe1-35b",s:"Amino Acids & Proteins",disc:"biochemistry",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:35#2"],
    q:"Four residues of a soluble protein are replaced: Lys→Glu, Arg→Asp, Lys→Asp and Ala→His. What is the change in the protein's net charge at pH 7?",
    choices:["A decrease of 6","A decrease of 5","A decrease of 7","An increase of 6"],ans:0,
    exp:"At pH 7, Lys and Arg are **+1**, Glu and Asp are **−1**, and Ala and His are **≈ 0**. Each basic-to-acidic swap goes from +1 to −1, a change of **−2**; there are three of them. Ala→His changes nothing. Total: −2 − 2 − 2 + 0 = **−6**.",
    how:{ask:"For each substitution, subtract the old side-chain charge from the new one at pH 7, then add the four changes.",
      know:"• Charges at pH 7: Arg/Lys **+1**, Asp/Glu **−1**, His **≈ 0**, others **0**.\n• Change at each site = **new − old**.\n• Net change = sum of the site changes.",
      steps:[{text:"List the swaps.",hl:"Lys→Glu, Arg→Asp, Lys→Asp and Ala→His"},
        {text:"Compute new − old at each site.",fig:["lysine-sc","arginine-sc","aspartate-sc","histidine-sc"],calc:["Lys→Glu: (−1) − (+1) = **−2**","Arg→Asp: (−1) − (+1) = **−2**","Lys→Asp: (−1) − (+1) = **−2**","Ala→His: 0 − 0 = **0**"]},
        {text:"Add them.",calc:["Δ = −2 + (−2) + (−2) + 0 = **−6**"]},
        {text:"Counting His as +1 gives a decrease of 5, and counting it as −1 gives 7; at pH 7 it is ≈ 0.",strike:["A decrease of 5","A decrease of 7"]},
        {text:"Positive charges are replaced by negative ones, so the net charge falls; an increase has the sign flipped.",strike:["An increase of 6"]},
        {text:"Answer: a decrease of 6 (Δ = −6)."}],
      trap:"Treating each + → − swap as a change of 1: losing the +1 and gaining the −1 together change the charge by 2."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Four residues",note:"four sites to add"},{t:"pH 7",note:"use pH 7 charges"},{t:"net charge",note:"sum of changes"}]},
      {text:"**Assign charges at pH 7.**",calc:["Lys, Arg: +1","Glu, Asp: −1","Ala, His: 0"]},
      {text:"**Change per site = new − old.** A + → − swap is worth 2.",calc:["(−1) − (+1) = −2"]},
      {text:"**Rule to reuse:** for each substitution take new charge minus old charge at the stated pH, then add all the site changes."}]},

  // ── Q36: activity retained after heating ──
  {id:"cpt-pe1-36a",s:"Reading Data",disc:"biochemistry",aamc:"5D",skill:"SIRS 4",from:["pe1-cp:36#1"],
    q:"After 15 min at 55 °C and cooling, wild-type lipase kept 30% of its activity, mutant A kept 65% and mutant B kept 25%. Which conclusion fits?",
    choices:["Only mutant A is more stable","Both mutants are more stable","Only mutant B is more stable","Neither mutant is more stable"],ans:0,
    exp:"Retained activity is the measure of heat stability: more activity left means less damage. Mutant A kept **65% vs the wild type's 30%**, so it is more stable. Mutant B kept **25%**, slightly **less** than the wild type, so it is not more stable.",
    how:{ask:"Line up each mutant's retained activity against the wild type's and decide which are higher.",
      know:"• **% activity kept after heating**: higher → more heat-stable.\n• Compare every variant with the **wild type**, the reference.\n• A conclusion about \"both\" fails if even one variant does not fit.",
      steps:[{text:"Find the reference and each variant's value.",hl:"wild-type lipase kept 30% of its activity, mutant A kept 65% and mutant B kept 25%"},
        {text:"Compare each with the wild type.",chart:{type:"bar",caption:"Activity kept after heating",x:{label:"Enzyme"},y:{label:"Activity kept (%)",min:0,max:100,step:20},categories:["Wild type","Mutant A","Mutant B"],series:[{name:"Kept",values:[30,65,25]}]},calc:["A: 65% > 30% → **more stable**","B: 25% < 30% → **less stable**"]},
        {text:"Mutant B kept less than the wild type, so it is neither more stable alone nor along with A.",strike:["Both mutants are more stable","Only mutant B is more stable"]},
        {text:"Mutant A clearly kept more, so it is wrong that neither is more stable.",strike:["Neither mutant is more stable"]},
        {text:"Answer: only mutant A is more stable."}],
      trap:"Assuming every mutant behaves alike: check each one against the wild type separately."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"55 °C",note:"heating step"},{t:"30%",note:"wild type, the reference"},{t:"65%",note:"mutant A"},{t:"25%",note:"mutant B"}]},
      {text:"**Heat, cool, assay.** The activity that survives measures how well the enzyme resists heat.",calc:["% kept ↑ → heat stability ↑"]},
      {text:"**Subtract the reference.**",calc:["A: 65 − 30 = +35","B: 25 − 30 = −5"]},
      {text:"**Rule to reuse:** compare each variant's retained activity with the wild type's; higher means more heat-stable, lower means less."}]},
  {id:"cpt-pe1-36b",s:"Reading Data",disc:"biochemistry",aamc:"5D",skill:"SIRS 4",from:["pe1-cp:36#2"],
    q:"After heating to 50 °C and cooling to 30 °C, a wild-type kinase keeps 40% of its activity and a variant keeps 15%. Which statement do the data support?",
    choices:["The variant tolerates heat less.","The kinase is wholly destroyed.","The variant is fully inactivated.","Both forms are equally stable."],ans:0,
    exp:"The variant kept **15%** and the wild type **40%**, so the variant is **less heat-stable**. Neither form reached 0%, so the kinase was not wholly destroyed and the variant was not fully inactivated. The two values differ, so the forms are not equally stable.",
    how:{ask:"Which statement stays within the numbers given, without claiming more than they show?",
      know:"• A conclusion must match the data; words like **all**, **fully** or **every** fail if any activity remains.\n• Compare the variant with the wild type to judge stability.",
      steps:[{text:"Read the two retained activities.",hl:"keeps 40% of its activity and a variant keeps 15%"},
        {text:"Both are above zero, so nothing lost all activity.",calc:["wild type: 40% > 0","variant: 15% > 0"],strike:["The kinase is wholly destroyed.","The variant is fully inactivated."]},
        {text:"The values differ, so the forms are not equally stable.",calc:["15% < 40% → variant **less stable**"],strike:["Both forms are equally stable."]},
        {text:"Answer: the variant tolerates heat less."}],
      trap:"Reading a large drop as total loss: 15% is low but not zero, so \"fully inactivated\" overstates the data."},
    teach:[{text:"First, **find every number** and what it is.",marks:[{t:"50 °C",note:"heating"},{t:"40%",note:"wild type kept"},{t:"15%",note:"variant kept"}]},
      {text:"**Check absolute words against the data.** \"All\" or \"fully\" needs 0%.",calc:["40% ≠ 0, 15% ≠ 0 → some activity remains"]},
      {text:"**Then compare.** Less activity kept than the wild type → less heat-stable."},
      {text:"**Rule to reuse:** keep only the claim the numbers show; reject absolute words like all, fully or every when any activity remains."}]},

  // ── Q38: numbering a glucose phosphate ──
  {id:"cpt-pe1-38a",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:38#1"],
    q:"In the pyranose ring of D-glucose, which carbon is bonded to the ring oxygen and also carries the –CH₂OH group?",
    choices:["C5","C1","C4","C6"],ans:0,
    exp:"Number glucose from the **anomeric carbon, C1**, which is bonded to the ring O and to an –OH. Going around the ring: C2, C3, C4, then **C5**, the other carbon bonded to the ring O. C5 in turn holds **C6**, the –CH₂OH that sits off the ring.",
    how:{ask:"Which ring carbons touch the ring oxygen, and which of them holds the CH₂OH?",
      know:"• **C1** = anomeric carbon: bonded to the ring O **and** an –OH (two oxygens).\n• **C2, C3, C4** = ring carbons, each with an –OH.\n• **C5** = bonded to the ring O and to C6.\n• **C6** = the –CH₂OH outside the ring.",
      steps:[{text:"Two clues: bonded to the ring O, and carrying CH₂OH.",hl:"bonded to the ring oxygen and also carries the –CH₂OH group"},
        {text:"Number the ring from the anomeric carbon.",fig:"beta-glucopyranose",calc:["ring O neighbors: **C1** and **C5**","CH₂OH = C6, attached to **C5**"]},
        {text:"C1 touches the ring O but carries an –OH, not the CH₂OH.",strike:["C1"]},
        {text:"C4 is not bonded to the ring O, and C6 is the CH₂OH carbon itself, outside the ring.",strike:["C4","C6"]},
        {text:"Answer: C5."}],
      trap:"Naming C6: C6 is the CH₂OH group; the ring carbon that carries it is C5."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"pyranose ring",note:"5 C + 1 O"},{t:"ring oxygen",note:"two carbon neighbors"},{t:"–CH₂OH group",note:"C6"}]},
      {text:"**Start at the anomeric carbon (C1)**: the ring carbon with two oxygens.",fig:"alpha-glucopyranose"},
      {text:"**Go around the ring away from the ring O.**",calc:["C1 → C2 → C3 → C4 → C5 (back to ring O)","C5–CH₂OH = C6"]},
      {text:"**Rule to reuse:** in glucopyranose, C1 is anomeric, C2–C4 are ring carbons, C5 is bonded to the ring O, and C6 is the CH₂OH."}]},
  {id:"cpt-pe1-38b",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:38#2"],
    q:"A glucopyranose drawing shows a phosphate on the ring carbon that is bonded to C5 but not to the ring oxygen. What is the compound?",
    choices:["Glucose 4-phosphate","Glucose 6-phosphate","Glucose 3-phosphate","Glucose 1-phosphate"],ans:0,
    exp:"C5 is bonded to the ring O, to **C6** (the –CH₂OH outside the ring) and to **C4**. The only other **ring** carbon on C5 is C4, so the phosphate is on C4: **glucose 4-phosphate**. A sugar phosphate is named by the number of the carbon that holds the phosphate.",
    how:{ask:"Which ring carbon is next to C5 on the side away from the ring O, and what number is it?",
      know:"• Ring order: O – C1 – C2 – C3 – C4 – C5 – O.\n• C5's neighbors: ring O, C4 (ring), C6 (outside).\n• Name = glucose **n**-phosphate, where n is the carbon carrying the phosphate.",
      steps:[{text:"The clue locates the phosphate relative to C5.",hl:"bonded to C5 but not to the ring oxygen"},
        {text:"List C5's neighbors.",fig:"alpha-glucopyranose",calc:["C5 → ring O, **C4**, C6","ring carbon among them: **C4**"]},
        {text:"C6 is bonded to C5 but sits outside the ring, so it is not a ring carbon.",strike:["Glucose 6-phosphate"]},
        {text:"C3 is two carbons from C5, and C1 is bonded to the ring O.",strike:["Glucose 3-phosphate","Glucose 1-phosphate"]},
        {text:"Answer: glucose 4-phosphate."}],
      trap:"Reaching for glucose 6-phosphate because it is the familiar one: C6 is bonded to C5 but is the CH₂OH outside the ring."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"ring carbon",note:"C1–C5 only"},{t:"bonded to C5",note:"C4 or C6"},{t:"not to the ring oxygen",note:"rules out C1"}]},
      {text:"**Walk the ring.** Every carbon number follows from the ring order.",calc:["O – C1 – C2 – C3 – C4 – C5 – O","C6 hangs off C5"]},
      {text:"**Name by carbon number.** The number in a sugar phosphate's name is the carbon bearing the phosphate.",fig:"cpd-glucose-6-phosphate"},
      {text:"**Rule to reuse:** number the ring from C1, find the carbon that carries the phosphate, and name it glucose n-phosphate."}]},
  {id:"cpt-pe1-38c",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:38#3"],
    q:"A passage states that a plant kinase phosphorylates glucose at C3 only. In the pyranose form of the product, which carbons still carry free –OH groups?",
    choices:["C1, C2, C4, C6","C1, C2, C3, C4","C2, C4, C5, C6","C1, C2, C4, C5"],ans:0,
    exp:"Glucopyranose has –OH groups on **C1, C2, C3, C4 and C6**; C5 has none because it is bonded to the ring O. The passage puts the phosphate on **C3**, so C3's –OH is used and **C1, C2, C4 and C6** stay free.",
    how:{ask:"Which carbons of glucopyranose carry –OH groups, and which one does the passage say is phosphorylated?",
      know:"• –OH groups in glucopyranose: **C1, C2, C3, C4, C6** (C5 holds the ring O instead).\n• Use the position the passage states, even if it is not the familiar C6.",
      steps:[{text:"The passage names the site.",hl:"phosphorylates glucose at C3 only"},
        {text:"List the –OH carbons, then remove C3.",fig:"beta-glucopyranose",calc:["–OH on: C1, C2, C3, C4, C6","phosphate on C3 → free: **C1, C2, C4, C6**"]},
        {text:"That set keeps C3 free and uses C6: it is glucose 6-phosphate, not what the passage states.",strike:["C1, C2, C3, C4"]},
        {text:"C5 has no –OH (it is bonded to the ring O), and C1's anomeric –OH is still free.",strike:["C2, C4, C5, C6","C1, C2, C4, C5"]},
        {text:"Answer: C1, C2, C4, C6."}],
      trap:"Assuming the phosphate is on C6 out of habit: the passage says C3, so C6 keeps its –OH."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"at C3 only",note:"the stated site"},{t:"pyranose form",note:"ring: C5 bonded to ring O"},{t:"free –OH groups",note:"the ones left"}]},
      {text:"**Where are the –OH groups?** Five of six carbons carry one; C5 carries the ring O.",fig:"alpha-glucopyranose",calc:["OH: C1, C2, C3, C4, C6"]},
      {text:"**Use the passage's position.** Take away the carbon it names.",calc:["remove C3 → C1, C2, C4, C6"]},
      {text:"**Rule to reuse:** always put the phosphate where the passage says, then number the ring from C1; do not default to C6."}]},

  // ── Q39: glycogen synthase, branching enzyme, α vs β ──
  {id:"cpt-pe1-39a",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:39#1"],
    q:"After a meal, liver glycogen synthase lengthens the outer chains of glycogen. Each glucose it adds is joined to the chain by which linkage?",
    choices:["α-1,4","α-1,6","β-1,4","β-1,6"],ans:0,
    exp:"Glycogen synthase transfers glucose from UDP-glucose to the **C4 –OH** at the end of a chain, joining C1 of the new unit to C4 of the last one: an **α-1,4** link. Branch points (α-1,6) are made by the branching enzyme, and β links belong to cellulose, not glycogen.",
    how:{ask:"Which bond extends a glycogen chain end to end, as opposed to starting a branch?",
      know:"• **Glycogen synthase**: elongates chains with **α-1,4** bonds (C1 of new glucose → C4 of chain end).\n• **Branching enzyme**: makes **α-1,6** branch points.\n• β-1,4 is the bond of cellulose.",
      steps:[{text:"The enzyme lengthens chains; it does not branch them.",hl:"lengthens the outer chains of glycogen"},
        {text:"Chain growth is end to end.",fig:"t1-maltose",calc:["new glucose C1 → chain end C4","→ **α-1,4**"]},
        {text:"α-1,6 bonds are branch points, made by a different enzyme.",strike:["α-1,6"]},
        {text:"Glycogen has no β links; β-1,4 is cellulose.",strike:["β-1,4","β-1,6"]},
        {text:"Answer: α-1,4."}],
      trap:"Mixing up the two glycogen enzymes: synthase makes the α-1,4 chain; the branching enzyme makes α-1,6."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"glycogen synthase",note:"chain builder"},{t:"lengthens the outer chains",note:"end to end"}]},
      {text:"**Chains are α-1,4.** C1 of each glucose bonds to C4 of the next.",fig:"t1-maltose"},
      {text:"**Branches are α-1,6.** A chain starts off the C6 of an interior residue.",calc:["chain: C1 → C4","branch: C1 → C6"]},
      {text:"**Rule to reuse:** glycogen synthase forms α-1,4 bonds; the branching enzyme forms α-1,6 bonds."}]},
  {id:"cpt-pe1-39b",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:39#2"],
    q:"Glycogen's branching enzyme cuts a short block of glucose residues from a chain end and reattaches it to an interior residue. Which bond holds the block?",
    choices:["α-1,6","α-1,4","β-1,4","β-1,6"],ans:0,
    exp:"The branching enzyme breaks an α-1,4 bond near the chain end and joins the released block's C1 to the **C6 –OH** of an interior glucose. That **α-1,6** bond is a new branch point. α-1,4 bonds make the linear chain, and glycogen has no β links.",
    how:{ask:"When a block is moved to an interior residue to start a branch, which carbon of that residue does it bond to?",
      know:"• **Branching enzyme**: cuts an α-1,4 bond and forms an **α-1,6** bond (a branch point).\n• **Glycogen synthase**: forms α-1,4 bonds (chain growth).\n• β links appear in cellulose, not glycogen.",
      steps:[{text:"The block is moved onto an interior residue: a new branch.",hl:"reattaches it to an interior residue"},
        {text:"A branch attaches through C6.",calc:["block C1 → interior C6","→ **α-1,6** branch point"]},
        {text:"α-1,4 is the bond that was cut, the linear chain bond made by glycogen synthase.",strike:["α-1,4"]},
        {text:"Glycogen is built only from α links.",strike:["β-1,4","β-1,6"]},
        {text:"Answer: α-1,6."}],
      trap:"Choosing α-1,4 because the block is a piece of chain: inside the block the bonds are α-1,4, but the new bond to the interior residue is α-1,6."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"branching enzyme",note:"makes branch points"},{t:"interior residue",note:"bonds through C6"}]},
      {text:"**Two bonds in glycogen.** α-1,4 runs along a chain; α-1,6 starts a branch.",fig:"alpha-glucopyranose",calc:["chain: C1–O–C4","branch: C1–O–C6"]},
      {text:"**The branching enzyme cuts one and makes the other.**",calc:["break α-1,4 → form α-1,6"]},
      {text:"**Rule to reuse:** the branching enzyme forms α-1,6 bonds, one at each branch point."}]},
  {id:"cpt-pe1-39c",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:39#3"],
    q:"On a Haworth drawing of a D-glucose residue, its CH₂OH points up while C1's link to the next residue points down. How is this glycosidic link classified?",
    choices:["α, as in glycogen","β, as in glycogen","α, as in cellulose","β, as in cellulose"],ans:0,
    exp:"For a D-sugar in a Haworth drawing, compare the anomeric (C1) bond with the CH₂OH: **opposite faces → α**, same face → β. Here CH₂OH is up and the C1 bond is down, so the link is **α**, the type found in glycogen and starch. Cellulose uses β links.",
    how:{ask:"Is the C1 bond on the same face as the CH₂OH or on the opposite face?",
      know:"• **D-sugar, Haworth**: C1 substituent **opposite** CH₂OH → **α**; **same** face → **β**.\n• Glycogen and starch: α-1,4 (+ α-1,6). Cellulose: β-1,4.",
      steps:[{text:"Read the two directions.",hl:"its CH₂OH points up while C1's link to the next residue points down"},
        {text:"Opposite faces → α.",fig:["t1-maltose","t1-cello-beta"],calc:["CH₂OH up, C1 bond down → opposite → **α**"]},
        {text:"β would need the C1 bond on the same face as CH₂OH.",strike:["β, as in glycogen","β, as in cellulose"]},
        {text:"Cellulose is built from β links, so an α link is not cellulose's.",strike:["α, as in cellulose"]},
        {text:"Answer: α, as in glycogen."}],
      trap:"Thinking 'down' always means α: the test is relative to the CH₂OH; for a D-sugar drawn with CH₂OH up, down is α."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"CH₂OH points up",note:"the reference"},{t:"C1's link to the next residue points down",note:"the anomeric bond"}]},
      {text:"**Compare C1 with CH₂OH.** Opposite faces = α; same face = β.",fig:["alpha-glucopyranose","beta-glucopyranose"]},
      {text:"**Match to the polymer.** Glycogen and starch are α-linked; cellulose is β-linked.",calc:["α-1,4: glycogen, starch","β-1,4: cellulose"]},
      {text:"**Rule to reuse:** on a Haworth projection, a C1 bond opposite the CH₂OH is α and one on the same face is β."}]},

  // ── Q40: the sugars of nucleotides ──
  {id:"cpt-pe1-40a",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:40#1"],
    q:"In lactose synthesis, UDP-galactose donates its galactose. Apart from galactose, which sugar ring is part of UDP-galactose?",
    choices:["Ribofuranose","Deoxyribofuranose","Glucopyranose","Fructofuranose"],ans:0,
    exp:"UDP is **uridine diphosphate**. Uridine is uracil bonded to **ribose**, a five-membered (furanose) ring with –OH groups on C2′ and C3′. UDP is an RNA-type nucleotide, so its sugar is ribose, not deoxyribose; glucose and fructose are not part of it.",
    how:{ask:"What does UDP stand for, and which sugar is in that nucleoside?",
      know:"• **UDP** = uridine diphosphate; **uridine** = uracil + **ribose**.\n• Nucleotides without a \"d\" (ATP, UTP, UDP, CTP) carry **ribose**.\n• Deoxyribose appears in DNA nucleotides (dATP, dTTP…).",
      steps:[{text:"The molecule is galactose attached to UDP.",hl:"UDP-galactose"},
        {text:"Expand the name.",fig:["uracil","ribose"],calc:["UDP = uridine diphosphate","uridine = uracil + **ribose** (furanose)"]},
        {text:"UDP has no \"d\" prefix, so its sugar keeps the 2′ –OH: it is not deoxyribose.",strike:["Deoxyribofuranose"]},
        {text:"Glucose and fructose are not part of a uridine nucleotide.",strike:["Glucopyranose","Fructofuranose"]},
        {text:"Answer: ribofuranose."}],
      trap:"Picking glucose because UDP-sugars are usually UDP-glucose: the attached sugar varies, but the nucleotide's own sugar is always ribose."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"UDP-galactose",note:"galactose + UDP"},{t:"Apart from galactose",note:"the nucleotide's sugar"}]},
      {text:"**Read UDP.** Uridine diphosphate: uracil + ribose + two phosphates.",fig:"ribose",calc:["U = uridine","D = di (2 phosphates)","P = phosphate"]},
      {text:"**Ribose vs deoxyribose.** Ribose has –OH on C2′ and C3′; deoxyribose lacks the 2′ –OH.",fig:["t1-ribose-c2oh","t1-dr-c2"]},
      {text:"**Rule to reuse:** UDP is uridine diphosphate, and uridine contains ribose."}]},
  {id:"cpt-pe1-40b",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:40#2"],
    q:"Which of these nucleotides contains 2-deoxyribose rather than ribose as its sugar?",
    choices:["dGTP","UTP","CTP","UDP-glucose"],ans:0,
    exp:"The **\"d\" prefix means deoxy**: dGTP (deoxyguanosine triphosphate) is a DNA building block, so its sugar is **2-deoxyribose**, missing the C2′ –OH. UTP, CTP and UDP-glucose have no \"d\" and carry ribose, the RNA sugar.",
    how:{ask:"Which nucleotide is a DNA building block, marked by a \"d\" prefix?",
      know:"• **DNA nucleotides** (dATP, dGTP, dCTP, dTTP) → **2-deoxyribose** (no 2′ –OH).\n• **RNA nucleotides** and carriers (ATP, UTP, CTP, UDP-sugars) → **ribose**.",
      steps:[{text:"The target is the sugar missing the 2′ –OH.",hl:"2-deoxyribose rather than ribose"},
        {text:"Look for the \"d\".",fig:"deoxyribose",calc:["dGTP = **deoxy**guanosine triphosphate → 2-deoxyribose"]},
        {text:"UTP and CTP are RNA nucleotides with ribose, and UDP-glucose (glucose on uridine diphosphate) also carries ribose.",strike:["UTP","CTP","UDP-glucose"]},
        {text:"Answer: dGTP."}],
      trap:"Thinking uracil nucleotides are the odd ones out: UTP and UDP are RNA-type and contain ribose; only the \"d\" nucleotides have deoxyribose."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"2-deoxyribose",note:"no 2′ –OH"},{t:"rather than ribose",note:"RNA sugar"}]},
      {text:"**Compare the two sugars.** They differ only at C2′.",fig:["ribose","deoxyribose"],calc:["ribose: C₅H₁₀O₅","2-deoxyribose: C₅H₁₀O₄"]},
      {text:"**The name tells you.** A \"d\" in front (dTTP, dGTP) means a DNA nucleotide.",calc:["dXTP → deoxyribose","XTP, XDP → ribose"]},
      {text:"**Rule to reuse:** deoxyribose is found in DNA nucleotides such as dTTP; nucleotides without the \"d\" carry ribose."}]},

  // ── Q43: branching and α-1,6 bonds ──
  {id:"cpt-pe1-43a",s:"Carbohydrates, Lipids & Nucleic Acids",disc:"biochemistry",aamc:"5D",skill:"SIRS 1",from:["pe1-cp:43#1"],
    q:"Amylopectin has a branch point about every 25 glucose residues, while glycogen has one about every 10. Which bond is less common in amylopectin?",
    choices:["α-1,6 bonds","α-1,4 bonds","β-1,4 bonds","β-1,6 bonds"],ans:0,
    exp:"Every **branch point is one α-1,6 bond**. Amylopectin branches less often (every ~25 residues vs ~10), so per glucose it has **fewer α-1,6 bonds**. In both polymers nearly every other link is α-1,4, and neither polymer has β links.",
    how:{ask:"Which bond is counted by the number of branch points?",
      know:"• **α-1,4**: links glucose units along a chain.\n• **α-1,6**: one at each **branch point**.\n• Fewer branches → fewer α-1,6 bonds.\n• β-1,4 is cellulose's bond.",
      steps:[{text:"The difference is branching frequency.",hl:"a branch point about every 25 glucose residues, while glycogen has one about every 10"},
        {text:"Count α-1,6 bonds per 100 residues.",calc:["amylopectin: 100 ÷ 25 ≈ **4**","glycogen: 100 ÷ 10 ≈ **10**","fewer branches → fewer **α-1,6**"]},
        {text:"With fewer branches, amylopectin has slightly more chain bonds per residue, not fewer.",strike:["α-1,4 bonds"]},
        {text:"Neither polymer contains β links; β-1,4 belongs to cellulose.",strike:["β-1,4 bonds","β-1,6 bonds"]},
        {text:"Answer: α-1,6 bonds."}],
      trap:"Picking α-1,4 because it is the main starch bond: it builds the chains in both; only the branch bond tracks branching."},
    teach:[{text:"First, **find every number**.",marks:[{t:"every 25 glucose residues",note:"amylopectin: fewer branches"},{t:"every 10",note:"glycogen: more branches"}]},
      {text:"**One branch = one α-1,6 bond.**",fig:"t1-maltose",calc:["chain: α-1,4","branch point: α-1,6"]},
      {text:"**Compare the counts.**",calc:["1/25 < 1/10 → amylopectin has fewer α-1,6"]},
      {text:"**Rule to reuse:** branch points are α-1,6 bonds, so fewer branches means fewer α-1,6 bonds."}]},
  // ── Practice Exam 1 · Chem/Phys, general chemistry: Q28, 29, 31, 33, 44, 47, 48 ──
  // pe1-cp:28 (hybridization of a central atom with six bonding domains)
  {id:"cpt-pe1-28a",s:"Molecular Structure & Intermolecular Forces",disc:"gen_chem",aamc:"5B",skill:"SIRS 1",from:["pe1-cp:28#1"],
    q:"Sulfur hexafluoride, SF₆, has six fluorine atoms bonded to a central sulfur atom that carries no lone pairs. Which hybridization describes the sulfur?",
    choices:["sp³d²","sp³d³","dsp³","sp²"],ans:0,
    exp:"Six bonded atoms and no lone pairs = **6 electron domains**, so sulfur needs **6 hybrid orbitals**: sp³d² (1 s + 3 p + 2 d = 6), which point to the corners of an octahedron. d²sp³ is the same count, written when inner d orbitals mix in a metal complex. sp³d³ makes 7, dsp³ (another name for sp³d) makes 5, and sp² makes 3.",
    how:{ask:"Count sulfur's electron domains, then pick the hybridization label that makes exactly that many orbitals.",
      know:"• Hybrid orbitals needed = electron domains (bonded atoms + lone pairs).\n• **2 → sp; 3 → sp²; 4 → sp³ (tetrahedral); 5 → sp³d (trigonal bipyramidal); 6 → sp³d² or d²sp³ (octahedral)**.\n• Count the orbitals in a label: s = 1, then read each superscript for p and d (no superscript = 1).",
      steps:[{text:"Count sulfur's domains: six bonds and no lone pairs.",hl:"six fluorine atoms bonded to a central sulfur atom that carries no lone pairs",calc:["domains = 6 bonds + 0 lone pairs = **6**","6 domains → **6** hybrid orbitals → octahedral"]},
        {text:"Count the orbitals each label makes.",calc:["sp³d²: 1 + 3 + 2 = **6** → octahedral","sp³d³: 1 + 3 + 3 = 7 → pentagonal bipyramidal","dsp³: 1 + 1 + 3 = 5 → trigonal bipyramidal","sp²: 1 + 2 = 3 → trigonal planar"]},
        {text:"Seven orbitals is one too many, and five or three cannot hold six bonds.",strike:["sp³d³","dsp³","sp²"]},
        {text:"Answer: sp³d²."}],
      trap:"dsp³ also uses a d orbital, so it looks right for an expanded octet, but it makes only 5 hybrid orbitals: the trigonal bipyramidal set of PCl₅, not the octahedral set of SF₆."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"six fluorine atoms",note:"6 bonded atoms"},{t:"no lone pairs",note:"0 extra domains"},{t:"hybridization",note:"how many orbitals mix"}]},
      {text:"**Electron domains** = atoms bonded + lone pairs. Each domain needs one hybrid orbital.",calc:["SF₆: 6 + 0 = 6 domains → 6 orbitals"]},
      {text:"**Match the count to a label.**",calc:["4 → sp³ (CH₄, tetrahedral)","5 → sp³d (PCl₅, trigonal bipyramidal)","6 → sp³d² or d²sp³ (SF₆, octahedral)"]},
      {text:"**Rule to reuse:** 6 domains → octahedral → sp³d² (d²sp³ in metal complexes); 5 → sp³d; 4 → sp³."}]},

  // pe1-cp:29 (ideal-gas assumptions; molar volume at STP)
  {id:"cpt-pe1-29a",s:"Molecular Structure & Intermolecular Forces",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:29#1"],
    q:"A chemist wants a sample of argon to obey PV = nRT as closely as possible. Under which conditions should she study the gas?",
    choices:["High temperature; low pressure","Low temperature; high pressure","High temperature; high pressure","Low temperature; low pressure"],ans:0,
    exp:"The ideal-gas law assumes particles of **negligible volume** that feel **no intermolecular forces**. Low pressure spreads the atoms far apart, so their own volume is a tiny fraction of the container; high temperature makes them move so fast that brief attractions hardly matter. High pressure and low temperature each break one of these assumptions.",
    how:{ask:"Which conditions make the two ideal-gas assumptions (tiny particle volume, no attractions) most nearly true?",
      know:"• **Ideal-gas assumptions**: (1) particle volume is negligible compared with the container; (2) no attractions or repulsions between particles.\n• **Low P** → particles far apart → assumption 1 holds.\n• **High T** → kinetic energy ≫ attraction energy → assumption 2 holds.\n• Real gases deviate most at high P and low T.",
      steps:[{text:"The goal is ideal behavior, so look for conditions that make both assumptions hold.",hl:"obey PV = nRT as closely as possible"},
        {text:"Particle volume: at high pressure the atoms are squeezed together and their own volume is no longer negligible.",calc:["low P → much empty space per atom → particle volume ≈ 0 ✓"],strike:["High temperature; high pressure","Low temperature; high pressure"]},
        {text:"Attractions: at low temperature the atoms move slowly and cling briefly, so the measured pressure falls below nRT/V.",calc:["high T → kinetic energy ≫ attraction → forces ≈ 0 ✓"],strike:["Low temperature; low pressure"]},
        {text:"Answer: high temperature; low pressure."}],
      trap:"Low temperature; low pressure fixes the volume problem but not the attraction problem: slow atoms still feel London forces, and near condensation the gas is far from ideal."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"argon",note:"a real gas"},{t:"PV = nRT",note:"the ideal-gas law"},{t:"as closely as possible",note:"most ideal conditions"}]},
      {text:"**The ideal-gas model makes two assumptions**: the particles themselves take up **no volume**, and they feel **no intermolecular forces** (no attraction, no repulsion).",calc:["assumption 1: particle volume negligible","assumption 2: no intermolecular forces"]},
      {text:"**Ask what breaks each one.** Crowding (high pressure) makes particle volume matter; slow motion (low temperature) lets attractions matter."},
      {text:"**Rule to reuse:** a gas is most ideal at high T and low P, where particle volume and intermolecular forces are both negligible."}]},
  {id:"cpt-pe1-29b",s:"Stoichiometry & Solutions",disc:"gen_chem",aamc:"4B",skill:"SIRS 1",from:["pe1-cp:29#2"],
    q:"A sealed flask holds 2.00 mol of nitrogen gas at STP. Assuming ideal behavior, what volume does the gas occupy?",
    choices:["44.8 L","48.9 L","11.2 L","89.6 L"],ans:0,
    exp:"At **STP (0 °C = 273 K, 1 atm)** one mole of ideal gas fills **22.4 L**, so V = 2.00 mol × 22.4 L/mol = **44.8 L**. 48.9 L is what the sample would fill at 298 K (room temperature), not at STP; 11.2 L divides by 2 instead of multiplying; 89.6 L doubles the answer again.",
    how:{ask:"What is the molar volume at STP, and how many moles are in the flask?",
      know:"• **STP = 0 °C (273 K) and 1 atm**. At STP, 1 mol of ideal gas occupies **22.4 L**.\n• 22.4 L/mol holds only at 0 °C; at 25 °C (298 K) a mole fills about 24.5 L.\n• Check with PV = nRT: V = nRT/P.",
      steps:[{text:"Note the amount and the conditions.",hl:"2.00 mol of nitrogen gas at STP",calc:["n = 2.00 mol","STP: T = 273 K, P = 1 atm"]},
        {text:"Use the molar volume at STP.",calc:["V = n × 22.4 L/mol","V = 2.00 mol × 22.4 L/mol","V = **44.8 L**"]},
        {text:"Check with PV = nRT.",calc:["V = nRT ÷ P","V = (2.00 mol)(0.0821 L·atm·mol⁻¹·K⁻¹)(273 K) ÷ 1 atm","V = **44.8 L** ✓"]},
        {text:"48.9 L uses 298 K (25 °C), room temperature, which is not STP.",calc:["(2.00)(0.0821)(298) ÷ 1 = 48.9 L"],strike:["48.9 L"]},
        {text:"11.2 L divides 22.4 by 2 instead of multiplying, and 89.6 L doubles the right answer again.",strike:["11.2 L","89.6 L"]},
        {text:"Answer: 44.8 L."}],
      trap:"Using 24.5 L/mol, the molar volume at 25 °C, gives 48.9 L. The 22.4 L/mol shortcut belongs to 0 °C only."},
    teach:[{text:"First, **find every number** and what it stands for.",marks:[{t:"2.00 mol",note:"n"},{t:"STP",note:"0 °C and 1 atm"},{t:"ideal behavior",note:"use the molar volume"}]},
      {text:"**STP** means standard temperature and pressure: **0 °C (273 K) and 1 atm**. There, one mole of any ideal gas fills **22.4 L**.",calc:["at STP: 1 mol ↔ 22.4 L"]},
      {text:"**Temperature matters.** Volume grows with T, so at 25 °C a mole fills more.",calc:["0 °C: 22.4 L/mol","25 °C: 22.4 × 298/273 ≈ 24.5 L/mol"]},
      {text:"**Rule to reuse:** V = n × 22.4 L/mol only at STP (0 °C, 1 atm); at any other temperature use PV = nRT."}]},

  // pe1-cp:31 (a pocket that binds a nonpolar ligand)
  {id:"cpt-pe1-31a",s:"Amino Acids & Proteins",disc:"gen_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:31#1"],
    q:"An insect odorant-binding protein holds a small hydrocarbon odorant inside a buried cavity. Which residue would most likely line that cavity?",
    choices:["Valine","Glutamate","Arginine","Threonine"],ans:0,
    exp:"A hydrocarbon odorant is **nonpolar**, so it binds best in a **hydrophobic pocket** whose side chains are also hydrocarbon. Valine's isopropyl group is all C and H and packs against the odorant (like dissolves like). Glutamate (–COO⁻) and arginine (guanidinium, +) are charged, and threonine's –OH is polar; all three would rather face water.",
    how:{ask:"Is the odorant polar or nonpolar, and which side chain is itself pure hydrocarbon?",
      know:"• **Nonpolar side chains** (hydrophobic): Ala, **Val, Leu, Ile**, Met, **Phe**, Trp, Pro.\n• **Polar uncharged**: Ser, **Thr**, Asn, Gln, Tyr, Cys. **Charged**: Asp, **Glu** (−); Lys, **Arg**, His (+).\n• Like dissolves like: a hydrocarbon ligand is buried among hydrocarbon side chains.",
      steps:[{text:"The ligand is a hydrocarbon: only C and H, so it is nonpolar.",hl:"a small hydrocarbon odorant",calc:["C–H bonds share electrons almost evenly → **nonpolar**"]},
        {text:"It sits in a buried cavity, away from water, so the lining must be hydrophobic too.",hl:"inside a buried cavity"},
        {text:"Valine's side chain is all C and H: it fits.",calc:["Val: –CH(CH₃)₂ → nonpolar ✓"]},
        {text:"Glutamate carries –COO⁻ and arginine a positive guanidinium at pH 7: charges want water. Threonine's –OH is polar.",strike:["Glutamate","Arginine","Threonine"]},
        {text:"Answer: valine."}],
      trap:"Threonine looks harmless because it is small and uncharged, but its –OH makes it polar; a pocket for a pure hydrocarbon is lined with Leu, Ile, Val and Phe."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"hydrocarbon odorant",note:"only C and H → nonpolar"},{t:"buried cavity",note:"away from water"},{t:"line that cavity",note:"side chains facing the ligand"}]},
      {text:"**Polar vs nonpolar:** O and N pull electrons and make polar or charged groups; C–H bonds are nonpolar. Hydrocarbons mix with hydrocarbons, not with water."},
      {text:"**The hydrophobic four** to remember for pockets: side chains made only of carbon and hydrogen.",calc:["Leu: –CH₂CH(CH₃)₂","Ile: –CH(CH₃)CH₂CH₃","Val: –CH(CH₃)₂","Phe: –CH₂C₆H₅"]},
      {text:"**Rule to reuse:** a nonpolar ligand binds in a hydrophobic pocket lined with Leu, Ile, Val and Phe."}]},
  {id:"cpt-pe1-31b",s:"Amino Acids & Proteins",disc:"gen_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:31#2"],
    q:"A fatty-acid-binding protein holds a long hydrocarbon chain against a leucine deep in its interior. Replacing that leucine with which residue would most weaken binding?",
    choices:["Glutamate","Isoleucine","Phenylalanine","Methionine"],ans:0,
    exp:"The chain is nonpolar, so binding relies on hydrophobic contacts. **Glutamate** puts a charged –COO⁻ into that nonpolar region: the charge loses its shell of water, which costs a lot of energy, and it gains nothing from touching C–H. Isoleucine, phenylalanine and methionine are all nonpolar and keep the pocket hydrophobic.",
    how:{ask:"Which substitution puts a charge or a polar group into a pocket built for a hydrocarbon?",
      know:"• Charged (Asp, Glu, Lys, Arg) and polar (Ser, Thr, Asn, Gln) side chains interact well with water, not with C–H surfaces.\n• Burying a charge in a nonpolar region costs its hydration energy, so it destabilizes binding.\n• Swapping one nonpolar residue for another (Leu → Ile, Phe, Met) keeps the pocket hydrophobic.",
      steps:[{text:"The contact is hydrocarbon on hydrocarbon.",hl:"long hydrocarbon chain against a leucine",calc:["chain: C–H only → nonpolar","Leu: –CH₂CH(CH₃)₂ → nonpolar"]},
        {text:"Isoleucine, phenylalanine and methionine are nonpolar too, so they keep the hydrophobic contact.",strike:["Isoleucine","Phenylalanine","Methionine"]},
        {text:"Glutamate puts a negative group against the chain: a charged lining doesn't fit a nonpolar ligand.",calc:["Glu: –CH₂CH₂COO⁻ → charged at pH 7"]},
        {text:"Answer: glutamate."}],
      trap:"Phenylalanine is the bulkiest choice, so it looks disruptive, but its benzene ring is pure hydrocarbon and packs well against a fatty chain."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"long hydrocarbon chain",note:"nonpolar ligand"},{t:"deep in its interior",note:"away from water"},{t:"most weaken binding",note:"find the misfit"}]},
      {text:"**Sort the side chains:** nonpolar (Ile, Phe, Met, like Leu) versus charged (Glu, −1 at pH 7)."},
      {text:"**Charges and polar groups want water.** Placed against a hydrocarbon, they give up their contacts with water and gain nothing back."},
      {text:"**Rule to reuse:** charged or polar side chains don't fit a pocket for a nonpolar ligand; swapping in Asp, Glu, Lys, Arg, Ser or Thr weakens binding."}]},

  // pe1-cp:33 (sp² carbons of a C=C; why cis/trans isomers exist)
  {id:"cpt-pe1-33a",s:"Molecular Structure & Intermolecular Forces",disc:"gen_chem",aamc:"5B",skill:"SIRS 1",from:["pe1-cp:33#1"],
    q:"In 1,2-dichloroethene, ClHC=CHCl, each carbon of the double bond is bonded to three atoms and has no lone pairs. What are its hybridization and geometry?",
    choices:["sp²; trigonal planar","sp³; trigonal pyramidal","sp³; tetrahedral","sp; linear"],ans:0,
    exp:"Three bonded atoms and no lone pairs give **three domains**, so each alkene carbon is **sp²**: trigonal planar with 120° angles. The one p orbital left unmixed on each carbon forms the π bond of C=C. sp³ needs four domains (tetrahedral, or trigonal pyramidal with a lone pair); sp needs two (linear).",
    how:{ask:"Count the electron domains on an alkene carbon and convert them to a hybridization and shape.",
      know:"• Electron domains = bonded atoms + lone pairs (a double bond counts once).\n• **4 → sp³**, tetrahedral, 109.5° (with one lone pair: trigonal pyramidal); **3 → sp²**, trigonal planar, 120°; **2 → sp**, linear, 180°.",
      steps:[{text:"Count the domains on one alkene carbon.",hl:"bonded to three atoms and has no lone pairs",calc:["domains = 3 atoms (Cl, H, C) + 0 lone pairs = **3**"]},
        {text:"Three domains → three sp² hybrid orbitals, spread as far apart as possible in one plane.",calc:["3 domains → **sp²**","angles ≈ 120° → **trigonal planar**"]},
        {text:"sp³ needs four domains: tetrahedral with four atoms, trigonal pyramidal with three atoms plus a lone pair. These carbons have neither.",strike:["sp³; trigonal pyramidal","sp³; tetrahedral"]},
        {text:"sp needs only two domains, as in a C≡C or C≡N carbon.",strike:["sp; linear"]},
        {text:"Answer: sp²; trigonal planar."}],
      trap:"sp³; trigonal pyramidal also has three atoms around the center, but that shape needs a fourth domain, a lone pair, which these alkene carbons do not have."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"ClHC=CHCl",note:"C=C double bond"},{t:"three atoms",note:"3 bonded groups"},{t:"no lone pairs",note:"nothing extra"}]},
      {text:"**Electron domains** are the regions of electrons around an atom: each bonded atom counts once (single, double or triple bond), and each lone pair counts once."},
      {text:"**Domains → hybridization → shape.**",calc:["2 → sp → linear","3 → sp² → trigonal planar","4 → sp³ → tetrahedral"]},
      {text:"**Rule to reuse:** each carbon of a C=C has 3 domains, so it is sp² and trigonal planar (120°)."}]},
  {id:"cpt-pe1-33b",s:"Molecular Structure & Intermolecular Forces",disc:"gen_chem",aamc:"5B",skill:"SIRS 1",from:["pe1-cp:33#2"],
    q:"Cis- and trans-but-2-ene can be stored as separate pure compounds because neither one turns into the other at 25 °C. What prevents the interconversion?",
    choices:["The C=C π bond","The C=C σ bond","Hydrogen bonding","Methyl group repulsion"],ans:0,
    exp:"Turning one end of a C=C twists the two p orbitals out of side-by-side overlap, which breaks the **π bond** (about 260 kJ/mol); room-temperature collisions cannot supply that energy. A σ bond alone allows rotation, as in butane. But-2-ene has no O–H or N–H for hydrogen bonding, and methyl repulsion only makes the trans form slightly more stable.",
    how:{ask:"What would have to break for one end of the double bond to rotate relative to the other?",
      know:"• A C=C = 1 σ bond (head-on overlap) + 1 π bond (side-by-side overlap of p orbitals).\n• σ bonds are symmetric around the bond axis, so single bonds rotate freely.\n• Rotating a C=C would break the π overlap → no rotation at room temperature → **cis/trans isomers** when each alkene carbon has two different groups.",
      steps:[{text:"Geometric isomers that stay separate point to a bond that cannot rotate.",hl:"neither one turns into the other at 25 °C"},
        {text:"The π bond is side-by-side overlap of two p orbitals; a 90° twist destroys that overlap.",calc:["π bond energy ≈ 260 kJ/mol","thermal energy at 298 K: RT = 8.314 × 298 ≈ 2.5 kJ/mol → far too small"]},
        {text:"A σ bond is cylindrical, so it keeps its overlap as it turns: that is why butane has no cis/trans isomers.",strike:["The C=C σ bond"]},
        {text:"But-2-ene has no O–H or N–H, so no hydrogen bonds; methyl repulsion only makes trans a little more stable and does not lock the shape.",strike:["Hydrogen bonding","Methyl group repulsion"]},
        {text:"Answer: the C=C π bond."}],
      trap:"The σ bond is the stronger half of the double bond, but strength is not what stops rotation: a σ bond keeps its overlap as it turns, while the π bond does not."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Cis- and trans-but-2-ene",note:"same atoms, different geometry"},{t:"neither one turns into the other",note:"something locks the shape"}]},
      {text:"**Cis/trans:** on a C=C, two groups can sit on the same side (cis) or on opposite sides (trans) of the double bond."},
      {text:"**Why it locks:** the π bond needs the two p orbitals parallel. Twist one carbon and the overlap, and with it the π bond, is lost.",calc:["0° twist: full π overlap","90° twist: no π overlap → π bond broken"]},
      {text:"**Rule to reuse:** cis/trans isomers exist because a C=C cannot rotate without breaking its π bond."}]},

  // pe1-cp:44 (strong acids; successive Ka values; the weakest acid in a polyprotic series)
  {id:"cpt-pe1-44a",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:44#1"],
    q:"Which pair contains two acids that each give up their first proton essentially completely in dilute aqueous solution?",
    choices:["HCl and H₂SO₄","HF and H₂SO₄","HCl and H₂CO₃","HF and H₃PO₄"],ans:0,
    exp:"HCl and H₂SO₄ (its first proton) are on the short list of **strong acids** (HCl, HBr, HI, HNO₃, HClO₄, H₂SO₄), which ionize essentially 100% in water. HF (pKa ≈ 3.2), H₂CO₃ (pKa₁ ≈ 6.4) and H₃PO₄ (pKa₁ ≈ 2.1) are weak acids, so every pair that includes one of them fails.",
    how:{ask:"Which of the named acids belong to the list of strong acids?",
      know:"• **Strong acids** (fully ionized in dilute water): HCl, HBr, HI, HNO₃, HClO₄, and H₂SO₄ for its first proton.\n• **Weak acids** (partly ionized, an equilibrium): HF, H₃PO₄, H₂CO₃, carboxylic acids.\n• H₂SO₄'s second proton (from HSO₄⁻, pKa ≈ 2) is weak.",
      steps:[{text:"The stem asks for complete ionization of the first proton: a strong acid.",hl:"essentially completely"},
        {text:"Check each acid against the strong-acid list.",calc:["HCl → strong ✓","H₂SO₄ → strong for its first H⁺ ✓","HF → weak (pKa ≈ 3.2)","H₂CO₃ → weak (pKa₁ ≈ 6.4)","H₃PO₄ → weak (pKa₁ ≈ 2.1)"]},
        {text:"Any pair with a weak acid in it fails.",strike:["HF and H₂SO₄","HCl and H₂CO₃","HF and H₃PO₄"]},
        {text:"Answer: HCl and H₂SO₄."}],
      trap:"HF looks like it should be strong because fluorine is the most electronegative halogen, but the very strong H–F bond and the small F⁻ ion make HF a weak acid."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"first proton",note:"H₂SO₄ has two"},{t:"essentially completely",note:"strong acid"},{t:"dilute aqueous solution",note:"in water"}]},
      {text:"**Strong vs weak:** a strong acid ionizes all the way (HA → H⁺ + A⁻); a weak acid sets up an equilibrium (HA ⇌ H⁺ + A⁻) and stays mostly as HA."},
      {text:"**Memorize the strong six:** HCl, HBr, HI, HNO₃, HClO₄, H₂SO₄ (first proton only). Most other common acids are weak."},
      {text:"**Rule to reuse:** HCl and H₂SO₄ (first H⁺) are strong acids; HF, H₃PO₄ and H₂CO₃ are weak."}]},
  {id:"cpt-pe1-44b",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:44#2"],
    q:"Oxalic acid, H₂C₂O₄, has pKa₁ = 1.3. Which value is most reasonable for the pKa of its second proton?",
    choices:["4.3","1.3","0.3","−0.7"],ans:0,
    exp:"Each successive proton is harder to remove because it must leave an ion that is **already negative** and holds H⁺ more tightly. So Ka₂ ≪ Ka₁, which means **pKa₂ is larger** than pKa₁; the measured value is about **4.3**. A pKa₂ equal to 1.3, or smaller (0.3, −0.7), would make the second proton as easy or easier to lose.",
    how:{ask:"Should the second proton come off more or less easily than the first, and which way does that move the pKa?",
      know:"• Polyprotic acids lose H⁺ one at a time: Ka₁ > Ka₂ > Ka₃, each usually much smaller.\n• Reason: removing H⁺ from an anion fights the attraction of the negative charge.\n• pKa = −log Ka: **smaller Ka → larger pKa**.",
      steps:[{text:"The second proton leaves HC₂O₄⁻, an anion.",hl:"pKa₁ = 1.3",calc:["H₂C₂O₄ ⇌ H⁺ + HC₂O₄⁻   (pKa₁ = 1.3)","HC₂O₄⁻ ⇌ H⁺ + C₂O₄²⁻   (pKa₂ = ?)"]},
        {text:"Pulling H⁺ off a negative ion is harder, so Ka₂ is smaller and pKa₂ is larger than 1.3. Equal or smaller values are out.",calc:["Ka₂ < Ka₁ → pKa₂ > 1.3"],strike:["1.3","0.3","−0.7"]},
        {text:"Only one value is larger; see the acid strengths it implies.",calc:["Ka₁ = 10^−1.3 ≈ 5 × 10⁻²","Ka₂ = 10^−4.3 ≈ 5 × 10⁻⁵","Ka₂ is about 1000 times smaller"]},
        {text:"Answer: 4.3."}],
      trap:"Picking 1.3 assumes both protons are alike because they look alike in H₂C₂O₄; once the first one leaves, the remaining one is held by a negative ion."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Oxalic acid",note:"diprotic: two H⁺"},{t:"pKa₁ = 1.3",note:"first proton"},{t:"second proton",note:"comes off an anion"}]},
      {text:"**Polyprotic acids** give up their protons one at a time, and each step has its own Ka.",calc:["H₂A → HA⁻ (Ka₁)","HA⁻ → A²⁻ (Ka₂)"]},
      {text:"**Each step is harder:** the more negative the ion, the more it attracts H⁺. Smaller Ka means larger pKa.",calc:["Ka₁ > Ka₂ > Ka₃","pKa₁ < pKa₂ < pKa₃"]},
      {text:"**Rule to reuse:** each successive Ka of a polyprotic acid is much smaller, because H⁺ is harder to remove from a more negative ion."}]},
  {id:"cpt-pe1-44c",s:"Acids & Bases",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:44#3"],
    q:"Arsenic acid, H₃AsO₄, is triprotic. Which of these acids dissociates to the smallest extent when dissolved in water?",
    choices:["HAsO₄²⁻","H₂AsO₄⁻","H₃AsO₄","HNO₃"],ans:0,
    exp:"HNO₃ is a strong acid. Arsenic acid's three Ka values fall steeply (pKa ≈ 2.2, 7.0, 11.5) because each H⁺ comes off a more negative ion. **HAsO₄²⁻** must lose H⁺ from a 2− ion, so it has the smallest Ka and dissociates least, just as HPO₄²⁻ does in the phosphate series.",
    how:{ask:"Rank the four by Ka: the strong acid first, then each successive arsenic-acid step.",
      know:"• A strong acid (HNO₃) ionizes completely.\n• Triprotic acid: H₃A → H₂A⁻ → HA²⁻ → A³⁻, with Ka₁ ≫ Ka₂ ≫ Ka₃.\n• The most negative species that still has an H⁺ is the weakest acid.",
      steps:[{text:"HNO₃ is a strong acid: it dissociates completely.",strike:["HNO₃"]},
        {text:"Write the three arsenic-acid steps.",hl:"is triprotic",calc:["H₃AsO₄ ⇌ H⁺ + H₂AsO₄⁻   pKa₁ ≈ 2.2","H₂AsO₄⁻ ⇌ H⁺ + HAsO₄²⁻   pKa₂ ≈ 7.0","HAsO₄²⁻ ⇌ H⁺ + AsO₄³⁻   pKa₃ ≈ 11.5"]},
        {text:"Each step is about 10⁴–10⁵ times weaker than the one before, because H⁺ leaves an ever more negative ion.",calc:["Ka₁ ≈ 6 × 10⁻³ > Ka₂ ≈ 1 × 10⁻⁷ > Ka₃ ≈ 3 × 10⁻¹²"],strike:["H₃AsO₄","H₂AsO₄⁻"]},
        {text:"Answer: HAsO₄²⁻."}],
      trap:"H₃AsO₄ is the weak acid named in the stem, but it is the strongest of the three arsenic species; its ions are weaker still."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"triprotic",note:"three H⁺ to lose"},{t:"smallest extent",note:"weakest acid, smallest Ka"}]},
      {text:"**Strong acids are out:** HNO₃ ionizes completely, so it dissociates most."},
      {text:"**Line up the arsenic species by charge:** neutral H₃AsO₄, then 1− H₂AsO₄⁻, then 2− HAsO₄²⁻. The more negative the ion, the more tightly it holds H⁺.",calc:["0 → 1− → 2−","Ka₁ ≫ Ka₂ ≫ Ka₃"]},
      {text:"**Rule to reuse:** in a polyprotic series, the most negative ion that still carries an H⁺ (HPO₄²⁻, HAsO₄²⁻, HCO₃⁻) is the weakest acid."}]},

  // pe1-cp:47 (signs of ΔG and ΔS; ΔG = ΔH − TΔS)
  {id:"cpt-pe1-47a",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:47#1"],
    q:"Iron nails left outdoors slowly rust with no outside input of energy. What is the sign of ΔG for the rusting reaction under these conditions?",
    choices:["Negative","Positive","Zero","Cannot be known"],ans:0,
    exp:"A process that proceeds on its own is **spontaneous**, and spontaneous means **ΔG < 0**. Speed does not matter: rusting is slow (kinetics) but still downhill in free energy (thermodynamics). A positive ΔG would make the reverse spontaneous, and ΔG = 0 means equilibrium.",
    how:{ask:"Does the reaction run by itself, and what does that say about ΔG?",
      know:"• **ΔG < 0 → spontaneous** (proceeds without outside energy).\n• ΔG > 0 → nonspontaneous (the reverse is spontaneous). ΔG = 0 → equilibrium.\n• ΔG says nothing about speed: a spontaneous reaction can be very slow.",
      steps:[{text:"The rusting happens on its own.",hl:"with no outside input of energy",calc:["runs by itself → spontaneous"]},
        {text:"Spontaneous means the free energy falls.",calc:["spontaneous ⇔ **ΔG < 0**"],strike:["Positive"]},
        {text:"ΔG = 0 only at equilibrium, where nothing changes overall; and the observation itself fixes the sign, so it can be known.",strike:["Zero","Cannot be known"]},
        {text:"Answer: negative."}],
      trap:"\"Slowly\" tempts you to call the reaction barely favorable or unknowable, but rate is kinetics; spontaneity depends only on the sign of ΔG."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"slowly rust",note:"slow but happening"},{t:"no outside input of energy",note:"runs by itself"},{t:"sign of ΔG",note:"what to find"}]},
      {text:"**ΔG (Gibbs free energy change)** tells which way a reaction runs by itself.",calc:["ΔG < 0: spontaneous","ΔG = 0: at equilibrium","ΔG > 0: not spontaneous"]},
      {text:"**Speed is separate.** Kinetics (activation energy) sets how fast; ΔG only sets whether."},
      {text:"**Rule to reuse:** spontaneous means ΔG < 0, however slow the reaction."}]},
  {id:"cpt-pe1-47b",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:47#2"],
    q:"Magnesium ribbon dropped into dilute sulfuric acid fizzes: Mg(s) + H₂SO₄(aq) → MgSO₄(aq) + H₂(g). What is the sign of ΔS for this reaction?",
    choices:["Positive","Negative","Zero","Equal to ΔH"],ans:0,
    exp:"Entropy measures how many ways the particles and their energy can be arranged: **gas ≫ liquid or solution > solid**. Here a solid and a solution produce **hydrogen gas** where there was none, so the products are far more spread out and **ΔS > 0**. ΔS and ΔH are different quantities with different units, so they are not equal.",
    how:{ask:"Count the moles of gas on each side of the equation.",
      know:"• **Entropy (S)**: disorder, the number of possible arrangements. S(gas) ≫ S(liquid, aq) > S(solid).\n• Gas formed from solids or solutions (Δn_gas > 0) → **ΔS > 0**.\n• Gas consumed (Δn_gas < 0) → ΔS < 0.",
      steps:[{text:"Read the phases.",hl:"Mg(s) + H₂SO₄(aq) → MgSO₄(aq) + H₂(g)",calc:["reactants: solid + solution → 0 mol gas","products: solution + **H₂(g)** → 1 mol gas"]},
        {text:"Gas appears where there was none.",calc:["Δn(gas) = 1 − 0 = **+1** → ΔS > 0"],strike:["Negative","Zero"]},
        {text:"ΔS (J/K) and ΔH (kJ) measure different things, so ΔS is not set equal to ΔH.",strike:["Equal to ΔH"]},
        {text:"Answer: positive."}],
      trap:"Metal ions dissolving can order nearby water molecules, but making a gas far outweighs it: any reaction that produces gas from no gas has ΔS > 0."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"fizzes",note:"a gas forms"},{t:"Mg(s)",note:"solid"},{t:"H₂(g)",note:"gas"},{t:"sign of ΔS",note:"what to find"}]},
      {text:"**Phase labels:** (s) solid, (l) liquid, (aq) dissolved in water, (g) gas."},
      {text:"**Entropy ranking:** gas particles roam the whole container, so a gas has far more possible arrangements.",calc:["S: solid < liquid ≈ aq ≪ gas"]},
      {text:"**Rule to reuse:** a reaction that makes gas from a solid or solution has ΔS > 0."}]},
  {id:"cpt-pe1-47c",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 1",from:["pe1-cp:47#3"],
    q:"A decomposition that releases a gas has ΔH = +40 kJ/mol and ΔS = +120 J/(mol·K). Above what temperature does it become spontaneous?",
    choices:["333 K","0.33 K","4800 K","3.0 K"],ans:0,
    exp:"Use **ΔG = ΔH − TΔS**. With ΔH > 0 and ΔS > 0, ΔG turns negative only once TΔS outgrows ΔH, so set ΔG = 0: T = ΔH/ΔS = 40,000 J/mol ÷ 120 J/(mol·K) = **333 K**. Above 333 K, ΔG < 0. 0.33 K forgets to convert kJ to J, 4800 K multiplies, and 3.0 K divides ΔS by ΔH.",
    how:{ask:"At what temperature does ΔH − TΔS change sign from positive to negative?",
      know:"• **ΔG = ΔH − TΔS**; spontaneous when ΔG < 0.\n• Signs: ΔH < 0, ΔS > 0 → always spontaneous; ΔH > 0, ΔS < 0 → never; ΔH > 0, ΔS > 0 → spontaneous at high T; ΔH < 0, ΔS < 0 → at low T.\n• Crossover: T = ΔH/ΔS, with both in the same energy unit (J).",
      steps:[{text:"Note the signs and match the units.",hl:"ΔH = +40 kJ/mol",calc:["ΔH = +40 kJ/mol = +40,000 J/mol","ΔS = +120 J/(mol·K)","ΔH > 0, ΔS > 0 → spontaneous only at high T"]},
        {text:"Set ΔG = 0 at the crossover and solve for T.",calc:["0 = ΔH − TΔS","T = ΔH ÷ ΔS","T = 40,000 J/mol ÷ 120 J/(mol·K)","T = **333 K**"]},
        {text:"Check above it, at 400 K.",calc:["ΔG = 40,000 − (400)(120) J/mol","ΔG = 40,000 − 48,000 = **−8,000 J/mol** < 0 ✓"]},
        {text:"The other values come from unit or arithmetic slips: 40 ÷ 120 leaves kJ against J, 40 × 120 multiplies, and 120 ÷ 40 inverts.",calc:["40 ÷ 120 = 0.33","40 × 120 = 4800","120 ÷ 40 = 3.0"],strike:["0.33 K","4800 K","3.0 K"]},
        {text:"Answer: 333 K."}],
      trap:"Dividing 40 by 120 without converting kJ to J gives 0.33 K, a thousand times too small; always put ΔH and ΔS in the same energy unit."},
    teach:[{text:"First, **find every number** and its sign.",marks:[{t:"releases a gas",note:"ΔS > 0"},{t:"ΔH = +40 kJ/mol",note:"endothermic"},{t:"ΔS = +120 J/(mol·K)",note:"entropy rises"},{t:"Above what temperature",note:"find the crossover T"}]},
      {text:"**ΔG = ΔH − TΔS.** A positive ΔH works against spontaneity; a positive ΔS works for it, more so as T rises."},
      {text:"**Crossover:** spontaneity switches where ΔG = 0, so T = ΔH/ΔS.",calc:["T = ΔH ÷ ΔS (ΔH in J, not kJ)"]},
      {text:"**Rule to reuse:** check signs with ΔG = ΔH − TΔS; when ΔH and ΔS are both positive, the reaction is spontaneous above T = ΔH/ΔS."}]},

  // pe1-cp:48 (overall reaction from a mechanism; balance check; catalyst vs intermediate)
  {id:"cpt-pe1-48a",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"4E",skill:"SIRS 1",from:["pe1-cp:48#1"],
    q:"Chlorine atoms destroy ozone in two steps: Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂. What is the overall reaction?",
    choices:["O₃ + O → 2O₂","Cl + O₃ + O → Cl + 2O₂","O₃ + ClO → Cl + 2O₂","2O₃ → 3O₂"],ans:0,
    exp:"Add the two steps and cross out anything on both sides: Cl + O₃ + ClO + O → ClO + O₂ + Cl + O₂ becomes **O₃ + O → 2O₂**. Cl is used and then regenerated (a catalyst), and ClO is made and then used (an intermediate), so neither appears overall. Leaving Cl on both sides is an unfinished sum; 2O₃ → 3O₂ is a different net reaction.",
    how:{ask:"Add the steps, then cancel each species that appears on both sides.",
      know:"• **Overall reaction** = sum of the elementary steps (multiply a step if needed so shared species cancel).\n• Cancel species found on both sides: **catalysts** (used, then regenerated) and **intermediates** (made, then used).\n• What's left holds only the true reactants and products.",
      steps:[{text:"Write both steps and add them.",hl:"Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂",calc:["Cl + O₃ → ClO + O₂","ClO + O → Cl + O₂","sum: Cl + O₃ + ClO + O → ClO + O₂ + Cl + O₂"]},
        {text:"Cancel Cl and ClO, each found on both sides, and combine the O₂.",calc:["cancel Cl (left and right)","cancel ClO (left and right)","**O₃ + O → 2O₂**"]},
        {text:"Leaving Cl on both sides is a sum that was never simplified; keeping ClO as a reactant cancels the wrong species.",strike:["Cl + O₃ + O → Cl + 2O₂","O₃ + ClO → Cl + 2O₂"]},
        {text:"2O₃ → 3O₂ is balanced, but it uses no free O atom, so it is not the sum of these steps.",strike:["2O₃ → 3O₂"]},
        {text:"Answer: O₃ + O → 2O₂."}],
      trap:"Cl + O₃ + O → Cl + 2O₂ is balanced and looks complete, but a species on both sides must be cancelled; an overall equation never shows a catalyst."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"two steps",note:"a mechanism"},{t:"Cl + O₃ → ClO + O₂",note:"step one"},{t:"ClO + O → Cl + O₂",note:"step two"},{t:"overall reaction",note:"sum and cancel"}]},
      {text:"**A mechanism** is the list of elementary steps a reaction actually goes through. Adding them gives the overall equation."},
      {text:"**Cancel like terms**, just as in algebra: a species on both sides drops out.",calc:["A + B → C","C + D → A + E","sum: B + D → E"]},
      {text:"**Rule to reuse:** add the steps, then cancel every species on both sides (catalysts and intermediates) to get the overall reaction."}]},
  {id:"cpt-pe1-48b",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"4E",skill:"SIRS 1",from:["pe1-cp:48#2"],
    q:"Adding the steps of a cerium–thallium mechanism gives 2Ce⁴⁺ + Tl⁺ → 2Ce³⁺ + Tl³⁺. What total ionic charge should each side carry?",
    choices:["+9","+5","+8","+6"],ans:0,
    exp:"Atoms: 2 Ce and 1 Tl on each side ✓. Charge: left 2(+4) + (+1) = **+9**; right 2(+3) + (+3) = **+9** ✓, so the overall equation balances. +5 ignores the coefficient on Ce⁴⁺, +8 counts only the cerium on the left, and +6 counts only the cerium on the right.",
    how:{ask:"Multiply each ion's charge by its coefficient and add, on both sides.",
      know:"• After summing steps, check the overall equation: **the same atoms of each element and the same total charge on both sides**.\n• Total charge = Σ (coefficient × ion charge).\n• Electrons lost = electrons gained.",
      steps:[{text:"Count the atoms first.",hl:"2Ce⁴⁺ + Tl⁺ → 2Ce³⁺ + Tl³⁺",calc:["Ce: 2 left, 2 right ✓","Tl: 1 left, 1 right ✓"]},
        {text:"Add the charges, weighting each ion by its coefficient.",calc:["left: 2(+4) + (+1) = 8 + 1 = **+9**","right: 2(+3) + (+3) = 6 + 3 = **+9** ✓"]},
        {text:"Electron check: the two Ce⁴⁺ gain 2 e⁻ in total and Tl⁺ loses 2 e⁻, so the transfer balances too.",calc:["Ce: +4 → +3, × 2 = 2 e⁻ gained","Tl: +1 → +3 = 2 e⁻ lost"]},
        {text:"Each slip misses part of the sum: +5 drops the coefficient (4 + 1); +8 counts only 2Ce⁴⁺; +6 counts only 2Ce³⁺.",strike:["+5","+8","+6"]},
        {text:"Answer: +9."}],
      trap:"+5 adds the charges as written without the coefficient on Ce⁴⁺; each charge must be weighted by how many of that ion there are."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Adding the steps",note:"the overall equation"},{t:"2Ce⁴⁺ + Tl⁺",note:"left side"},{t:"2Ce³⁺ + Tl³⁺",note:"right side"},{t:"total ionic charge",note:"Σ coefficient × charge"}]},
      {text:"**Two checks on every overall equation:** the atoms of each element match, and the total charge matches."},
      {text:"**Total charge** on a side = each ion's charge times its coefficient, added up.",calc:["2Ce⁴⁺ → 2 × (+4) = +8"]},
      {text:"**Rule to reuse:** after summing a mechanism, confirm that atoms and total charge (coefficient × charge) balance on both sides."}]},
  {id:"cpt-pe1-48c",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"4E",skill:"SIRS 1",from:["pe1-cp:48#3"],
    q:"Iron ions speed up the oxidation of iodide by persulfate: S₂O₈²⁻ + 2Fe²⁺ → 2SO₄²⁻ + 2Fe³⁺, then 2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂. Which species is the catalyst?",
    choices:["Fe²⁺","Fe³⁺","I⁻","SO₄²⁻"],ans:0,
    exp:"**Fe²⁺ is used in the first step and regenerated in the second**, so it is the catalyst: present at the start and given back at the end. **Fe³⁺ is made in the first step and used up in the second**: an intermediate. I⁻ is a reactant and SO₄²⁻ a product; neither cancels. Overall: S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂.",
    how:{ask:"For each iron ion, is it consumed first and returned later, or made first and consumed later?",
      know:"• **Catalyst**: consumed in an early step, **regenerated** later; it is present before the reaction starts.\n• **Intermediate**: **produced** in an early step, consumed later; it is never added at the start.\n• Both cancel from the overall equation; reactants and products do not.",
      steps:[{text:"Track Fe²⁺: a reactant in step one, a product in step two.",hl:"S₂O₈²⁻ + 2Fe²⁺ → 2SO₄²⁻ + 2Fe³⁺",calc:["step one: 2Fe²⁺ used","step two: 2Fe²⁺ made → **regenerated** → catalyst"]},
        {text:"Track Fe³⁺: made in step one, used up in step two, so it is an intermediate.",hl:"2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂",strike:["Fe³⁺"]},
        {text:"I⁻ is only consumed and SO₄²⁻ only produced: a reactant and a product, which stay in the overall equation.",calc:["overall: S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂"],strike:["I⁻","SO₄²⁻"]},
        {text:"Answer: Fe²⁺."}],
      trap:"Fe³⁺ also cancels from the overall equation, but it is made first and used later: that is an intermediate. A catalyst enters first as a reactant and is given back."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Iron ions speed up",note:"the catalyst is an iron ion"},{t:"S₂O₈²⁻ + 2Fe²⁺",note:"step one reactants"},{t:"2Fe²⁺ + I₂",note:"step two products"}]},
      {text:"**Catalyst: in, then out.** It enters an early step as a reactant and leaves a later step as a product, unchanged overall."},
      {text:"**Intermediate: out, then in.** It is made in an early step and used up in a later one.",calc:["catalyst: reactant (step one) → product (step two)","intermediate: product (step one) → reactant (step two)"]},
      {text:"**Rule to reuse:** a catalyst is used and then regenerated; an intermediate is made and then used up. Both cancel from the overall equation."}]},
  // ── Practice Exam 1 · Chem/Phys, general chemistry: Q49, 50, 51, 53, 54, 55, 57, 58 ──
  // pe1-cp:49 (what a catalytic converter does)
  {id:"cpt-pe1-49a",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 2",from:["pe1-cp:49#1"],
    q:"Hot exhaust gases flow over a ceramic honeycomb coated with solid rhodium and palladium in a car's catalytic converter. What kind of catalyst are these metals?",
    choices:["Heterogeneous","Homogeneous","Enzymatic","Autocatalytic"],ans:0,
    exp:"The metals are **solids** and the exhaust is a **gas**: catalyst and reactants are in **different phases**, so this is **heterogeneous** catalysis. The gases adsorb on the metal surface, react there and leave; the metal is not used up.",
    how:{ask:"Compare the phase of the catalyst with the phase of the reactants.",
      know:"• **Heterogeneous catalyst**: a different phase from the reactants (usually a solid surface with gases or liquids).\n• **Homogeneous catalyst**: the same phase as the reactants (e.g. dissolved in the same solution).\n• A catalyst is regenerated, not consumed.",
      steps:[{text:"Note the phase of each partner.",hl:"solid rhodium and palladium",calc:["catalyst: solid metals","reactants: exhaust gases"]},
        {text:"Solid vs gas = different phases, so the catalysis is heterogeneous; it is not homogeneous, which needs one shared phase.",calc:["solid ≠ gas → heterogeneous"],strike:["Homogeneous"]},
        {text:"Enzymes are protein catalysts in living cells, not metal coatings.",strike:["Enzymatic"]},
        {text:"Autocatalysis means a product speeds up its own formation; the metals are not products of the exhaust reactions.",strike:["Autocatalytic"]},
        {text:"Answer: heterogeneous."}],
      trap:"Calling a catalyst homogeneous because it is \"one material\": the test is whether it shares the reactants' phase."},
    teach:[{text:"First, **find the phases**.",marks:[{t:"Hot exhaust gases",note:"reactants: gas"},{t:"solid rhodium and palladium",note:"catalyst: solid"}]},
      {text:"**Homo = same, hetero = different.** The label compares the catalyst's phase with the reactants' phase.",calc:["same phase → homogeneous","different phase → heterogeneous"]},
      {text:"**How a solid catalyst works:** gas molecules stick to the metal surface, react there, then leave the surface free for more."},
      {text:"**Rule to reuse:** a solid catalyst acting on gases (a catalytic converter) is a heterogeneous catalyst."}]},
  {id:"cpt-pe1-49b",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"5E",skill:"SIRS 2",from:["pe1-cp:49#2"],
    q:"A catalytic converter treats exhaust containing carbon monoxide and unburned propane. Into which products does it turn both of these pollutants?",
    choices:["CO₂ and H₂O","CO and H₂","CH₃OH and H₂","C and H₂O"],ans:0,
    exp:"The converter **oxidizes** with O₂: carbon monoxide goes to **CO₂** (carbon +2 → +4), and a hydrocarbon such as propane burns completely to **CO₂ and H₂O**. Soot, CO, methanol or H₂ would be incomplete or reductive products.",
    how:{ask:"What do CO and a hydrocarbon become when fully oxidized by O₂ over the catalyst?",
      know:"• The converter's oxidation job: **CO → CO₂** and **hydrocarbons → CO₂ + H₂O**.\n• Oxidation of carbon raises its oxidation number; full oxidation of carbon ends at +4 (CO₂).",
      steps:[{text:"Note the two pollutants.",hl:"carbon monoxide and unburned propane",calc:["CO and C₃H₈"]},
        {text:"Oxidize each with O₂ and balance.",calc:["2CO + O₂ → 2CO₂   (C: +2 → +4)","C₃H₈ + 5O₂ → 3CO₂ + 4H₂O"]},
        {text:"CO and H₂ or soot plus water are less oxidized than what went in, the opposite of the converter's job.",strike:["CO and H₂","C and H₂O"]},
        {text:"Methanol plus H₂ is a partial, not complete, oxidation and is not what leaves the tailpipe.",strike:["CH₃OH and H₂"]},
        {text:"Answer: CO₂ and H₂O."}],
      trap:"Forgetting the hydrogen in a hydrocarbon: complete oxidation gives water as well as carbon dioxide."},
    teach:[{text:"First, **find the pollutants**.",marks:[{t:"carbon monoxide",note:"CO, C = +2"},{t:"unburned propane",note:"hydrocarbon C₃H₈"}]},
      {text:"**Oxidation side of the converter:** O₂ in the exhaust finishes burning anything carbon-based.",calc:["CO → CO₂","CₓHᵧ → CO₂ + H₂O"]},
      {text:"**Check by oxidation number:** carbon in CO is +2 and in CO₂ is +4, so carbon loses electrons: oxidation."},
      {text:"**Rule to reuse:** a catalytic converter oxidizes CO to CO₂ and unburned hydrocarbons to CO₂ and H₂O."}]},
  {id:"cpt-pe1-49c",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"5E",skill:"SIRS 2",from:["pe1-cp:49#3"],
    q:"To meet emission limits, a catalytic converter also removes nitric oxide (NO) from engine exhaust. What happens to the nitrogen atoms?",
    choices:["Reduced to N₂","Oxidized to N₂","Oxidized to NO₂","Oxidized to N₂O₅"],ans:0,
    exp:"Nitrogen in NO has oxidation number **+2**; in N₂ it is **0**. Its oxidation number falls, so nitrogen gains electrons: NO is **reduced to harmless N₂**. Forming NO₂ (+4) or N₂O₅ (+5) would be oxidation and would still pollute.",
    how:{ask:"Find nitrogen's oxidation number before and after, and decide whether it rose or fell.",
      know:"• **Oxidation number of N in NOₓ:** O = −2, so N in NO = +2, in NO₂ = +4.\n• Element (N₂) = 0.\n• Oxidation number down = **reduction** (gain of e⁻); up = oxidation.\n• The converter's reduction job: **NOₓ → N₂**.",
      steps:[{text:"Assign nitrogen's oxidation number in the pollutant.",hl:"nitric oxide (NO)",calc:["N + (−2) = 0 → N = +2"]},
        {text:"The converter turns it into nitrogen gas.",calc:["2NO → N₂ + O₂","N: +2 → 0 (decrease) → reduced"]},
        {text:"Going to N₂ lowers the number, so calling it oxidation is wrong.",strike:["Oxidized to N₂"]},
        {text:"NO₂ (+4) and N₂O₅ (+5) are higher oxides, still pollutants, and not what the converter makes.",calc:["NO₂: N = +4","N₂O₅: 2N = +10 → N = +5"],strike:["Oxidized to NO₂","Oxidized to N₂O₅"]},
        {text:"Answer: reduced to N₂."}],
      trap:"Assuming everything in a converter is oxidized: CO and hydrocarbons are, but nitrogen oxides are reduced."},
    teach:[{text:"First, **find the species**.",marks:[{t:"nitric oxide (NO)",note:"N = +2"},{t:"nitrogen atoms",note:"track their oxidation number"}]},
      {text:"**Oxidation numbers:** O is −2, so in NO nitrogen is +2; in N₂ it is 0.",calc:["NO: N = +2","N₂: N = 0"]},
      {text:"**Down = reduction.** Gaining electrons lowers the oxidation number.",calc:["+2 → 0: reduction"]},
      {text:"**Rule to reuse:** a catalytic converter reduces nitrogen oxides (NOₓ) to N₂ while it oxidizes CO and hydrocarbons."}]},

  // pe1-cp:50 (a homogeneous catalyst that cannot be separated)
  {id:"cpt-pe1-50a",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:50#1"],
    q:"A liquid ester is made using dissolved sulfuric acid as the catalyst, and the acid cannot be removed from the liquid afterward. What is the main consequence?",
    choices:["A contaminated product","More product at equilibrium","Less product at equilibrium","A consumed catalyst"],ans:0,
    exp:"Dissolved acid in a liquid reaction is a **homogeneous** catalyst: it shares one **liquid phase** with the ester. If it can't be removed, the acid **stays mixed into the product**. A catalyst speeds both directions equally, so it **does not change the equilibrium amount** of product, and it is regenerated, not used up.",
    how:{ask:"Where does a same-phase catalyst end up, and does a catalyst change how much product forms at equilibrium?",
      know:"• **Homogeneous catalyst** = same phase as reactants and products, so it is hard to separate.\n• A catalyst lowers Ea for **both** forward and reverse reactions: it reaches equilibrium faster but **K and the equilibrium amounts don't change**.\n• A catalyst is regenerated at the end of each cycle.",
      steps:[{text:"Classify the catalyst by phase.",hl:"dissolved sulfuric acid",calc:["catalyst: dissolved (liquid phase)","product: liquid ester → same phase → homogeneous"]},
        {text:"Not separable + same phase → the acid remains in the ester: contamination.",hl:"cannot be removed"},
        {text:"A catalyst speeds forward and reverse equally, so the equilibrium yield is neither raised nor lowered.",calc:["K unchanged → equilibrium amounts unchanged"],strike:["More product at equilibrium","Less product at equilibrium"]},
        {text:"Catalysts are regenerated, so the acid is not used up.",strike:["A consumed catalyst"]},
        {text:"Answer: a contaminated product."}],
      trap:"Thinking a catalyst raises the yield: it only gets the mixture to the same equilibrium sooner."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"dissolved sulfuric acid",note:"same phase: homogeneous"},{t:"cannot be removed",note:"it stays in the mixture"}]},
      {text:"**Same phase means mixed in.** A dissolved catalyst ends up in the same liquid as the product, so it must be separated or it contaminates it."},
      {text:"**Catalysts change speed, not position.** With or without a catalyst, the product level reaches the same plateau; the catalyst only gets there sooner.",
        chart:{type:"line",caption:"Same equilibrium, reached sooner",x:{label:"Time (min)",min:0,max:60,step:10},y:{label:"Ester formed (% of maximum)",min:0,max:100,step:20},
          series:[{name:"With catalyst",marker:"circle",line:"smooth",points:[[0,0],[5,45],[10,65],[20,67],[40,67],[60,67]]},{name:"No catalyst",marker:"circle",line:"smooth",points:[[0,0],[10,20],[20,38],[30,52],[40,61],[60,67]]}]}},
      {text:"**Rule to reuse:** an inseparable homogeneous catalyst contaminates the product; a catalyst never shifts the equilibrium."}]},

  // pe1-cp:51 (grinding a solid catalyst)
  {id:"cpt-pe1-51a",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:51#1"],
    q:"Equal masses of manganese dioxide catalyst, one as a single pellet and one as fine powder, are added to identical hydrogen peroxide solutions. Why does the powder release O₂ faster?",
    choices:["More exposed surface","Greater catalyst mass","Higher activation energy","Larger equilibrium constant"],ans:0,
    exp:"A solid catalyst works only at its **surface**, where H₂O₂ molecules meet it. Powder exposes far **more surface area** for the same mass, so more reaction sites act at once and the **rate rises**. The mass is equal, a catalyst lowers (not raises) Ea, and catalysts don't change K.",
    how:{ask:"What differs between the pellet and the powder, given that their masses match?",
      know:"• A **heterogeneous catalyst reacts at its surface**.\n• Breaking a solid into small pieces greatly **raises surface area** without changing mass.\n• More surface → more active sites → **faster rate**.",
      steps:[{text:"Note what is the same and what differs.",hl:"Equal masses of manganese dioxide catalyst",calc:["mass: same","form: pellet vs fine powder"]},
        {text:"The masses are equal, so mass can't explain the difference.",strike:["Greater catalyst mass"]},
        {text:"Powder exposes more surface where H₂O₂ meets the catalyst, so more molecules react per second.",calc:["surface area ↑ → active sites ↑ → rate ↑"]},
        {text:"A catalyst lowers Ea, and a higher Ea would slow the reaction; neither form changes K.",strike:["Higher activation energy","Larger equilibrium constant"]},
        {text:"Answer: more exposed surface."}],
      trap:"Thinking grinding adds catalyst: the amount is unchanged; only the surface the reactants can reach grows."},
    teach:[{text:"First, **find what was changed**.",marks:[{t:"Equal masses",note:"mass held fixed"},{t:"fine powder",note:"more surface"},{t:"release O₂ faster",note:"rate"}]},
      {text:"**Surface catalysis:** reactant molecules must touch the solid to react, so only surface atoms count."},
      {text:"**Smaller pieces, more surface.** Cutting a solid exposes new faces that were inside before.",calc:["particle size ↓ → surface area ↑ → rate ↑"]},
      {text:"**Rule to reuse:** grinding a solid catalyst speeds the reaction because it exposes more surface area."}]},
  {id:"cpt-pe1-51b",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:51#2"],
    q:"A nickel catalyst cube weighing 3.0 grams is cut into 27 identical smaller cubes, and no material is lost. What is the total mass of the small cubes?",
    choices:["3.0 g","9.0 g","81 g","0.11 g"],ans:0,
    exp:"Cutting changes the **shape and surface area**, not the amount of nickel. With no material lost, **mass is conserved**: the 27 cubes together weigh **3.0 g** (each one 3.0 ÷ 27 ≈ 0.11 g).",
    how:{ask:"Does cutting a solid into pieces change how much matter there is?",
      know:"• **Conservation of mass**: dividing a solid changes its shape and surface area, not its mass.\n• Each piece's mass = total ÷ number of pieces.",
      steps:[{text:"Note the starting mass and the number of pieces.",hl:"weighing 3.0 grams",calc:["total mass = 3.0 g","pieces = 27"]},
        {text:"No material lost, so the total is conserved.",hl:"no material is lost",calc:["total after = 3.0 g"]},
        {text:"9.0 g multiplies by the edge ratio (3), and 81 g by 27; cutting doesn't create matter.",calc:["3.0 × 3 = 9.0","3.0 × 27 = 81"],strike:["9.0 g","81 g"]},
        {text:"0.11 g is the mass of one small cube, not of all 27 together.",calc:["3.0 ÷ 27 = 0.11 g each"],strike:["0.11 g"]},
        {text:"Answer: 3.0 g."}],
      trap:"Mixing up quantities that grow with grinding (surface area, number of pieces) with mass, which stays fixed."},
    teach:[{text:"First, **find the givens**.",marks:[{t:"3.0 grams",note:"starting mass"},{t:"27 identical smaller cubes",note:"pieces"},{t:"no material is lost",note:"mass conserved"}]},
      {text:"**What grinding changes:** surface area and number of particles go up."},
      {text:"**What it doesn't:** the total mass.",calc:["total mass after = total mass before"]},
      {text:"**Rule to reuse:** grinding or cutting a catalyst raises its surface area but leaves its mass unchanged."}]},
  {id:"cpt-pe1-51c",s:"Thermodynamics & Kinetics",disc:"gen_chem",aamc:"5E",skill:"SIRS 3",from:["pe1-cp:51#3"],
    q:"A solid catalyst cube 2.4 cm on each edge is cut into identical cubes 0.60 cm on each edge. By what factor does the total surface area increase?",
    choices:["4","16","64","0.25"],ans:0,
    exp:"Big cube: 6(2.4)² = **34.56 cm²**. Number of small cubes = (2.4 ÷ 0.60)³ = 64, each 6(0.60)² = 2.16 cm², total **138.24 cm²**. 138.24 ÷ 34.56 = **4**, which equals the **edge ratio** 2.4 ÷ 0.60.",
    how:{ask:"Compare the total surface area of all the small cubes with that of the big cube.",
      know:"• Surface area of a cube = **6a²** (a = edge).\n• Number of small cubes = **(a_big ÷ a_small)³**.\n• Shortcut: total area grows by the **edge ratio a_big ÷ a_small**.",
      steps:[{text:"Note the two edge lengths.",hl:"2.4 cm on each edge",calc:["a_big = 2.4 cm","a_small = 0.60 cm"]},
        {text:"Area of the big cube.",calc:["A = 6 × (2.4 cm)²","A = 6 × 5.76 cm² = 34.56 cm²"]},
        {text:"Number of small cubes and their total area.",calc:["n = (2.4 ÷ 0.60)³ = 4³ = 64","each: 6 × (0.60 cm)² = 6 × 0.36 = 2.16 cm²","total: 64 × 2.16 = 138.24 cm²"]},
        {text:"Ratio of areas.",calc:["138.24 ÷ 34.56 = **4**  (= 2.4 ÷ 0.60)"]},
        {text:"16 compares one small face with one big face and ignores the number of cubes; 64 is the number of cubes; 0.25 inverts the ratio.",calc:["(2.4 ÷ 0.60)² = 16","4³ = 64","0.60 ÷ 2.4 = 0.25"],strike:["16","64","0.25"]},
        {text:"Answer: 4."}],
      trap:"Using the volume ratio (number of pieces, 64) or the area ratio of one face (16) instead of the edge ratio."},
    teach:[{text:"First, **find the edges**.",marks:[{t:"2.4 cm",note:"big edge"},{t:"0.60 cm",note:"small edge"},{t:"total surface area",note:"all pieces together"}]},
      {text:"**Two effects:** each small cube has less area, but there are many more of them.",calc:["area per cube ∝ a²","number of cubes ∝ 1/a³"]},
      {text:"**Combine them:** a² × (1/a³) = 1/a, so the total area scales with 1/edge.",calc:["factor = a_big ÷ a_small"]},
      {text:"**Rule to reuse:** cutting a cube into smaller cubes multiplies the total surface area by the ratio of the edge lengths."}]},

  // pe1-cp:53 (will a metal release H₂ from acid?)
  {id:"cpt-pe1-53a",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:53#1"],
    q:"Standard reduction potentials: Mg²⁺/Mg, −2.37 V; Ag⁺/Ag, +0.80 V. Strips of magnesium and silver are each dropped into 1 M HCl. Which produces H₂ gas?",
    choices:["Magnesium only","Silver only","Both magnesium and silver","Neither metal"],ans:0,
    exp:"H⁺/H₂ is the **zero reference**. Magnesium's E° is **negative** (−2.37 V), so Mg is more easily oxidized than H₂: Mg → Mg²⁺ while **H⁺ gains electrons and becomes H₂**. Silver's E° is **positive**, so Ag holds its electrons and does not reduce H⁺; no gas forms on it.",
    how:{ask:"For each metal, is it easier to oxidize than H₂ (E° below that of H⁺/H₂)?",
      know:"• Reference: **2H⁺ + 2e⁻ → H₂, E° = 0 V**.\n• Metal with **E° < 0** is oxidized by H⁺: M → Mⁿ⁺ and H⁺ → H₂.\n• Metal with **E° > 0** does not react with H⁺.\n• Check: E°cell = E°(H⁺/H₂) − E°(metal) must be positive.",
      steps:[{text:"Note both potentials.",hl:"Mg²⁺/Mg, −2.37 V",calc:["Mg: −2.37 V","Ag: +0.80 V","H⁺/H₂: 0 V"]},
        {text:"Magnesium: H⁺ is the cathode, Mg the anode.",calc:["E°cell = 0 − (−2.37) = +2.37 V > 0 → spontaneous","Mg + 2H⁺ → Mg²⁺ + H₂"]},
        {text:"Silver: the same set-up gives a negative E°cell, so silver does not release H₂.",calc:["E°cell = 0 − (+0.80) = −0.80 V < 0 → no reaction"],strike:["Silver only","Both magnesium and silver"]},
        {text:"Magnesium does react, so it is not the case that neither metal gives gas.",strike:["Neither metal"]},
        {text:"Answer: magnesium only."}],
      trap:"Thinking any metal dissolves in acid: only metals with E° below 0 V (more active than H₂) reduce H⁺ to H₂."},
    teach:[{text:"First, **find the potentials**.",marks:[{t:"−2.37 V",note:"Mg: below 0"},{t:"+0.80 V",note:"Ag: above 0"},{t:"1 M HCl",note:"source of H⁺"},{t:"H₂ gas",note:"H⁺ must be reduced"}]},
      {text:"**H⁺/H₂ sits at 0 V.** A metal below it gives electrons to H⁺; a metal above it doesn't.",calc:["E°(metal) < 0 → metal oxidized, H⁺ → H₂"]},
      {text:"**Confirm with E°cell** (H⁺ as cathode, metal as anode): positive means it happens.",calc:["E°cell = 0 − E°(metal)"]},
      {text:"**Rule to reuse:** a metal more easily oxidized than H₂ (E° < 0) is oxidized by acid and H⁺ is reduced to H₂ gas."}]},

  // pe1-cp:54 (balanced metal-displacement equation)
  {id:"cpt-pe1-54a",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:54#1"],
    q:"Standard reduction potentials: Fe²⁺/Fe, −0.44 V; Ag⁺/Ag, +0.80 V. An iron nail is placed in silver nitrate solution. Which species is oxidized?",
    choices:["Iron metal","Silver metal","Iron(II) ions","Silver ions"],ans:0,
    exp:"The half-reaction with the **lower reduction potential runs backward** as oxidation. Iron's E° (−0.44 V) is lower than silver's (+0.80 V), so **Fe → Fe²⁺ + 2e⁻**, and Ag⁺ is reduced to silver metal.",
    how:{ask:"Which half-reaction has the lower E°, and so runs as an oxidation?",
      know:"• **Higher E°** → reduced (cathode). **Lower E°** → oxidized (anode).\n• Only the reduced form of a couple (the metal) can be oxidized; the ion is already oxidized.",
      steps:[{text:"Compare the two potentials.",hl:"Fe²⁺/Fe, −0.44 V",calc:["Fe²⁺/Fe: −0.44 V (lower)","Ag⁺/Ag: +0.80 V (higher)"]},
        {text:"Lower E° is oxidized: iron metal gives up electrons.",calc:["Fe → Fe²⁺ + 2e⁻"]},
        {text:"Silver ions are reduced, not oxidized; silver metal is the product they form.",calc:["Ag⁺ + e⁻ → Ag"],strike:["Silver ions","Silver metal"]},
        {text:"Fe²⁺ is the product of the oxidation, not the species being oxidized.",strike:["Iron(II) ions"]},
        {text:"Answer: iron metal."}],
      trap:"Picking the ion of the more negative couple: Fe²⁺ is what iron becomes, not what gets oxidized."},
    teach:[{text:"First, **find the potentials**.",marks:[{t:"−0.44 V",note:"Fe: lower"},{t:"+0.80 V",note:"Ag: higher"},{t:"iron nail",note:"Fe metal"},{t:"silver nitrate",note:"Ag⁺ ions"}]},
      {text:"**Higher E° wins the electrons.** Ag⁺ has the higher E°, so it is reduced."},
      {text:"**The other one is oxidized.** Iron's half-reaction runs in reverse.",calc:["Fe → Fe²⁺ + 2e⁻","2Ag⁺ + 2e⁻ → 2Ag"]},
      {text:"**Rule to reuse:** of two half-reactions, the metal with the lower reduction potential is oxidized."}]},
  {id:"cpt-pe1-54b",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4E",skill:"SIRS 2",from:["pe1-cp:54#2"],
    q:"Chromium metal is dipped in a nickel(II) solution. Standard reduction potentials: Cr³⁺/Cr, −0.74 V; Ni²⁺/Ni, −0.25 V. Which balanced equation describes the reaction?",
    choices:["2Cr + 3Ni²⁺ → 2Cr³⁺ + 3Ni","3Cr + 2Ni²⁺ → 3Cr³⁺ + 2Ni","Cr + Ni²⁺ → Cr³⁺ + Ni","2Cr³⁺ + 3Ni → 2Cr + 3Ni²⁺"],ans:0,
    exp:"Cr has the lower E°, so **Cr is oxidized** (Cr → Cr³⁺ + 3e⁻) and **Ni²⁺ is reduced** (Ni²⁺ + 2e⁻ → Ni). Electrons lost must equal electrons gained: **LCM of 3 and 2 is 6**, so 2 Cr and 3 Ni²⁺. Charge check: three Ni²⁺ ions carry +6, and so do two Cr³⁺ ions.",
    how:{ask:"Write both half-reactions, then multiply them so the electrons cancel.",
      know:"• Lower E° → oxidized; higher E° → reduced.\n• **Balance electrons**: multiply each half-reaction so e⁻ lost = e⁻ gained (use the LCM).\n• A balanced ionic equation balances **atoms and charge**.",
      steps:[{text:"Pick the direction from the potentials.",hl:"Cr³⁺/Cr, −0.74 V",calc:["Cr (−0.74 V) lower → oxidized","Ni (−0.25 V) higher → reduced"]},
        {text:"Write the half-reactions.",calc:["Cr → Cr³⁺ + 3e⁻","Ni²⁺ + 2e⁻ → Ni"]},
        {text:"LCM of 3 and 2 is 6: double the chromium half, triple the nickel half.",calc:["2Cr → 2Cr³⁺ + 6e⁻","3Ni²⁺ + 6e⁻ → 3Ni","2Cr + 3Ni²⁺ → 2Cr³⁺ + 3Ni"]},
        {text:"Charge check on the other forms: the swapped coefficients and the 1:1 equation leave the charges unequal.",calc:["3Cr + 2Ni²⁺: left +4, right +9 ✗","Cr + Ni²⁺: left +2, right +3 ✗","2Cr + 3Ni²⁺: left +6, right +6 ✓"],strike:["3Cr + 2Ni²⁺ → 3Cr³⁺ + 2Ni","Cr + Ni²⁺ → Cr³⁺ + Ni"]},
        {text:"The reversed equation would oxidize Ni and reduce Cr³⁺, giving a negative E°cell.",calc:["E°cell = −0.74 − (−0.25) = −0.49 V ✗"],strike:["2Cr³⁺ + 3Ni → 2Cr + 3Ni²⁺"]},
        {text:"Answer: 2Cr + 3Ni²⁺ → 2Cr³⁺ + 3Ni."}],
      trap:"Swapping the coefficients (3Cr, 2Ni²⁺): the coefficient of Cr comes from the 2 electrons each Ni²⁺ takes, and the coefficient of Ni²⁺ from the 3 each Cr gives."},
    teach:[{text:"First, **find the half-reactions**.",marks:[{t:"Cr³⁺/Cr, −0.74 V",note:"lower: Cr oxidized, 3 e⁻"},{t:"Ni²⁺/Ni, −0.25 V",note:"higher: Ni²⁺ reduced, 2 e⁻"}]},
      {text:"**Electrons lost = electrons gained.** Cr gives 3 each; Ni²⁺ takes 2 each.",calc:["LCM(3, 2) = 6 e⁻","6 ÷ 3 = 2 Cr","6 ÷ 2 = 3 Ni²⁺"]},
      {text:"**Check the charge.** Both sides must carry the same total charge.",calc:["3 × (+2) = +6","2 × (+3) = +6 ✓"]},
      {text:"**Rule to reuse:** balance a redox equation by multiplying the half-reactions so the electrons lost equal the electrons gained, then check the charge."}]},

  // pe1-cp:55 (E°cell and spontaneity)
  {id:"cpt-pe1-55a",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:55#1"],
    q:"In a galvanic cell, copper is the cathode (E° = +0.34 V) and iron is the anode (E° = −0.44 V). What is E°cell?",
    choices:["+0.78 V","−0.10 V","+0.34 V","+0.44 V"],ans:0,
    exp:"Subtract the anode from the cathode, **E°cell = E°red(cathode) − E°red(anode)**, using both reduction potentials: +0.34 − (−0.44) = **+0.78 V**. Adding the two values gives −0.10 V, and either electrode alone (+0.34 V or +0.44 V) is only half the cell.",
    how:{ask:"Subtract the anode's reduction potential from the cathode's.",
      know:"• **E°cell = E°cathode − E°anode** (both as reduction potentials from the table).\n• Don't flip a sign and then also subtract; do one or the other.",
      steps:[{text:"Note which electrode is which.",hl:"copper is the cathode (E° = +0.34 V)",calc:["E°cathode = +0.34 V","E°anode = −0.44 V"]},
        {text:"Apply the formula.",calc:["E°cell = E°cathode − E°anode","E°cell = +0.34 − (−0.44)","E°cell = +0.34 + 0.44 = **+0.78 V**"]},
        {text:"Adding the two tabulated potentials skips the anode's sign change.",calc:["+0.34 + (−0.44) = −0.10 V ✗"],strike:["−0.10 V"]},
        {text:"+0.34 V is the cathode alone, and +0.44 V is only the anode's oxidation potential; the cell needs both.",calc:["oxidation of Fe: +0.44 V","reduction of Cu²⁺: +0.34 V","sum = +0.78 V"],strike:["+0.34 V","+0.44 V"]},
        {text:"Answer: +0.78 V."}],
      trap:"Adding the two tabulated reduction potentials: that skips the sign change for the anode's oxidation."},
    teach:[{text:"First, **find the roles and values**.",marks:[{t:"copper is the cathode",note:"reduction"},{t:"+0.34 V",note:"E°cathode"},{t:"iron is the anode",note:"oxidation"},{t:"−0.44 V",note:"E°anode"}]},
      {text:"**The formula** uses both reduction potentials as listed.",calc:["E°cell = E°cathode − E°anode"]},
      {text:"**Watch the double negative.** Subtracting a negative number adds it.",calc:["+0.34 − (−0.44) = +0.34 + 0.44"]},
      {text:"**Rule to reuse:** E°cell = E°cathode − E°anode, with both values taken as reduction potentials."}]},
  {id:"cpt-pe1-55b",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:55#2"],
    q:"Standard reduction potentials: Ag⁺/Ag, +0.80 V; Pb²⁺/Pb, −0.13 V. In a galvanic cell made from these two half-cells, which electrode is the cathode?",
    choices:["Silver","Lead","Neither electrode","The salt bridge"],ans:0,
    exp:"The **cathode is where reduction happens**, and the couple with the **higher reduction potential** is reduced: Ag⁺/Ag (+0.80 V) beats Pb²⁺/Pb (−0.13 V). So **silver is the cathode**, lead the anode, and E°cell = 0.80 − (−0.13) = +0.93 V.",
    how:{ask:"Which half-cell has the higher reduction potential, and so is reduced?",
      know:"• **Cathode = reduction**; anode = oxidation.\n• In a galvanic cell the **higher E°** half-cell is the cathode.\n• The salt bridge only carries ions; it is not an electrode.",
      steps:[{text:"Compare the two reduction potentials.",hl:"Ag⁺/Ag, +0.80 V",calc:["Ag: +0.80 V (higher)","Pb: −0.13 V (lower)"]},
        {text:"Higher E° → reduced → cathode; lead is oxidized at the anode.",calc:["Ag⁺ + e⁻ → Ag (cathode)","Pb → Pb²⁺ + 2e⁻ (anode)"],strike:["Lead"]},
        {text:"Check: this choice gives a positive E°cell, as a galvanic cell must.",calc:["E°cell = 0.80 − (−0.13) = +0.93 V"]},
        {text:"A galvanic cell always has one cathode, and the salt bridge only moves ions between the half-cells.",strike:["Neither electrode","The salt bridge"]},
        {text:"Answer: silver."}],
      trap:"Choosing the electrode with the larger number of electrons transferred, or the more negative value: only the higher reduction potential decides the cathode."},
    teach:[{text:"First, **find the potentials**.",marks:[{t:"+0.80 V",note:"Ag: higher"},{t:"−0.13 V",note:"Pb: lower"},{t:"cathode",note:"site of reduction"}]},
      {text:"**Red Cat:** reduction happens at the cathode."},
      {text:"**Higher E° is reduced.** The couple that wants electrons more takes them.",calc:["higher E° → cathode","lower E° → anode"]},
      {text:"**Rule to reuse:** in a galvanic cell, the cathode is the half-cell with the higher standard reduction potential."}]},
  {id:"cpt-pe1-55c",s:"Electrochemistry & Redox",disc:"gen_chem",aamc:"4C",skill:"SIRS 2",from:["pe1-cp:55#3"],
    q:"For the reaction Sn(s) + Fe²⁺(aq) → Sn²⁺(aq) + Fe(s), E°cell = −0.30 V. Under standard conditions, is the reaction spontaneous?",
    choices:["No; ΔG° is positive","Yes; ΔG° is negative","No; ΔG° is negative","Yes; ΔG° is positive"],ans:0,
    exp:"**ΔG° = −nFE°cell.** With E°cell negative, ΔG° = −(2)(96,485)(−0.30) ≈ **+58 kJ**, positive, so the reaction is **not spontaneous** as written (the reverse is). Positive E°cell ↔ negative ΔG° ↔ spontaneous.",
    how:{ask:"Use the sign of E°cell to get the sign of ΔG°.",
      know:"• **ΔG° = −nFE°cell** (F = 96,485 C/mol e⁻).\n• **E°cell > 0 → ΔG° < 0 → spontaneous**; E°cell < 0 → ΔG° > 0 → nonspontaneous.",
      steps:[{text:"Note the sign of E°cell and the electrons moved.",hl:"E°cell = −0.30 V",calc:["E°cell = −0.30 V","n = 2 (Sn → Sn²⁺)"]},
        {text:"Compute ΔG°.",calc:["ΔG° = −nFE°","ΔG° = −(2)(96,485 C/mol)(−0.30 V)","ΔG° = +57,891 J/mol ≈ **+58 kJ/mol**"]},
        {text:"ΔG° is positive, so any choice with ΔG° < 0 is wrong.",strike:["Yes; ΔG° is negative","No; ΔG° is negative"]},
        {text:"A positive ΔG° means nonspontaneous, not spontaneous.",strike:["Yes; ΔG° is positive"]},
        {text:"Answer: no; ΔG° is positive."}],
      trap:"Forgetting the minus sign in ΔG° = −nFE: a positive E°cell gives a negative ΔG°, and vice versa."},
    teach:[{text:"First, **find the sign**.",marks:[{t:"E°cell = −0.30 V",note:"negative"},{t:"spontaneous",note:"needs ΔG° < 0"}]},
      {text:"**Link voltage and free energy.**",calc:["ΔG° = −nFE°cell"]},
      {text:"**Opposite signs.** The minus sign makes ΔG° and E°cell always opposite in sign.",calc:["E° > 0 ↔ ΔG° < 0 ↔ spontaneous","E° < 0 ↔ ΔG° > 0 ↔ nonspontaneous"]},
      {text:"**Rule to reuse:** a positive E°cell means a spontaneous reaction (ΔG° < 0); a negative E°cell means nonspontaneous."}]},

  // pe1-cp:57 (common ion added to a saturated salt)
  {id:"cpt-pe1-57a",s:"Equilibrium",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:57#1"],
    q:"Solid sodium chloride is dissolved in a saturated silver chloride solution that sits over undissolved AgCl. Immediately afterward, how does the ion product Q compare with Ksp?",
    choices:["Above Ksp","Below Ksp","Equal to Ksp","Exactly zero"],ans:0,
    exp:"Before the addition the solution is saturated, so **Q = [Ag⁺][Cl⁻] = Ksp**. NaCl adds **Cl⁻, a common ion**, raising [Cl⁻] while [Ag⁺] is momentarily unchanged, so the product **Q now exceeds Ksp**.",
    how:{ask:"What was Q before the addition, and which factor in Q just grew?",
      know:"• **Q = [Ag⁺][Cl⁻]** at any moment; **Ksp** is its value at saturation.\n• Saturated: Q = Ksp. Adding a **common ion** raises one factor of Q.\n• Q > Ksp → precipitate forms; Q < Ksp → more dissolves.",
      steps:[{text:"Start from the saturated solution.",hl:"saturated silver chloride solution",calc:["AgCl(s) ⇌ Ag⁺ + Cl⁻","Q = [Ag⁺][Cl⁻] = Ksp = 1.8 × 10⁻¹⁰","[Ag⁺] = [Cl⁻] = √(1.8 × 10⁻¹⁰) = 1.3 × 10⁻⁵ M"]},
        {text:"NaCl adds Cl⁻. Suppose [Cl⁻] becomes 0.050 M.",hl:"Solid sodium chloride",calc:["Q = (1.3 × 10⁻⁵)(0.050)","Q = 6.7 × 10⁻⁷ > 1.8 × 10⁻¹⁰"]},
        {text:"Raising one factor can't leave Q equal to or below Ksp.",strike:["Below Ksp","Equal to Ksp"]},
        {text:"Ag⁺ is still present, so Q is not zero.",strike:["Exactly zero"]},
        {text:"Answer: Q is above Ksp."}],
      trap:"Thinking Q stays at Ksp because the solution was saturated: saturation describes the moment before the common ion arrived."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"sodium chloride",note:"adds Cl⁻, a common ion"},{t:"saturated",note:"Q = Ksp before"},{t:"Immediately afterward",note:"before any shift"}]},
      {text:"**Q has the same form as Ksp** but uses the concentrations right now.",calc:["Q = [Ag⁺][Cl⁻]"]},
      {text:"**One factor up → Q up.** From Q = Ksp, any extra common ion pushes Q above Ksp.",calc:["[Cl⁻] ↑ → Q ↑ → Q > Ksp"]},
      {text:"**Rule to reuse:** adding a common ion to a saturated solution raises Q above Ksp."}]},
  {id:"cpt-pe1-57b",s:"Equilibrium",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:57#2"],
    q:"Sodium sulfate, a very soluble salt, is stirred into a saturated calcium sulfate solution. What is observed as the system returns to equilibrium?",
    choices:["Solid CaSO₄ forms","More CaSO₄ dissolves","Solid Na₂SO₄ forms","Nothing visible happens"],ans:0,
    exp:"Na₂SO₄ adds **SO₄²⁻, a common ion**, so Q for CaSO₄ exceeds Ksp. By **Le Châtelier**, CaSO₄(s) ⇌ Ca²⁺ + SO₄²⁻ shifts **left**: Ca²⁺ and SO₄²⁻ combine and **solid CaSO₄ precipitates** until Q = Ksp again.",
    how:{ask:"Which way does the dissolution equilibrium shift when a product ion is added?",
      know:"• **CaSO₄(s) ⇌ Ca²⁺(aq) + SO₄²⁻(aq)**.\n• Adding a product (common ion) → Q > Ksp → **shift left** → the salt **precipitates**.\n• A very soluble salt stays dissolved.",
      steps:[{text:"Find the common ion.",hl:"Sodium sulfate",calc:["Na₂SO₄ → 2Na⁺ + SO₄²⁻","SO₄²⁻ is shared with CaSO₄"]},
        {text:"More product → Q > Ksp → shift left: Ca²⁺ and SO₄²⁻ leave solution as solid.",calc:["CaSO₄(s) ⇐ Ca²⁺ + SO₄²⁻"]},
        {text:"A left shift removes ions from solution, the opposite of dissolving more, and a solid appears.",strike:["More CaSO₄ dissolves","Nothing visible happens"]},
        {text:"Sodium sulfate is very soluble, so it doesn't come out of solution.",strike:["Solid Na₂SO₄ forms"]},
        {text:"Answer: solid CaSO₄ forms."}],
      trap:"Expecting the added salt itself to precipitate: it is the sparingly soluble salt that comes out."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"very soluble salt",note:"stays dissolved"},{t:"saturated calcium sulfate solution",note:"CaSO₄ at Ksp"}]},
      {text:"**Write the equilibrium** with the solid on the left.",calc:["CaSO₄(s) ⇌ Ca²⁺ + SO₄²⁻"]},
      {text:"**Le Châtelier:** adding a product shifts the equilibrium to the left, toward the solid.",calc:["[SO₄²⁻] ↑ → shift left → CaSO₄ precipitates"]},
      {text:"**Rule to reuse:** a common ion shifts a saturated salt's equilibrium left, so the sparingly soluble salt precipitates."}]},
  {id:"cpt-pe1-57c",s:"Equilibrium",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:57#3"],
    q:"Potassium bromide is added to a saturated silver bromide solution held at constant temperature. What happens to the Ksp of silver bromide?",
    choices:["It is unchanged","It increases","It decreases","It becomes zero"],ans:0,
    exp:"**Ksp is an equilibrium constant**, and it depends only on **temperature**. The common ion Br⁻ lowers the **molar solubility** of AgBr (some AgBr precipitates), but once equilibrium returns, [Ag⁺][Br⁻] equals the same Ksp.",
    how:{ask:"What can change an equilibrium constant, and did that change here?",
      know:"• **Ksp changes only with temperature.**\n• A common ion changes **Q** and the **solubility**, not Ksp.\n• After the shift, the new [Ag⁺][Br⁻] equals the same Ksp.",
      steps:[{text:"Note the condition held fixed.",hl:"constant temperature",calc:["T fixed → Ksp fixed"]},
        {text:"KBr adds Br⁻; AgBr precipitates until the ion product is back at Ksp.",calc:["Ksp(AgBr) ≈ 5.0 × 10⁻¹³","with [Br⁻] = 0.10 M: [Ag⁺] = 5.0 × 10⁻¹³ ÷ 0.10 = 5.0 × 10⁻¹² M","[Ag⁺][Br⁻] = 5.0 × 10⁻¹² × 0.10 = 5.0 × 10⁻¹³ = Ksp"]},
        {text:"Solubility falls, but the constant doesn't rise or fall with it.",strike:["It increases","It decreases"]},
        {text:"Ksp is a fixed positive constant for AgBr at a given temperature; it can't become zero.",strike:["It becomes zero"]},
        {text:"Answer: it is unchanged."}],
      trap:"Mixing up solubility (which falls with a common ion) with Ksp (which stays the same at constant temperature)."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Potassium bromide",note:"adds Br⁻, a common ion"},{t:"constant temperature",note:"Ksp fixed"}]},
      {text:"**Two different quantities:** solubility is how much dissolves; Ksp is the constant that the ion product returns to.",calc:["common ion → solubility ↓","common ion → Ksp unchanged"]},
      {text:"**Only temperature changes K.** Concentrations change Q, not K."},
      {text:"**Rule to reuse:** adding a common ion lowers a salt's solubility, but Ksp itself doesn't change unless temperature does."}]},

  // pe1-cp:58 (volume of solution holding a given amount)
  {id:"cpt-pe1-58a",s:"Stoichiometry & Solutions",disc:"gen_chem",aamc:"5A",skill:"SIRS 2",from:["pe1-cp:58#1"],
    q:"A recipe needs 2.34 g of sodium chloride (molar mass 58.5 g/mol), measured out from a 0.400 M NaCl stock. What volume of stock is required?",
    choices:["100 mL","16 mL","40 mL","5.85 L"],ans:0,
    exp:"First grams to moles: 2.34 g ÷ 58.5 g/mol = **0.0400 mol**. Then **V = n ÷ M** = 0.0400 mol ÷ 0.400 mol/L = 0.100 L = **100 mL**.",
    how:{ask:"Convert grams to moles, then divide moles by molarity to get litres, then convert to mL.",
      know:"• **n = mass ÷ molar mass**.\n• **M = n ÷ V**, so **V = n ÷ M** (V in litres).\n• 1 L = 1000 mL.",
      steps:[{text:"Note the mass, molar mass and molarity.",hl:"2.34 g of sodium chloride",calc:["m = 2.34 g","molar mass = 58.5 g/mol","M = 0.400 mol/L"]},
        {text:"Grams to moles.",calc:["n = 2.34 g ÷ 58.5 g/mol","n = 0.0400 mol"]},
        {text:"Volume from V = n ÷ M, then mL.",calc:["V = 0.0400 mol ÷ 0.400 mol/L","V = 0.100 L","V = 0.100 × 1000 = **100 mL**"]},
        {text:"Multiplying n × M instead of dividing gives 16 mL, and stopping at the moles (0.0400 read as litres) gives 40 mL.",calc:["0.0400 × 0.400 = 0.016 L = 16 mL ✗","0.0400 → 40 mL skips ÷ M ✗"],strike:["16 mL","40 mL"]},
        {text:"Skipping the grams-to-moles step divides grams by molarity.",calc:["2.34 ÷ 0.400 = 5.85 ✗"],strike:["5.85 L"]},
        {text:"Answer: 100 mL."}],
      trap:"Dividing grams by molarity: molarity is moles per litre, so the mass must become moles first."},
    teach:[{text:"First, **find the givens**.",marks:[{t:"2.34 g",note:"mass"},{t:"58.5 g/mol",note:"molar mass"},{t:"0.400 M",note:"mol per L"}]},
      {text:"**Grams → moles.**",calc:["n = mass ÷ molar mass"]},
      {text:"**Moles → litres → mL.** Rearrange M = n/V.",calc:["V = n ÷ M","mL = L × 1000"]},
      {text:"**Rule to reuse:** V = n ÷ M gives litres; convert grams to moles first and litres to mL at the end."}]},
];
